window.HT = window.HT || {}; HT.CDF = HT.CDF || {};
HT.CDF["G12"] = {"bang":[{"i":0,"tieu_de_bang":"Pác Bó – Cao Bằng","tieu_de":"Pác Bó 1941 – 1945: bốn năm ở đầu nguồn và con đường tới ngày độc lập","sapo":"Mùng 2 Tết Tân Tỵ, tức ngày 28/1/1941, một người đàn ông năm mươi tuổi mà bà con sau này quen gọi là Già Thu bước qua cột mốc biên giới 108 vào thung lũng Pác Bó. Hơn bốn năm sau, cũng từ thung lũng đầu nguồn ấy, Người lên đường về Tân Trào để lãnh đạo Tổng khởi nghĩa. Giữa hai mốc đó là một mặt trận, một tờ báo, một bài sử ca, những lớp học giữa rừng và đội quân chủ lực đầu tiên. Gian trưng bày này đưa bạn đi lại chặng đường ấy.","bia":{"src":"textures/bai/G12_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Một chuyến trở về vào ngày Tết","text":"Ngày 28/1/1941 là mùng 2 Tết Tân Tỵ. Ở các bản Tày, Nùng vùng Hà Quảng, Cao Bằng, người ta còn đang trong những ngày đầu năm mới. Đúng lúc ấy, một nhóm nhỏ lặng lẽ vượt qua cột mốc biên giới số 108, men theo lối mòn vào thung lũng Pác Bó, xã Trường Hà. Trong nhóm có một người đàn ông năm mươi tuổi mà bà con trong bản sẽ quen gọi là Già Thu, là ông Ké. Đó là Nguyễn Ái Quốc.\n\nNgười đã rời Tổ quốc từ năm 1911, khi còn là chàng thanh niên Nguyễn Tất Thành xuống tàu ở bến Nhà Rồng. Suốt gần ba mươi năm, Người đi qua nhiều châu lục, hoạt động ở Pháp, Liên Xô, Trung Quốc, Xiêm, bị chính quyền thực dân kết án tử hình vắng mặt, từng bị giam ở Hồng Kông. Chuyến trở về này khác mọi chuyến đi trước: Người về để ở lại, để trực tiếp lãnh đạo cách mạng ngay trên đất nước mình. Gian trưng bày Pác Bó – Cao Bằng kể về hơn bốn năm tiếp theo, từ bước chân qua cột mốc biên giới đến ngày 4/5/1945, khi Người rời Pác Bó về Tân Trào. Đó là những năm Người sống trong hang đá, lán nứa, giữa vòng tay che chở của đồng bào, và cũng là những năm chuẩn bị trực tiếp cho Cách mạng Tháng Tám.","doc":1},{"loai":"doan","tieu_de":"Năm 1940 và một quyết định không thể chậm trễ","text":"Muốn hiểu vì sao Người chọn về nước vào đầu năm 1941, phải nhìn lại năm 1940 đầy biến động. Tháng 6/1940, nước Pháp thua trận, ký đình chiến với phát xít Đức. Tháng 9/1940, quân Nhật đánh vào Lạng Sơn rồi đổ bộ lên Hải Phòng, chính quyền thực dân ở Đông Dương nhanh chóng chịu khuất phục. Nhân dân ta từ đây phải chịu cảnh “một cổ hai tròng”. Trong nước, các cuộc nổi dậy liên tiếp bùng lên: khởi nghĩa Bắc Sơn ngày 27/9/1940, khởi nghĩa Nam Kỳ ngày 23/11/1940, rồi binh biến Đô Lương đầu năm 1941. Các cuộc nổi dậy ấy bị đàn áp đẫm máu, nhưng cho thấy lòng dân đã sôi sục.\n\nLúc ấy, Nguyễn Ái Quốc đang ở Trung Quốc, tìm mọi cách bắt liên lạc với tổ chức Đảng trong nước. Theo hồi ký của Đại tướng Võ Nguyên Giáp, mùa hè năm 1940 ở Côn Minh, khi nghe tin Pháp mất nước, Người nhận định đây là cơ hội rất thuận lợi cho cách mạng Việt Nam. Phải tìm mọi cách về nước ngay để tranh thủ thời cơ. Những thanh niên đang trên đường sang Diên An học tập được gọi quay lại để chuẩn bị công việc mới. Từ đó, hướng đi đã rõ: tới vùng biên giới, dựng căn cứ ở trong nước.","doc":2},{"loai":"anh","src":"textures/bang_w/G12_0_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Pác Bó – Cao Bằng”, nhìn từ xa."},{"loai":"doan","tieu_de":"Vì sao là Cao Bằng?","text":"Người không chọn điểm về một cách ngẫu nhiên. Cao Bằng hội đủ ba điều kiện hiếm có. Thứ nhất là thế đất: núi đá vôi trùng điệp, nhiều hang động và rừng rậm, đường sá hiểm trở, kẻ địch khó kiểm soát. Thứ hai là vị trí: vùng Hà Quảng nằm sát biên giới, khi cần có thể lui sang bên kia, đồng thời thuận đường liên lạc với bên ngoài. Thứ ba, quan trọng nhất, là con người. Ngay từ năm 1930, chi bộ cộng sản đầu tiên của Cao Bằng đã ra đời ở Nặm Lìn, thuộc Hà Quảng. Qua những năm bị khủng bố gắt gao, phong trào ở đây vẫn được giữ gìn, đồng bào Tày, Nùng một lòng tin theo cách mạng.\n\nTheo hồi ký của Đại tướng Võ Nguyên Giáp, Người cho rằng căn cứ địa Cao Bằng sẽ mở ra triển vọng lớn cho cách mạng. Nhưng Người cũng lưu ý: từ Cao Bằng phải phát triển xuống Thái Nguyên, rồi nối với phong trào cả nước, như thế mới có thể tiến tới khởi nghĩa. Căn cứ không phải chỗ để náu mình, mà là bàn đạp để tiến ra. Tầm nhìn ấy về sau thành hiện thực trên con đường Nam tiến và trong Khu giải phóng Việt Bắc năm 1945. Còn Pác Bó, trong tiếng Tày nghĩa là “đầu nguồn”, trở thành nơi khởi phát của dòng chảy đó.","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_pac_bo.jpg","chu_thich":"Suối Lê-nin dưới chân núi Các Mác, vùng đầu nguồn Pác Bó, Cao Bằng. Ảnh chụp năm 2016.","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Chuẩn bị từ bên kia biên giới","text":"Cuối năm 1940, Người tới vùng Tĩnh Tây, tỉnh Quảng Tây, sát biên giới Cao Bằng. Tại đây, Người trực tiếp mở lớp huấn luyện ngắn ngày cho cán bộ từ Cao Bằng sang học. Học viên được giảng về tình hình thế giới và trong nước, về cách tổ chức quần chúng, cách tuyên truyền, cách giữ bí mật. Học xong, họ trở về các bản làng, gây dựng cơ sở và chuẩn bị nơi đón Người. Như vậy, trước khi bước qua cột mốc 108, Người đã có trong tay những cán bộ đầu tiên hiểu rõ đường lối, và một vùng đất đã sẵn lòng che chở.\n\nMọi việc được làm trong bí mật tuyệt đối. Người không dùng tên Nguyễn Ái Quốc, cái tên mà mật thám Pháp đã truy lùng hơn hai mươi năm. Với đồng bào, Người là một ông già hiền hậu, sống giản dị như mọi người trong bản. Những ngày đầu về nước, Người ở nhà ông Lý Quốc Súng trong bản Pác Bó, rồi từ ngày 8/2/1941 chuyển vào hang Cốc Bó. Về sau, khi cần tránh sự lùng sục của địch, Người còn ở hang Lũng Lạn và lán Khuổi Nặm gần đó. Sống lẫn trong dân, thay đổi chỗ ở khi cần, là tấm khiên đầu tiên của người lãnh đạo cách mạng.","doc":4},{"loai":"doan","tieu_de":"Sáng ra bờ suối, tối vào hang","text":"Cuộc sống ở Pác Bó kham khổ đến khó tin. Hang đá ẩm lạnh, những tháng đầu xuân vùng núi rét buốt, bữa ăn thường chỉ có cháo ngô, rau rừng, măng. Vậy mà người đứng đầu phong trào vẫn giữ một nhịp làm việc đều đặn: ban ngày ra bờ suối, ngồi bên phiến đá làm việc, tối lại về hang. Người đặt tên dòng suối trước hang là suối Lê-nin, ngọn núi phía sau là núi Các Mác. Người dịch cuốn Lịch sử Đảng Cộng sản (b) Liên Xô, soạn tài liệu, mở lớp huấn luyện cán bộ. Cảnh sống ấy đi vào bài thơ “Tức cảnh Pác Bó” với câu kết nổi tiếng: “Cuộc đời cách mạng thật là sang”.\n\nNhững câu chuyện ấy được kể kỹ ở các bảng khác trong gian. Đó là hai bảng ảnh tư liệu về hang Cốc Bó và suối Lê-nin, bảng Lời Bác về bài thơ bốn câu, cùng các bảng hiện vật về cột mốc 108, hang Cốc Bó, bàn đá và lán Khuổi Nặm. Ở bảng giới thiệu này, xin nhấn một điều: sự đối lập giữa điều kiện sống tối giản và tầm vóc công việc. Chính giữa những hang đá, lán nứa ấy, các chủ trương lớn nhất của cách mạng Việt Nam thời kỳ này đã được chuẩn bị.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_coc_bo.jpg","chu_thich":"Cửa hang Cốc Bó, nơi Nguyễn Ái Quốc ở từ ngày 8/2/1941. Ảnh chụp năm 2016.","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Khuổi Nặm và một cuộc chuyển hướng","text":"Tháng 5/1941, tại lán Khuổi Nặm, Người chủ trì Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng. Hội nghị hoàn chỉnh chủ trương chuyển hướng chỉ đạo chiến lược, đặt nhiệm vụ giải phóng dân tộc lên hàng đầu. Hội nghị quyết định thành lập Mặt trận Việt Nam Độc lập Đồng minh, tức Việt Minh, và xác định chuẩn bị khởi nghĩa vũ trang là nhiệm vụ trung tâm (xem chuyên đề Lán Khuổi Nặm). Ngày 6/6/1941, Người viết thư “Kính cáo đồng bào”, kêu gọi mọi người Việt Nam yêu nước đoàn kết đánh Pháp, đuổi Nhật.\n\nCao Bằng được chọn làm nơi thí điểm cuộc vận động xây dựng các hội Cứu quốc trong Mặt trận Việt Minh. Ngày 1/8/1941, báo Việt Nam độc lập do Người sáng lập ra số đầu tiên, lời lẽ giản dị để đồng bào ít chữ cũng hiểu được. Theo sách giáo khoa lịch sử, đến năm 1942, khắp các châu ở Cao Bằng đều có hội Cứu quốc, trong đó có ba “châu hoàn toàn”, nghĩa là hầu như làng nào cũng có tổ chức Việt Minh. Từ một thung lũng hẻo lánh sát biên giới, mạng lưới ấy lan dần ra khắp tỉnh rồi sang các tỉnh lân cận.","doc":6},{"loai":"ban_co_biet","text":"Mặt trận Việt Minh chính thức ra đời ngày 19/5/1941, đúng ngày sinh lần thứ 51 của Nguyễn Ái Quốc, khi Hội nghị Trung ương lần thứ tám do Người chủ trì kết thúc tại Khuổi Nặm.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","doc":7},{"loai":"trich","text":"Việc cứu quốc là việc chung. Ai là người Việt Nam đều phải kề vai gánh vác một phần trách nhiệm: người có tiền góp tiền, người có của góp của, người có sức góp sức, người có tài năng góp tài năng.","nguoi":"Nguyễn Ái Quốc","nguon_ten":"Thư “Kính cáo đồng bào”, 6/6/1941 – Hồ Chí Minh Toàn tập, tập 3, NXB Chính trị quốc gia, 2011","doc":8},{"loai":"doan","tieu_de":"Những năm xa cách và lần trở lại","text":"Tháng 8/1942, để tranh thủ sự giúp đỡ quốc tế cho cách mạng Việt Nam, Người lên đường sang Trung Quốc với cái tên mới: Hồ Chí Minh. Ngày 29/8/1942, Người bị chính quyền Tưởng Giới Thạch bắt ở Túc Vinh, tỉnh Quảng Tây, rồi bị giải qua nhiều nhà lao. Trong hơn một năm bị giam cầm, Người viết tập thơ chữ Hán “Nhật ký trong tù”. Theo hồi ký của Đại tướng Võ Nguyên Giáp, có lúc tin đồn Người đã mất trong tù truyền về căn cứ, khiến anh em vô cùng đau buồn. Ngày 10/9/1943, Người được trả tự do, rồi hoạt động một thời gian ở Liễu Châu.\n\nTrong những năm Người vắng mặt, phong trào ở Cao Bằng không dừng lại. Ủy ban Việt Minh liên tỉnh Cao – Bắc – Lạng lập ra các ban “xung phong Nam tiến”, mở đường xuống phía nam, nối vùng căn cứ Cao Bằng với căn cứ Bắc Sơn – Võ Nhai. Tháng 9/1944, Người trở lại Pác Bó. Lúc ấy, Liên tỉnh ủy Cao – Bắc – Lạng đang chuẩn bị phát động khởi nghĩa vũ trang. Người phân tích tình hình và đề nghị hoãn lại, vì thời cơ trong cả nước chưa tới. Thay vào đó, Người chỉ thị thành lập một đội vũ trang tập trung, câu chuyện được kể ở chuyên đề “34 chiến sĩ đầu tiên”.","doc":9},{"loai":"anh","src":"textures/bang_w/G12_0_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Pác Bó – Cao Bằng”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Từ Pác Bó về Tân Trào","text":"Đầu năm 1945, Người sang Côn Minh, Trung Quốc, tìm cách liên lạc với lực lượng Đồng minh đang chống phát xít. Ngày 9/3/1945, Nhật đảo chính lật đổ Pháp trên toàn cõi Đông Dương, thời cơ cách mạng tới gần từng ngày. Cuối tháng 4/1945, Người trở về Pác Bó. Ngày 4/5/1945, Người rời Pác Bó, bắt đầu hành trình về phía nam. Trên đường, Người dừng ở căn cứ Lam Sơn của Cao Bằng, rồi qua các vùng Ngân Sơn, Chợ Rã, Chợ Đồn. Từ ngày 17 đến 19/5/1945, tại Nà Kiến, Người gặp Võ Nguyên Giáp, nghe báo cáo tình hình. Ngày 21/5/1945, Người tới Tân Trào, tỉnh Tuyên Quang.\n\nTân Trào sẽ là nơi Người chỉ đạo Tổng khởi nghĩa, đúng với tầm nhìn từ những ngày đầu ở Cao Bằng: căn cứ phải phát triển xuống phía nam, tới gần trung tâm của cả nước. Ngày 4/6/1945, Khu giải phóng Việt Bắc chính thức được thành lập, gồm hầu hết các tỉnh Cao Bằng, Bắc Kạn, Lạng Sơn, Hà Giang, Tuyên Quang, Thái Nguyên. Chưa đầy ba tháng sau, Cách mạng Tháng Tám thành công. Ngày 2/9/1945, tại Quảng trường Ba Đình, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa.","doc":10},{"loai":"anh","src":"textures/bang_w/G12_0_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Pác Bó – Cao Bằng”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, Khu di tích lịch sử Pác Bó nằm ở vùng Hà Quảng, cách thành phố Cao Bằng khoảng năm mươi cây số. Quần thể di tích được chia thành ba cụm. Cụm đầu nguồn gồm hang Cốc Bó, nền nhà ông Lý Quốc Súng, hang Lũng Lạn, suối Lê-nin và cột mốc 108, nay mang số hiệu 675. Khu trung tâm có Nhà tưởng niệm Chủ tịch Hồ Chí Minh khánh thành năm 2011 và cánh đồng Nà Chang, nơi Người gặp gỡ đồng bào khi về thăm lại Pác Bó ngày 20/2/1961. Cụm Khuổi Nặm có chiếc lán chính rộng khoảng mười hai mét vuông, đã được phục dựng, cùng hai lán phụ dùng để giữ an toàn.\n\nTrong gian trưng bày 3D này, các góc dựng lại cảnh hang đá, bàn đá bên suối và lán nứa Khuổi Nặm. Khách có thể bắt đầu từ bảng giới thiệu, đi theo bảng mốc thời gian, rồi dừng ở từng bảng câu chuyện và hiện vật. Những đồ vật minh họa đặt quanh các góc, như chiếc hòm gỗ, chiếc bát, ngọn đèn dầu, gợi lại nếp sinh hoạt đơn sơ của những năm ấy. Mỗi bảng dẫn tới một lát cắt có thật của bốn năm ở đầu nguồn, nơi con đường tới ngày độc lập bắt đầu.","doc":11},{"loai":"ban_co_biet","text":"Ngày 10/5/2012, theo Quyết định số 548/QĐ-TTg của Thủ tướng Chính phủ, Di tích lịch sử Pác Bó được xếp hạng di tích quốc gia đặc biệt. Riêng hang Cốc Bó rộng khoảng 80 mét vuông, còn hang Lũng Lạn gần đó rộng khoảng 50 mét vuông.","nguon_ten":"Cục Di sản văn hóa, “Di tích lịch sử Pác Bó” – https://dsvh.gov.vn/di-tich-lich-su-pac-bo-2950","doc":12}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, tập 3, NXB Chính trị quốc gia, 2011","Võ Nguyên Giáp, Những năm tháng không thể nào quên; Từ nhân dân mà ra (hồi ký)","Cục Di sản văn hóa, “Di tích lịch sử Pác Bó” – https://dsvh.gov.vn/di-tich-lich-su-pac-bo-2950","Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch, “Hồ Chí Minh chặng đường từ Pác Bó về Tân Trào” – https://nhasanbacho.vn/bai-viet/ho-chi-minh-chang-duong-tu-pac-bo-ve-tan-trao/","Sách giáo khoa Lịch sử 9, NXB Giáo dục Việt Nam"],"doc":[{"t":"Pác Bó 1941 – 1945: bốn năm ở đầu nguồn và con đường tới ngày độc lập. Mùng 2 Tết Tân Tỵ, tức ngày 28/1/1941, một người đàn ông năm mươi tuổi mà bà con sau này quen gọi là Già Thu bước qua cột mốc biên giới 108 vào thung lũng Pác Bó. Hơn bốn năm sau, cũng từ thung lũng đầu nguồn ấy, Người lên đường về Tân Trào để lãnh đạo Tổng khởi nghĩa. Giữa hai mốc đó là một mặt trận, một tờ báo, một bài sử ca, những lớp học giữa rừng và đội quân chủ lực đầu tiên. Gian trưng bày này đưa bạn đi lại chặng đường ấy."},{"t":"Một chuyến trở về vào ngày Tết. Ngày 28/1/1941 là mùng 2 Tết Tân Tỵ. Ở các bản Tày, Nùng vùng Hà Quảng, Cao Bằng, người ta còn đang trong những ngày đầu năm mới. Đúng lúc ấy, một nhóm nhỏ lặng lẽ vượt qua cột mốc biên giới số 108, men theo lối mòn vào thung lũng Pác Bó, xã Trường Hà. Trong nhóm có một người đàn ông năm mươi tuổi mà bà con trong bản sẽ quen gọi là Già Thu, là ông Ké. Đó là Nguyễn Ái Quốc. Người đã rời Tổ quốc từ năm 1911, khi còn là chàng thanh niên Nguyễn Tất Thành xuống tàu ở bến Nhà Rồng. Suốt gần ba mươi năm, Người đi qua nhiều châu lục, hoạt động ở Pháp, Liên Xô, Trung Quốc, Xiêm, bị chính quyền thực dân kết án tử hình vắng mặt, từng bị giam ở Hồng Kông. Chuyến trở về này khác mọi chuyến đi trước: Người về để ở lại, để trực tiếp lãnh đạo cách mạng ngay trên đất nước mình. Gian trưng bày Pác Bó – Cao Bằng kể về hơn bốn năm tiếp theo, từ bước chân qua cột mốc biên giới đến ngày 4/5/1945, khi Người rời Pác Bó về Tân Trào. Đó là những năm Người sống trong hang đá, lán nứa, giữa vòng tay che chở của đồng bào, và cũng là những năm chuẩn bị trực tiếp cho Cách mạng Tháng Tám."},{"t":"Năm 1940 và một quyết định không thể chậm trễ. Muốn hiểu vì sao Người chọn về nước vào đầu năm 1941, phải nhìn lại năm 1940 đầy biến động. Tháng 6/1940, nước Pháp thua trận, ký đình chiến với phát xít Đức. Tháng 9/1940, quân Nhật đánh vào Lạng Sơn rồi đổ bộ lên Hải Phòng, chính quyền thực dân ở Đông Dương nhanh chóng chịu khuất phục. Nhân dân ta từ đây phải chịu cảnh “một cổ hai tròng”. Trong nước, các cuộc nổi dậy liên tiếp bùng lên: khởi nghĩa Bắc Sơn ngày 27/9/1940, khởi nghĩa Nam Kỳ ngày 23/11/1940, rồi binh biến Đô Lương đầu năm 1941. Các cuộc nổi dậy ấy bị đàn áp đẫm máu, nhưng cho thấy lòng dân đã sôi sục. Lúc ấy, Nguyễn Ái Quốc đang ở Trung Quốc, tìm mọi cách bắt liên lạc với tổ chức Đảng trong nước. Theo hồi ký của Đại tướng Võ Nguyên Giáp, mùa hè năm 1940 ở Côn Minh, khi nghe tin Pháp mất nước, Người nhận định đây là cơ hội rất thuận lợi cho cách mạng Việt Nam. Phải tìm mọi cách về nước ngay để tranh thủ thời cơ. Những thanh niên đang trên đường sang Diên An học tập được gọi quay lại để chuẩn bị công việc mới. Từ đó, hướng đi đã rõ: tới vùng biên giới, dựng căn cứ ở trong nước."},{"t":"Vì sao là Cao Bằng?. Người không chọn điểm về một cách ngẫu nhiên. Cao Bằng hội đủ ba điều kiện hiếm có. Thứ nhất là thế đất: núi đá vôi trùng điệp, nhiều hang động và rừng rậm, đường sá hiểm trở, kẻ địch khó kiểm soát. Thứ hai là vị trí: vùng Hà Quảng nằm sát biên giới, khi cần có thể lui sang bên kia, đồng thời thuận đường liên lạc với bên ngoài. Thứ ba, quan trọng nhất, là con người. Ngay từ năm 1930, chi bộ cộng sản đầu tiên của Cao Bằng đã ra đời ở Nặm Lìn, thuộc Hà Quảng. Qua những năm bị khủng bố gắt gao, phong trào ở đây vẫn được giữ gìn, đồng bào Tày, Nùng một lòng tin theo cách mạng. Theo hồi ký của Đại tướng Võ Nguyên Giáp, Người cho rằng căn cứ địa Cao Bằng sẽ mở ra triển vọng lớn cho cách mạng. Nhưng Người cũng lưu ý: từ Cao Bằng phải phát triển xuống Thái Nguyên, rồi nối với phong trào cả nước, như thế mới có thể tiến tới khởi nghĩa. Căn cứ không phải chỗ để náu mình, mà là bàn đạp để tiến ra. Tầm nhìn ấy về sau thành hiện thực trên con đường Nam tiến và trong Khu giải phóng Việt Bắc năm 1945. Còn Pác Bó, trong tiếng Tày nghĩa là “đầu nguồn”, trở thành nơi khởi phát của dòng chảy đó."},{"t":"Chuẩn bị từ bên kia biên giới. Cuối năm 1940, Người tới vùng Tĩnh Tây, tỉnh Quảng Tây, sát biên giới Cao Bằng. Tại đây, Người trực tiếp mở lớp huấn luyện ngắn ngày cho cán bộ từ Cao Bằng sang học. Học viên được giảng về tình hình thế giới và trong nước, về cách tổ chức quần chúng, cách tuyên truyền, cách giữ bí mật. Học xong, họ trở về các bản làng, gây dựng cơ sở và chuẩn bị nơi đón Người. Như vậy, trước khi bước qua cột mốc 108, Người đã có trong tay những cán bộ đầu tiên hiểu rõ đường lối, và một vùng đất đã sẵn lòng che chở. Mọi việc được làm trong bí mật tuyệt đối. Người không dùng tên Nguyễn Ái Quốc, cái tên mà mật thám Pháp đã truy lùng hơn hai mươi năm. Với đồng bào, Người là một ông già hiền hậu, sống giản dị như mọi người trong bản. Những ngày đầu về nước, Người ở nhà ông Lý Quốc Súng trong bản Pác Bó, rồi từ ngày 8/2/1941 chuyển vào hang Cốc Bó. Về sau, khi cần tránh sự lùng sục của địch, Người còn ở hang Lũng Lạn và lán Khuổi Nặm gần đó. Sống lẫn trong dân, thay đổi chỗ ở khi cần, là tấm khiên đầu tiên của người lãnh đạo cách mạng."},{"t":"Sáng ra bờ suối, tối vào hang. Cuộc sống ở Pác Bó kham khổ đến khó tin. Hang đá ẩm lạnh, những tháng đầu xuân vùng núi rét buốt, bữa ăn thường chỉ có cháo ngô, rau rừng, măng. Vậy mà người đứng đầu phong trào vẫn giữ một nhịp làm việc đều đặn: ban ngày ra bờ suối, ngồi bên phiến đá làm việc, tối lại về hang. Người đặt tên dòng suối trước hang là suối Lê-nin, ngọn núi phía sau là núi Các Mác. Người dịch cuốn Lịch sử Đảng Cộng sản (b) Liên Xô, soạn tài liệu, mở lớp huấn luyện cán bộ. Cảnh sống ấy đi vào bài thơ “Tức cảnh Pác Bó” với câu kết nổi tiếng: “Cuộc đời cách mạng thật là sang”. Những câu chuyện ấy được kể kỹ ở các bảng khác trong gian. Đó là hai bảng ảnh tư liệu về hang Cốc Bó và suối Lê-nin, bảng Lời Bác về bài thơ bốn câu, cùng các bảng hiện vật về cột mốc 108, hang Cốc Bó, bàn đá và lán Khuổi Nặm. Ở bảng giới thiệu này, xin nhấn một điều: sự đối lập giữa điều kiện sống tối giản và tầm vóc công việc. Chính giữa những hang đá, lán nứa ấy, các chủ trương lớn nhất của cách mạng Việt Nam thời kỳ này đã được chuẩn bị."},{"t":"Khuổi Nặm và một cuộc chuyển hướng. Tháng 5/1941, tại lán Khuổi Nặm, Người chủ trì Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng. Hội nghị hoàn chỉnh chủ trương chuyển hướng chỉ đạo chiến lược, đặt nhiệm vụ giải phóng dân tộc lên hàng đầu. Hội nghị quyết định thành lập Mặt trận Việt Nam Độc lập Đồng minh, tức Việt Minh, và xác định chuẩn bị khởi nghĩa vũ trang là nhiệm vụ trung tâm (xem chuyên đề Lán Khuổi Nặm). Ngày 6/6/1941, Người viết thư “Kính cáo đồng bào”, kêu gọi mọi người Việt Nam yêu nước đoàn kết đánh Pháp, đuổi Nhật. Cao Bằng được chọn làm nơi thí điểm cuộc vận động xây dựng các hội Cứu quốc trong Mặt trận Việt Minh. Ngày 1/8/1941, báo Việt Nam độc lập do Người sáng lập ra số đầu tiên, lời lẽ giản dị để đồng bào ít chữ cũng hiểu được. Theo sách giáo khoa lịch sử, đến năm 1942, khắp các châu ở Cao Bằng đều có hội Cứu quốc, trong đó có ba “châu hoàn toàn”, nghĩa là hầu như làng nào cũng có tổ chức Việt Minh. Từ một thung lũng hẻo lánh sát biên giới, mạng lưới ấy lan dần ra khắp tỉnh rồi sang các tỉnh lân cận."},{"t":"Bạn có biết? Mặt trận Việt Minh chính thức ra đời ngày 19/5/1941, đúng ngày sinh lần thứ 51 của Nguyễn Ái Quốc, khi Hội nghị Trung ương lần thứ tám do Người chủ trì kết thúc tại Khuổi Nặm."},{"t":"Việc cứu quốc là việc chung. Ai là người Việt Nam đều phải kề vai gánh vác một phần trách nhiệm: người có tiền góp tiền, người có của góp của, người có sức góp sức, người có tài năng góp tài năng. — Nguyễn Ái Quốc"},{"t":"Những năm xa cách và lần trở lại. Tháng 8/1942, để tranh thủ sự giúp đỡ quốc tế cho cách mạng Việt Nam, Người lên đường sang Trung Quốc với cái tên mới: Hồ Chí Minh. Ngày 29/8/1942, Người bị chính quyền Tưởng Giới Thạch bắt ở Túc Vinh, tỉnh Quảng Tây, rồi bị giải qua nhiều nhà lao. Trong hơn một năm bị giam cầm, Người viết tập thơ chữ Hán “Nhật ký trong tù”. Theo hồi ký của Đại tướng Võ Nguyên Giáp, có lúc tin đồn Người đã mất trong tù truyền về căn cứ, khiến anh em vô cùng đau buồn. Ngày 10/9/1943, Người được trả tự do, rồi hoạt động một thời gian ở Liễu Châu. Trong những năm Người vắng mặt, phong trào ở Cao Bằng không dừng lại. Ủy ban Việt Minh liên tỉnh Cao – Bắc – Lạng lập ra các ban “xung phong Nam tiến”, mở đường xuống phía nam, nối vùng căn cứ Cao Bằng với căn cứ Bắc Sơn – Võ Nhai. Tháng 9/1944, Người trở lại Pác Bó. Lúc ấy, Liên tỉnh ủy Cao – Bắc – Lạng đang chuẩn bị phát động khởi nghĩa vũ trang. Người phân tích tình hình và đề nghị hoãn lại, vì thời cơ trong cả nước chưa tới. Thay vào đó, Người chỉ thị thành lập một đội vũ trang tập trung, câu chuyện được kể ở chuyên đề “34 chiến sĩ đầu tiên”."},{"t":"Từ Pác Bó về Tân Trào. Đầu năm 1945, Người sang Côn Minh, Trung Quốc, tìm cách liên lạc với lực lượng Đồng minh đang chống phát xít. Ngày 9/3/1945, Nhật đảo chính lật đổ Pháp trên toàn cõi Đông Dương, thời cơ cách mạng tới gần từng ngày. Cuối tháng 4/1945, Người trở về Pác Bó. Ngày 4/5/1945, Người rời Pác Bó, bắt đầu hành trình về phía nam. Trên đường, Người dừng ở căn cứ Lam Sơn của Cao Bằng, rồi qua các vùng Ngân Sơn, Chợ Rã, Chợ Đồn. Từ ngày 17 đến 19/5/1945, tại Nà Kiến, Người gặp Võ Nguyên Giáp, nghe báo cáo tình hình. Ngày 21/5/1945, Người tới Tân Trào, tỉnh Tuyên Quang. Tân Trào sẽ là nơi Người chỉ đạo Tổng khởi nghĩa, đúng với tầm nhìn từ những ngày đầu ở Cao Bằng: căn cứ phải phát triển xuống phía nam, tới gần trung tâm của cả nước. Ngày 4/6/1945, Khu giải phóng Việt Bắc chính thức được thành lập, gồm hầu hết các tỉnh Cao Bằng, Bắc Kạn, Lạng Sơn, Hà Giang, Tuyên Quang, Thái Nguyên. Chưa đầy ba tháng sau, Cách mạng Tháng Tám thành công. Ngày 2/9/1945, tại Quảng trường Ba Đình, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa."},{"t":"Dấu tích hôm nay. Ngày nay, Khu di tích lịch sử Pác Bó nằm ở vùng Hà Quảng, cách thành phố Cao Bằng khoảng năm mươi cây số. Quần thể di tích được chia thành ba cụm. Cụm đầu nguồn gồm hang Cốc Bó, nền nhà ông Lý Quốc Súng, hang Lũng Lạn, suối Lê-nin và cột mốc 108, nay mang số hiệu 675. Khu trung tâm có Nhà tưởng niệm Chủ tịch Hồ Chí Minh khánh thành năm 2011 và cánh đồng Nà Chang, nơi Người gặp gỡ đồng bào khi về thăm lại Pác Bó ngày 20/2/1961. Cụm Khuổi Nặm có chiếc lán chính rộng khoảng mười hai mét vuông, đã được phục dựng, cùng hai lán phụ dùng để giữ an toàn. Trong gian trưng bày 3D này, các góc dựng lại cảnh hang đá, bàn đá bên suối và lán nứa Khuổi Nặm. Khách có thể bắt đầu từ bảng giới thiệu, đi theo bảng mốc thời gian, rồi dừng ở từng bảng câu chuyện và hiện vật. Những đồ vật minh họa đặt quanh các góc, như chiếc hòm gỗ, chiếc bát, ngọn đèn dầu, gợi lại nếp sinh hoạt đơn sơ của những năm ấy. Mỗi bảng dẫn tới một lát cắt có thật của bốn năm ở đầu nguồn, nơi con đường tới ngày độc lập bắt đầu."},{"t":"Bạn có biết? Ngày 10/5/2012, theo Quyết định số 548/QĐ-TTg của Thủ tướng Chính phủ, Di tích lịch sử Pác Bó được xếp hạng di tích quốc gia đặc biệt. Riêng hang Cốc Bó rộng khoảng 80 mét vuông, còn hang Lũng Lạn gần đó rộng khoảng 50 mét vuông."}],"so_chu":2263},{"i":1,"tieu_de_bang":"“Lịch sử nước ta” và dự báo năm 1945","tieu_de":"“Dân ta phải biết sử ta”: tập sử ca viết ở Cao Bằng và dòng chữ “1945 – Việt Nam độc lập”","sapo":"Đầu năm 1942, khi nước ta còn chìm dưới ách Pháp – Nhật, Việt Minh phát hành một tập sách nhỏ kể lịch sử dân tộc bằng thơ lục bát. Ở trang cuối, trong bảng những năm quan trọng, tác giả ghi một mốc chưa hề xảy ra: “1945 – Việt Nam độc lập”. Ba năm sau, dòng chữ ấy thành sự thật. Tác giả là Nguyễn Ái Quốc, khi ấy đang sống giữa núi rừng Cao Bằng.","bia":{"src":"textures/bai/G12_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Một dòng chữ đi trước lịch sử","text":"Hãy hình dung một người nông dân ở vùng căn cứ Cao Bằng đầu năm 1942, lần đầu cầm trên tay tập sách mỏng do cán bộ Việt Minh mang tới. Sách do Việt Minh tuyên truyền bộ xuất bản. Bên trong là một bài diễn ca dài bằng thơ lục bát, kể chuyện nước nhà từ buổi tổ tiên dựng nước. Lật tới cuối, người đọc gặp bảng “Những năm quan trọng”, ghi các mốc lớn trong lịch sử dân tộc. Các mốc nối nhau tới năm 1941. Rồi đến dòng cuối cùng: “1945 – Việt Nam độc lập”.\n\nNăm ấy, nước ta vẫn nằm dưới ách thống trị của thực dân Pháp và phát xít Nhật. Mặt trận Việt Minh mới ra đời chưa đầy một năm. Lực lượng vũ trang cách mạng mới chỉ là những nhóm du kích nhỏ, vũ khí thô sơ. Không ai biết chắc cuộc chiến tranh thế giới sẽ kết thúc vào lúc nào. Vậy mà tác giả tập sách, Nguyễn Ái Quốc, đã ghi một năm cụ thể. Chuyên đề này kể về tập sách nhỏ ấy: vì sao nó được viết, và nó nói gì với đồng bào. Chuyên đề cũng lý giải vì sao dòng chữ cuối cùng lại trở thành một trong những lời dự báo nổi tiếng nhất của lịch sử Việt Nam hiện đại.","doc":1},{"loai":"doan","tieu_de":"Căn cứ cần những trang sách dễ hiểu","text":"Sau Hội nghị Trung ương lần thứ tám tháng 5/1941, việc lớn nhất ở vùng căn cứ là đưa đường lối của Việt Minh tới từng bản làng. Nhưng đồng bào nơi đây phần đông là nông dân các dân tộc Tày, Nùng, Dao, nhiều người không biết chữ, có người chưa thạo tiếng Kinh. Những văn kiện dài, lời lẽ lý luận khó lòng đi vào đời sống của họ. Cán bộ cần những tài liệu ngắn, dễ nhớ, có thể đọc to trong các buổi họp, học thuộc rồi truyền miệng từ người này sang người khác.\n\nNguyễn Ái Quốc tự tay làm công việc ấy. Ngoài việc dịch sách và soạn tài liệu huấn luyện, Người viết bài cho báo Việt Nam độc lập, ra số đầu ngày 1/8/1941, với lối viết ngắn gọn, giản dị. Người còn viết nhiều bài ca vận động bằng thơ, như “Ca sợi chỉ”, mượn hình ảnh sợi chỉ yếu ớt khi đứng riêng nhưng bền chắc khi dệt thành tấm vải để nói về sức mạnh đoàn kết. Bài diễn ca “Lịch sử nước ta” ra đời trong mạch công việc đó. Người viết năm 1941, và tháng 2/1942, Việt Minh tuyên truyền bộ in thành sách để phát hành rộng rãi trong vùng căn cứ và các nơi có cơ sở cách mạng.","doc":2},{"loai":"anh","src":"textures/bang_w/G12_1_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc ““Lịch sử nước ta” và dự báo năm 1945”, nhìn từ xa."},{"loai":"doan","tieu_de":"Vì sao chọn thể thơ lục bát?","text":"Lục bát là thể thơ quen thuộc nhất của người Việt. Câu sáu chữ nối câu tám chữ, vần gieo đều đặn, nhịp chẵn dễ đọc, dễ ngâm. Từ những câu ca dao mẹ ru con đến những truyện thơ dài, lục bát đã nuôi dưỡng trí nhớ dân gian qua nhiều thế kỷ. Một người không biết chữ vẫn có thể thuộc hàng trăm câu lục bát nếu được nghe đọc nhiều lần. Chọn lục bát để kể lịch sử, Nguyễn Ái Quốc biến những trang sử khô khan thành lời ca có thể theo người nông dân ra đồng, lên nương, tới những buổi sinh hoạt của hội Cứu quốc.\n\nCách làm này cũng tiếp nối một truyền thống cũ. Ở thế kỷ XIX, các nhà nho đã soạn “Đại Nam quốc sử diễn ca”, kể lịch sử nước nhà bằng thơ lục bát để người học dễ nhớ. Điểm mới ở tác phẩm của Nguyễn Ái Quốc nằm ở mục đích: không chỉ để học thuộc, mà để thức tỉnh. Kể lại quá khứ, bài thơ hướng người đọc tới những câu hỏi của hiện tại: một dân tộc từng nhiều lần đánh thắng ngoại xâm vì sao nay lại mất nước, và phải làm gì để giành lại độc lập.","doc":3},{"loai":"trich","text":"Dân ta phải biết sử ta / Cho tường gốc tích nước nhà Việt Nam / Kể năm hơn bốn ngàn năm / Tổ tiên rực rỡ, anh em thuận hòa.","nguoi":"Nguyễn Ái Quốc","nguon_ten":"Lịch sử nước ta (1941), Việt Minh tuyên truyền bộ xuất bản tháng 2/1942 – Hồ Chí Minh Toàn tập, tập 3","doc":4},{"loai":"doan","tieu_de":"Bốn câu mở đầu","text":"Bài diễn ca mở đầu bằng bốn câu nay đã trở thành lời nhắc của nhiều thế hệ. Câu đầu tiên đặt ra một yêu cầu chứ không phải một lời khuyên: dân ta “phải biết” sử ta. Biết sử ở đây không phải để thuộc tên vua, năm trị vì, mà để “cho tường gốc tích nước nhà”, tức là hiểu cội nguồn của chính mình. Hai câu tiếp theo khẳng định bề dày “hơn bốn ngàn năm” và dừng lại ở hai chữ “thuận hòa”. Ngay từ những dòng đầu, tinh thần đoàn kết đã được đặt làm nền cho toàn bộ câu chuyện phía sau.\n\nVới người đọc năm 1942, bốn câu ấy mang một thông điệp rất rõ. Thực dân Pháp chia đất nước thành ba kỳ với những chế độ cai trị khác nhau, cố làm phai nhạt ý thức về một dân tộc thống nhất. Nhắc rằng người Việt có chung một gốc tích, một bề dày hơn bốn nghìn năm, là cách khơi dậy lòng tự hào và ý thức cộng đồng từ Bắc chí Nam. Người đọc được mời nhìn mình không phải như một người dân thuộc địa, mà như con cháu của một dân tộc có lịch sử vẻ vang.","doc":5},{"loai":"anh","src":"textures/bang_w/G12_1_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc ““Lịch sử nước ta” và dự báo năm 1945”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Qua các triều đại, một bài học xuyên suốt","text":"Từ buổi dựng nước, bài diễn ca đưa người đọc đi qua các thời kỳ: cuộc khởi nghĩa của Hai Bà Trưng, những chiến công chống ngoại xâm dưới các triều Lý, Trần, Lê, rồi tới khi nước ta bị thực dân Pháp xâm chiếm. Các nhân vật lịch sử được kể bằng lời thơ mộc mạc, gần với lời ăn tiếng nói hằng ngày, đọc lên là hiểu, không cần chú giải. Phần cuối bài dẫn câu chuyện tới những năm gần với lúc viết, để người đọc thấy mạch yêu nước chưa bao giờ đứt.\n\nĐiều bài thơ muốn đồng bào rút ra là sức mạnh của đoàn kết. Bài học ấy được gói lại trong hai câu thơ nổi tiếng: “Dân ta xin nhớ chữ đồng: / Đồng tình, đồng sức, đồng lòng, đồng minh!”. Bốn chữ “đồng” nối nhau dồn dập như bốn nhịp trống. Chữ cuối cùng, “đồng minh”, còn gợi chính tên gọi Việt Nam Độc lập Đồng minh, tức Mặt trận Việt Minh vừa ra đời. Bài học lịch sử vì thế dẫn thẳng tới lời kêu gọi của hiện tại: đồng lòng đứng vào hàng ngũ Việt Minh để cùng nhau giành lại độc lập.","doc":6},{"loai":"doan","tieu_de":"Trang “Những năm quan trọng”","text":"Sau phần diễn ca là bảng “Những năm quan trọng”. Đây là một bảng niên biểu thu gọn, ghi các sự kiện lớn của lịch sử dân tộc từ những năm xa xưa trước Công nguyên cho đến năm 1941. Với người đọc ít chữ, một bảng mốc như thế giúp họ hình dung lịch sử như một dòng chảy liên tục, có trước có sau. Đó cũng là cách Nguyễn Ái Quốc thường làm trong các tài liệu huấn luyện: giản lược, rõ ràng, dễ ghi nhớ.\n\nDòng cuối cùng của bảng không ghi một sự kiện đã qua. Nó ghi: “1945 – Việt Nam độc lập”. Đặt dòng ấy vào cuối một bảng niên biểu là một cách viết đầy chủ ý. Mọi sự kiện phía trên đều đã xảy ra, được sử sách ghi nhận. Dòng cuối cùng đứng chung hàng với chúng, như thể cũng là một điều đã được định trước. Người đọc năm 1942 cầm tập sách lên sẽ thấy độc lập không còn là một giấc mơ mơ hồ, mà là một đích đến có năm tháng cụ thể, gần tới mức có thể đếm được.","doc":7},{"loai":"ban_co_biet","text":"Bài diễn ca “Lịch sử nước ta” gồm 208 câu thơ lục bát. Bảng “Những năm quan trọng” in kèm ghi các sự kiện lớn tới năm 1941, rồi vượt qua bốn năm chưa tới để kết thúc bằng mốc “1945 Việt Nam độc lập”.","nguon_ten":"Báo Nhân Dân, “80 năm tác phẩm Lịch sử nước ta của Chủ tịch Hồ Chí Minh” – https://nhandan.vn/80-nam-tac-pham-lich-su-nuoc-ta-cua-chu-tich-ho-chi-minh-post727707.html","doc":8},{"loai":"doan","tieu_de":"Mùa thu 1944: lời dự báo thứ hai","text":"Gần ba năm sau, Người lại đưa ra một dự báo về thời gian, lần này còn cụ thể hơn. Tháng 9/1944, sau hơn một năm bị giam trong các nhà lao ở Quảng Tây và một thời gian hoạt động ở Liễu Châu, Người trở lại Pác Bó. Thế giới lúc ấy đã khác hẳn. Hồng quân Liên Xô đang tiến về phía tây, quân Đồng minh đổ bộ lên nước Pháp tháng 6/1944, Pa-ri được giải phóng tháng 8/1944. Ở Đông Dương, mâu thuẫn giữa Nhật và chính quyền thực dân Pháp ngày càng gay gắt.\n\nTháng 10/1944, Người viết thư gửi đồng bào toàn quốc, đề nghị chuẩn bị triệu tập một đại hội đại biểu quốc dân và nêu một nhận định về thời cơ. Cùng thời gian ấy, Người đề nghị hoãn cuộc khởi nghĩa mà Liên tỉnh ủy Cao – Bắc – Lạng đang chuẩn bị (xem chuyên đề “34 chiến sĩ đầu tiên”). Hai việc tưởng như trái chiều thực ra cùng một lôgic: kìm lại một cuộc nổi dậy non ở vài tỉnh, nhưng thúc giục cả nước khẩn trương chuẩn bị cho một thời cơ lớn đang tới gần.","doc":9},{"loai":"trich","text":"Cơ hội cho dân tộc ta giải phóng chỉ ở trong một năm hoặc năm rưỡi nữa. Thời gian rất gấp. Ta phải làm nhanh!","nguoi":"Hồ Chí Minh","nguon_ten":"Thư gửi đồng bào toàn quốc, tháng 10/1944 – Hồ Chí Minh Toàn tập, tập 3, NXB Chính trị quốc gia, 2011","doc":10},{"loai":"anh","src":"textures/bai/G12_v3.jpg","chu_thich":"Không gian 3D tái hiện gian Pác Bó – Cao Bằng, vùng căn cứ nơi Người viết nhiều tài liệu tuyên truyền trong những năm 1941 – 1942.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Dự báo từ đâu mà có?","text":"Người đời sau thường gọi hai lời dự báo ấy là “tiên tri”. Nhưng chúng không phải những lời đoán may rủi. Ngay từ khi Chiến tranh thế giới thứ hai bùng nổ, Đảng đã nhận định cuộc chiến sẽ làm suy yếu các thế lực đế quốc, tạo thời cơ cho các dân tộc thuộc địa vùng lên. Hội nghị Trung ương lần thứ tám tháng 5/1941 do Người chủ trì xác định chuẩn bị khởi nghĩa vũ trang là nhiệm vụ trung tâm, phải sẵn sàng khi thời cơ đến. Ở Pác Bó, dù sống giữa núi rừng, Người vẫn theo dõi diễn biến chiến sự qua những tờ báo, những tin tức mà cán bộ liên lạc mang về.\n\nLời dự báo năm 1945 vì vậy dựa trên một phép tính chiến lược. Phe phát xít sớm muộn sẽ thua. Khi Nhật suy yếu, Pháp và Nhật sẽ xung đột với nhau ở Đông Dương. Nếu đến lúc ấy dân tộc ta đã có tổ chức, có lực lượng, thì có thể vùng lên giành chính quyền. Viết “1945” vào cuối bảng niên biểu vừa là kết quả của phép tính ấy, vừa là một mục tiêu đặt ra để cả phong trào hướng tới. Dự báo và hành động gắn chặt với nhau: nói trước năm độc lập, rồi dồn sức làm cho năm ấy thành sự thật.","doc":11},{"loai":"anh","src":"textures/bang_w/G12_1_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc ““Lịch sử nước ta” và dự báo năm 1945”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Năm 1945: khi dòng chữ thành hiện thực","text":"Diễn biến năm 1945 khớp với phép tính ấy một cách lạ lùng. Ngày 9/3/1945, Nhật đảo chính lật đổ Pháp. Ngày 15/8/1945, Nhật tuyên bố đầu hàng Đồng minh. Ngay trong những ngày ấy, tại Tân Trào, Hội nghị toàn quốc của Đảng quyết định Tổng khởi nghĩa, Quốc dân Đại hội thông qua lệnh khởi nghĩa và bầu ra Ủy ban Dân tộc giải phóng Việt Nam. Ngày 19/8, Hà Nội giành chính quyền; chỉ trong khoảng nửa tháng, cuộc khởi nghĩa thắng lợi trên cả nước. Ngày 2/9/1945, tại Quảng trường Ba Đình, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập. Dòng chữ viết ở núi rừng Cao Bằng ba năm trước đã thành sự thật.\n\nNgày nay, “Lịch sử nước ta” được in trong Hồ Chí Minh Toàn tập, tập 3. Hai câu mở đầu “Dân ta phải biết sử ta / Cho tường gốc tích nước nhà Việt Nam” trở thành lời nhắc quen thuộc trong nhà trường và nhiều nơi trưng bày lịch sử. Năm 2022, tròn tám mươi năm tác phẩm được xuất bản, báo chí và giới nghiên cứu đã có nhiều bài viết đánh giá lại giá trị của tập sách nhỏ ấy. Đứng trước bảng này, mỗi người có thể đọc lại bốn câu mở đầu và tự hỏi: mình đã thật sự biết sử ta đến đâu?","doc":12},{"loai":"ban_co_biet","text":"Đề nghị triệu tập đại hội đại biểu quốc dân nêu trong bức thư tháng 10/1944 đã thành hiện thực gần một năm sau, khi Quốc dân Đại hội họp tại Tân Trào ngày 16 – 17/8/1945, ngay trước Tổng khởi nghĩa.","nguon_ten":"Hồ Chí Minh Toàn tập, tập 3; Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","doc":13}],"nguon":["Hồ Chí Minh Toàn tập, tập 3, NXB Chính trị quốc gia, 2011 (“Lịch sử nước ta”; Thư gửi đồng bào toàn quốc, tháng 10/1944)","Báo Nhân Dân, “80 năm tác phẩm Lịch sử nước ta của Chủ tịch Hồ Chí Minh” – https://nhandan.vn/80-nam-tac-pham-lich-su-nuoc-ta-cua-chu-tich-ho-chi-minh-post727707.html","Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","Báo Cao Bằng, “Những lời tiên tri thần kỳ về Cách mạng Tháng Tám”","Bảo tàng Hồ Chí Minh"],"doc":[{"t":"“Dân ta phải biết sử ta”: tập sử ca viết ở Cao Bằng và dòng chữ “1945 – Việt Nam độc lập”. Đầu năm 1942, khi nước ta còn chìm dưới ách Pháp – Nhật, Việt Minh phát hành một tập sách nhỏ kể lịch sử dân tộc bằng thơ lục bát. Ở trang cuối, trong bảng những năm quan trọng, tác giả ghi một mốc chưa hề xảy ra: “1945 – Việt Nam độc lập”. Ba năm sau, dòng chữ ấy thành sự thật. Tác giả là Nguyễn Ái Quốc, khi ấy đang sống giữa núi rừng Cao Bằng."},{"t":"Một dòng chữ đi trước lịch sử. Hãy hình dung một người nông dân ở vùng căn cứ Cao Bằng đầu năm 1942, lần đầu cầm trên tay tập sách mỏng do cán bộ Việt Minh mang tới. Sách do Việt Minh tuyên truyền bộ xuất bản. Bên trong là một bài diễn ca dài bằng thơ lục bát, kể chuyện nước nhà từ buổi tổ tiên dựng nước. Lật tới cuối, người đọc gặp bảng “Những năm quan trọng”, ghi các mốc lớn trong lịch sử dân tộc. Các mốc nối nhau tới năm 1941. Rồi đến dòng cuối cùng: “1945 – Việt Nam độc lập”. Năm ấy, nước ta vẫn nằm dưới ách thống trị của thực dân Pháp và phát xít Nhật. Mặt trận Việt Minh mới ra đời chưa đầy một năm. Lực lượng vũ trang cách mạng mới chỉ là những nhóm du kích nhỏ, vũ khí thô sơ. Không ai biết chắc cuộc chiến tranh thế giới sẽ kết thúc vào lúc nào. Vậy mà tác giả tập sách, Nguyễn Ái Quốc, đã ghi một năm cụ thể. Chuyên đề này kể về tập sách nhỏ ấy: vì sao nó được viết, và nó nói gì với đồng bào. Chuyên đề cũng lý giải vì sao dòng chữ cuối cùng lại trở thành một trong những lời dự báo nổi tiếng nhất của lịch sử Việt Nam hiện đại."},{"t":"Căn cứ cần những trang sách dễ hiểu. Sau Hội nghị Trung ương lần thứ tám tháng 5/1941, việc lớn nhất ở vùng căn cứ là đưa đường lối của Việt Minh tới từng bản làng. Nhưng đồng bào nơi đây phần đông là nông dân các dân tộc Tày, Nùng, Dao, nhiều người không biết chữ, có người chưa thạo tiếng Kinh. Những văn kiện dài, lời lẽ lý luận khó lòng đi vào đời sống của họ. Cán bộ cần những tài liệu ngắn, dễ nhớ, có thể đọc to trong các buổi họp, học thuộc rồi truyền miệng từ người này sang người khác. Nguyễn Ái Quốc tự tay làm công việc ấy. Ngoài việc dịch sách và soạn tài liệu huấn luyện, Người viết bài cho báo Việt Nam độc lập, ra số đầu ngày 1/8/1941, với lối viết ngắn gọn, giản dị. Người còn viết nhiều bài ca vận động bằng thơ, như “Ca sợi chỉ”, mượn hình ảnh sợi chỉ yếu ớt khi đứng riêng nhưng bền chắc khi dệt thành tấm vải để nói về sức mạnh đoàn kết. Bài diễn ca “Lịch sử nước ta” ra đời trong mạch công việc đó. Người viết năm 1941, và tháng 2/1942, Việt Minh tuyên truyền bộ in thành sách để phát hành rộng rãi trong vùng căn cứ và các nơi có cơ sở cách mạng."},{"t":"Vì sao chọn thể thơ lục bát?. Lục bát là thể thơ quen thuộc nhất của người Việt. Câu sáu chữ nối câu tám chữ, vần gieo đều đặn, nhịp chẵn dễ đọc, dễ ngâm. Từ những câu ca dao mẹ ru con đến những truyện thơ dài, lục bát đã nuôi dưỡng trí nhớ dân gian qua nhiều thế kỷ. Một người không biết chữ vẫn có thể thuộc hàng trăm câu lục bát nếu được nghe đọc nhiều lần. Chọn lục bát để kể lịch sử, Nguyễn Ái Quốc biến những trang sử khô khan thành lời ca có thể theo người nông dân ra đồng, lên nương, tới những buổi sinh hoạt của hội Cứu quốc. Cách làm này cũng tiếp nối một truyền thống cũ. Ở thế kỷ XIX, các nhà nho đã soạn “Đại Nam quốc sử diễn ca”, kể lịch sử nước nhà bằng thơ lục bát để người học dễ nhớ. Điểm mới ở tác phẩm của Nguyễn Ái Quốc nằm ở mục đích: không chỉ để học thuộc, mà để thức tỉnh. Kể lại quá khứ, bài thơ hướng người đọc tới những câu hỏi của hiện tại: một dân tộc từng nhiều lần đánh thắng ngoại xâm vì sao nay lại mất nước, và phải làm gì để giành lại độc lập."},{"t":"Dân ta phải biết sử ta / Cho tường gốc tích nước nhà Việt Nam / Kể năm hơn bốn ngàn năm / Tổ tiên rực rỡ, anh em thuận hòa. — Nguyễn Ái Quốc"},{"t":"Bốn câu mở đầu. Bài diễn ca mở đầu bằng bốn câu nay đã trở thành lời nhắc của nhiều thế hệ. Câu đầu tiên đặt ra một yêu cầu chứ không phải một lời khuyên: dân ta “phải biết” sử ta. Biết sử ở đây không phải để thuộc tên vua, năm trị vì, mà để “cho tường gốc tích nước nhà”, tức là hiểu cội nguồn của chính mình. Hai câu tiếp theo khẳng định bề dày “hơn bốn ngàn năm” và dừng lại ở hai chữ “thuận hòa”. Ngay từ những dòng đầu, tinh thần đoàn kết đã được đặt làm nền cho toàn bộ câu chuyện phía sau. Với người đọc năm 1942, bốn câu ấy mang một thông điệp rất rõ. Thực dân Pháp chia đất nước thành ba kỳ với những chế độ cai trị khác nhau, cố làm phai nhạt ý thức về một dân tộc thống nhất. Nhắc rằng người Việt có chung một gốc tích, một bề dày hơn bốn nghìn năm, là cách khơi dậy lòng tự hào và ý thức cộng đồng từ Bắc chí Nam. Người đọc được mời nhìn mình không phải như một người dân thuộc địa, mà như con cháu của một dân tộc có lịch sử vẻ vang."},{"t":"Qua các triều đại, một bài học xuyên suốt. Từ buổi dựng nước, bài diễn ca đưa người đọc đi qua các thời kỳ: cuộc khởi nghĩa của Hai Bà Trưng, những chiến công chống ngoại xâm dưới các triều Lý, Trần, Lê, rồi tới khi nước ta bị thực dân Pháp xâm chiếm. Các nhân vật lịch sử được kể bằng lời thơ mộc mạc, gần với lời ăn tiếng nói hằng ngày, đọc lên là hiểu, không cần chú giải. Phần cuối bài dẫn câu chuyện tới những năm gần với lúc viết, để người đọc thấy mạch yêu nước chưa bao giờ đứt. Điều bài thơ muốn đồng bào rút ra là sức mạnh của đoàn kết. Bài học ấy được gói lại trong hai câu thơ nổi tiếng: “Dân ta xin nhớ chữ đồng: / Đồng tình, đồng sức, đồng lòng, đồng minh!”. Bốn chữ “đồng” nối nhau dồn dập như bốn nhịp trống. Chữ cuối cùng, “đồng minh”, còn gợi chính tên gọi Việt Nam Độc lập Đồng minh, tức Mặt trận Việt Minh vừa ra đời. Bài học lịch sử vì thế dẫn thẳng tới lời kêu gọi của hiện tại: đồng lòng đứng vào hàng ngũ Việt Minh để cùng nhau giành lại độc lập."},{"t":"Trang “Những năm quan trọng”. Sau phần diễn ca là bảng “Những năm quan trọng”. Đây là một bảng niên biểu thu gọn, ghi các sự kiện lớn của lịch sử dân tộc từ những năm xa xưa trước Công nguyên cho đến năm 1941. Với người đọc ít chữ, một bảng mốc như thế giúp họ hình dung lịch sử như một dòng chảy liên tục, có trước có sau. Đó cũng là cách Nguyễn Ái Quốc thường làm trong các tài liệu huấn luyện: giản lược, rõ ràng, dễ ghi nhớ. Dòng cuối cùng của bảng không ghi một sự kiện đã qua. Nó ghi: “1945 – Việt Nam độc lập”. Đặt dòng ấy vào cuối một bảng niên biểu là một cách viết đầy chủ ý. Mọi sự kiện phía trên đều đã xảy ra, được sử sách ghi nhận. Dòng cuối cùng đứng chung hàng với chúng, như thể cũng là một điều đã được định trước. Người đọc năm 1942 cầm tập sách lên sẽ thấy độc lập không còn là một giấc mơ mơ hồ, mà là một đích đến có năm tháng cụ thể, gần tới mức có thể đếm được."},{"t":"Bạn có biết? Bài diễn ca “Lịch sử nước ta” gồm 208 câu thơ lục bát. Bảng “Những năm quan trọng” in kèm ghi các sự kiện lớn tới năm 1941, rồi vượt qua bốn năm chưa tới để kết thúc bằng mốc “1945 Việt Nam độc lập”."},{"t":"Mùa thu 1944: lời dự báo thứ hai. Gần ba năm sau, Người lại đưa ra một dự báo về thời gian, lần này còn cụ thể hơn. Tháng 9/1944, sau hơn một năm bị giam trong các nhà lao ở Quảng Tây và một thời gian hoạt động ở Liễu Châu, Người trở lại Pác Bó. Thế giới lúc ấy đã khác hẳn. Hồng quân Liên Xô đang tiến về phía tây, quân Đồng minh đổ bộ lên nước Pháp tháng 6/1944, Pa-ri được giải phóng tháng 8/1944. Ở Đông Dương, mâu thuẫn giữa Nhật và chính quyền thực dân Pháp ngày càng gay gắt. Tháng 10/1944, Người viết thư gửi đồng bào toàn quốc, đề nghị chuẩn bị triệu tập một đại hội đại biểu quốc dân và nêu một nhận định về thời cơ. Cùng thời gian ấy, Người đề nghị hoãn cuộc khởi nghĩa mà Liên tỉnh ủy Cao – Bắc – Lạng đang chuẩn bị (xem chuyên đề “34 chiến sĩ đầu tiên”). Hai việc tưởng như trái chiều thực ra cùng một lôgic: kìm lại một cuộc nổi dậy non ở vài tỉnh, nhưng thúc giục cả nước khẩn trương chuẩn bị cho một thời cơ lớn đang tới gần."},{"t":"Cơ hội cho dân tộc ta giải phóng chỉ ở trong một năm hoặc năm rưỡi nữa. Thời gian rất gấp. Ta phải làm nhanh! — Hồ Chí Minh"},{"t":"Dự báo từ đâu mà có?. Người đời sau thường gọi hai lời dự báo ấy là “tiên tri”. Nhưng chúng không phải những lời đoán may rủi. Ngay từ khi Chiến tranh thế giới thứ hai bùng nổ, Đảng đã nhận định cuộc chiến sẽ làm suy yếu các thế lực đế quốc, tạo thời cơ cho các dân tộc thuộc địa vùng lên. Hội nghị Trung ương lần thứ tám tháng 5/1941 do Người chủ trì xác định chuẩn bị khởi nghĩa vũ trang là nhiệm vụ trung tâm, phải sẵn sàng khi thời cơ đến. Ở Pác Bó, dù sống giữa núi rừng, Người vẫn theo dõi diễn biến chiến sự qua những tờ báo, những tin tức mà cán bộ liên lạc mang về. Lời dự báo năm 1945 vì vậy dựa trên một phép tính chiến lược. Phe phát xít sớm muộn sẽ thua. Khi Nhật suy yếu, Pháp và Nhật sẽ xung đột với nhau ở Đông Dương. Nếu đến lúc ấy dân tộc ta đã có tổ chức, có lực lượng, thì có thể vùng lên giành chính quyền. Viết “1945” vào cuối bảng niên biểu vừa là kết quả của phép tính ấy, vừa là một mục tiêu đặt ra để cả phong trào hướng tới. Dự báo và hành động gắn chặt với nhau: nói trước năm độc lập, rồi dồn sức làm cho năm ấy thành sự thật."},{"t":"Năm 1945: khi dòng chữ thành hiện thực. Diễn biến năm 1945 khớp với phép tính ấy một cách lạ lùng. Ngày 9/3/1945, Nhật đảo chính lật đổ Pháp. Ngày 15/8/1945, Nhật tuyên bố đầu hàng Đồng minh. Ngay trong những ngày ấy, tại Tân Trào, Hội nghị toàn quốc của Đảng quyết định Tổng khởi nghĩa, Quốc dân Đại hội thông qua lệnh khởi nghĩa và bầu ra Ủy ban Dân tộc giải phóng Việt Nam. Ngày 19/8, Hà Nội giành chính quyền; chỉ trong khoảng nửa tháng, cuộc khởi nghĩa thắng lợi trên cả nước. Ngày 2/9/1945, tại Quảng trường Ba Đình, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập. Dòng chữ viết ở núi rừng Cao Bằng ba năm trước đã thành sự thật. Ngày nay, “Lịch sử nước ta” được in trong Hồ Chí Minh Toàn tập, tập 3. Hai câu mở đầu “Dân ta phải biết sử ta / Cho tường gốc tích nước nhà Việt Nam” trở thành lời nhắc quen thuộc trong nhà trường và nhiều nơi trưng bày lịch sử. Năm 2022, tròn tám mươi năm tác phẩm được xuất bản, báo chí và giới nghiên cứu đã có nhiều bài viết đánh giá lại giá trị của tập sách nhỏ ấy. Đứng trước bảng này, mỗi người có thể đọc lại bốn câu mở đầu và tự hỏi: mình đã thật sự biết sử ta đến đâu?"},{"t":"Bạn có biết? Đề nghị triệu tập đại hội đại biểu quốc dân nêu trong bức thư tháng 10/1944 đã thành hiện thực gần một năm sau, khi Quốc dân Đại hội họp tại Tân Trào ngày 16 – 17/8/1945, ngay trước Tổng khởi nghĩa."}],"so_chu":2153},{"i":2,"tieu_de_bang":"34 chiến sĩ đầu tiên (22/12/1944)","tieu_de":"Ba mươi tư chiến sĩ trong rừng Trần Hưng Đạo: ngày khai sinh đội quân chủ lực đầu tiên","sapo":"Ba mươi tư người, ba mươi tư khẩu súng, phần lớn là súng trường và súng kíp. Đó là toàn bộ lực lượng làm lễ thành lập trong một khu rừng ở Nguyên Bình, Cao Bằng, ngày 22/12/1944. Bản chỉ thị ngắn của Hồ Chí Minh gọi đội quân nhỏ ấy là “khởi điểm của giải phóng quân”. Ba ngày sau, họ đánh trận đầu tiên, và thắng.","bia":{"src":"textures/bai/G12_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Khu rừng giữa hai tổng mang tên anh hùng","text":"Khu rừng ấy nằm giữa hai tổng mang tên hai vị anh hùng dân tộc, tổng Hoàng Hoa Thám và tổng Trần Hưng Đạo, thuộc châu Nguyên Bình, tỉnh Cao Bằng. Người trong phong trào quen gọi đó là rừng Trần Hưng Đạo. Hai cái tên ấy gợi lại hai thời kỳ chống ngoại xâm. Trần Hưng Đạo là vị tướng tài của nhà Trần, người chỉ huy quân dân đánh bại quân Nguyên Mông ở thế kỷ XIII. Hoàng Hoa Thám là thủ lĩnh cuộc khởi nghĩa Yên Thế, kiên trì chống thực dân Pháp gần ba mươi năm. Ngày nay, nơi ấy thuộc xóm Nà Sang, xã Tam Kim, huyện Nguyên Bình. Ngày 22/12/1944, giữa những tán cây rừng, ba mươi tư người đứng thành hàng làm lễ thành lập Đội Việt Nam Tuyên truyền Giải phóng quân. Người trực tiếp tổ chức và chỉ huy đội là đồng chí Võ Nguyên Giáp, được Hồ Chí Minh giao nhiệm vụ chỉ ít tuần trước đó.\n\nTrong buổi lễ, các đội viên trang nghiêm tuyên đọc Mười lời thề danh dự của người chiến sĩ, nguyện chiến đấu vì Tổ quốc, vì nhân dân. Không có quân phục chỉnh tề, không có doanh trại, không có kho tàng. Chỉ có một đội hình nhỏ giữa rừng, những khẩu súng đủ loại và một bản chỉ thị chưa đầy một trang giấy. Có lẽ ít ai trong số họ hình dung được rằng từ đội hình nhỏ bé này sẽ lớn lên cả một quân đội. Nhưng người viết bản chỉ thị thì đã nhìn thấy điều đó từ trước.","doc":1},{"loai":"doan","tieu_de":"Mùa thu 1944: một kế hoạch khởi nghĩa bị hoãn","text":"Câu chuyện bắt đầu từ khoảng ba tháng trước. Tháng 9/1944, Hồ Chí Minh trở lại Pác Bó sau hơn hai năm vắng mặt, trong đó có hơn một năm bị giam trong các nhà lao của chính quyền Tưởng Giới Thạch ở Quảng Tây. Người thấy phong trào ở Cao Bằng đã lớn mạnh: Việt Minh có cơ sở ở khắp các châu, nhiều đội du kích đã được thành lập. Nhưng cũng trong thời gian ấy, thực dân Pháp ra sức càn quét, khủng bố vùng căn cứ. Trước tình hình đó, Liên tỉnh ủy Cao – Bắc – Lạng đã quyết định phát động khởi nghĩa vũ trang trong vùng.\n\nNgười nghe báo cáo và phân tích: phong trào mới mạnh ở vài tỉnh miền núi, cả nước chưa sẵn sàng. Nếu nổi dậy lúc này, địch sẽ dồn lực lượng về đàn áp, cơ sở gây dựng bao năm có thể bị phá vỡ. Theo hồi ký của Đại tướng Võ Nguyên Giáp, Người nhận định thời kỳ cách mạng hòa bình phát triển đã qua, nhưng thời kỳ toàn dân khởi nghĩa chưa tới. Kế hoạch khởi nghĩa được hoãn lại. Nhưng Người không để phong trào đứng yên. Cần một hình thức mới, vừa giữ gìn được lực lượng, vừa đưa phong trào lên một bước cao hơn.","doc":2},{"loai":"anh","src":"textures/bang_w/G12_2_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “34 chiến sĩ đầu tiên (22/12/1944)”, nhìn từ xa."},{"loai":"doan","tieu_de":"Một đội quân mà chính trị trọng hơn quân sự","text":"Hình thức mới ấy là một đội vũ trang tập trung. Người đề nghị chọn trong các đội du kích Cao – Bắc – Lạng những cán bộ, đội viên kiên quyết, hăng hái nhất, tập trung một phần lớn vũ khí, lập thành một đội chủ lực. Tháng 12/1944, Người viết bản chỉ thị thành lập Đội Việt Nam Tuyên truyền Giải phóng quân và giao cho đồng chí Võ Nguyên Giáp tổ chức. Bản chỉ thị rất ngắn, nhưng mỗi câu đều hàm chứa một nguyên tắc.\n\nNgay ở phần đầu, chỉ thị giải thích chính cái tên: tên gọi của đội nghĩa là chính trị trọng hơn quân sự, đội trước hết là một đội tuyên truyền. Nhiệm vụ của đội không chỉ là đánh địch, mà là dùng hoạt động vũ trang để tuyên truyền, kêu gọi toàn dân đứng lên. Chỉ thị nhấn mạnh cuộc kháng chiến của ta là cuộc kháng chiến của toàn dân, cần phải động viên toàn dân, vũ trang toàn dân. Người còn gọi Đội Việt Nam Tuyên truyền Giải phóng quân là “đội đàn anh”, mong cho chóng có những “đội đàn em” khác. Một đội quân nhỏ, nhưng được hình dung như hạt nhân của cả một hệ thống lực lượng vũ trang nhân dân sau này.","doc":3},{"loai":"doan","tieu_de":"Nay Đông mai Tây, trận đầu phải thắng","text":"Về cách đánh, bản chỉ thị yêu cầu vận dụng lối đánh du kích: bí mật, nhanh chóng, tích cực, “nay Đông mai Tây, lai vô ảnh, khứ vô tung”, nghĩa là đến không thấy bóng, đi không để dấu. Với một đội quân chỉ có vài chục người, vũ khí thô sơ, đối đầu trực diện với các đồn binh có công sự là điều không thể. Sức mạnh của đội nằm ở sự bất ngờ, ở khả năng xuất hiện rồi biến mất giữa núi rừng mà đồng bào che chở.\n\nTheo hồi ký của Đại tướng Võ Nguyên Giáp, Người còn dặn đội phải có hoạt động ngay trong vòng một tháng, và trận đầu nhất định phải thắng. Yêu cầu ấy không chỉ mang ý nghĩa quân sự. Một chiến thắng đầu tiên sẽ khẳng định uy tín của đội, gây tiếng vang trong nhân dân, làm kẻ địch hoang mang. Ngược lại, một thất bại ngay từ đầu có thể làm lung lay niềm tin của cả phong trào vừa mới được nhen nhóm. Bởi vậy, từ trước ngày làm lễ thành lập, những người chỉ huy đã phải điều tra, tính toán kỹ lưỡng cho trận ra quân.","doc":4},{"loai":"trich","text":"Tuy lúc đầu quy mô của nó còn nhỏ, nhưng tiền đồ của nó rất vẻ vang. Nó là khởi điểm của giải phóng quân, nó có thể đi suốt từ Nam chí Bắc, khắp đất nước Việt Nam.","nguoi":"Hồ Chí Minh","nguon_ten":"Chỉ thị thành lập Đội Việt Nam Tuyên truyền Giải phóng quân, tháng 12/1944 – Hồ Chí Minh Toàn tập, tập 3, NXB Chính trị quốc gia, 2011","doc":5},{"loai":"anh","src":"textures/bang_w/G12_2_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “34 chiến sĩ đầu tiên (22/12/1944)”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Ba mươi tư con người, ba mươi tư khẩu súng","text":"Đội có ba mươi tư chiến sĩ, biên chế thành ba tiểu đội, có chi bộ Đảng lãnh đạo. Đội trưởng là đồng chí Hoàng Sâm, chính trị viên là đồng chí Xích Thắng. Đồng chí Hoàng Văn Thái phụ trách công tác kế hoạch và tình báo. Các đội viên được tuyển chọn từ những cán bộ và du kích ưu tú của phong trào Cao – Bắc – Lạng. Nhiều người là con em các dân tộc miền núi, đã được thử thách qua những năm hoạt động bí mật và những đợt khủng bố của địch.\n\nVũ khí của đội là ba mươi tư khẩu súng các loại, đúng bằng số người. Theo nhiều tài liệu, trong đó có hai khẩu súng ngắn, mười bảy khẩu súng trường, một khẩu trung liên và mười bốn khẩu súng kíp. Súng kíp là loại súng nạp thuốc đằng nòng, dùng hạt nổ để kích hỏa, đồng bào miền núi vẫn dùng để đi săn. Thiếu thốn đủ bề, nhưng đội có một thứ mà không đồn binh nào có được: sự che chở của nhân dân trong vùng, từ bữa cơm, chỗ ngủ đến những tin tức về đường đi nước bước của địch.","doc":6},{"loai":"ban_co_biet","text":"Đồng chí Hoàng Văn Thái, người phụ trách kế hoạch và tình báo của Đội năm 1944, về sau trở thành Tổng Tham mưu trưởng đầu tiên của Quân đội nhân dân Việt Nam.","nguon_ten":"Báo Nhân Dân, “Việt Nam Tuyên truyền Giải phóng quân – Đội quân chủ lực đầu tiên của Quân đội nhân dân Việt Nam”; Bộ Quốc phòng – Lịch sử Quân đội nhân dân Việt Nam","doc":7},{"loai":"doan","tieu_de":"Phai Khắt, Nà Ngần: hai trận đầu tiên","text":"Chỉ ba ngày sau lễ thành lập, đội ra quân. Mục tiêu đầu tiên là đồn Phai Khắt ở châu Nguyên Bình. Khoảng 17 giờ ngày 25/12/1944, đội bất ngờ tập kích đồn. Theo hồi ký của Đại tướng Võ Nguyên Giáp, các chiến sĩ đã cải trang để tiếp cận, đánh úp khi địch không kịp trở tay. Trận đánh diễn ra nhanh gọn, đồn Phai Khắt bị tiêu diệt, vũ khí trong đồn được thu về.\n\nKhông để địch kịp đối phó, ngày hôm sau, 26/12/1944, đội tiếp tục đánh đồn Nà Ngần và lại giành thắng lợi. Hai ngày liền, hai đồn bị diệt, số vũ khí thu được trang bị thêm cho chính đội quân vừa ra đời. Tiếng súng Phai Khắt, Nà Ngần vang khắp vùng Cao – Bắc – Lạng, làm nức lòng đồng bào và khiến kẻ địch hoang mang. Yêu cầu “trận đầu phải thắng” đã được thực hiện trọn vẹn. Chiến thắng đến chỉ ba, bốn ngày sau lễ thành lập, sớm hơn nhiều so với thời hạn một tháng mà Người căn dặn. Từ đây, đánh thắng trận đầu trở thành một truyền thống của quân đội ta, được các thế hệ sau nhắc lại mỗi khi bước vào chiến dịch mới.","doc":8},{"loai":"anh","src":"textures/bai/G12_v4.jpg","chu_thich":"Không gian 3D tái hiện gian Pác Bó – Cao Bằng, vùng căn cứ nơi những lực lượng vũ trang cách mạng đầu tiên được xây dựng.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Từ ba mươi tư người đến một quân đội","text":"Mùa xuân năm 1945, thời cuộc chuyển biến rất nhanh. Ngày 9/3/1945, Nhật đảo chính lật đổ Pháp trên toàn Đông Dương. Ngày 15/4/1945, Hội nghị Quân sự cách mạng Bắc Kỳ quyết định thống nhất các lực lượng vũ trang cách mạng. Ngày 15/5/1945, tại Thái Nguyên, Đội Việt Nam Tuyên truyền Giải phóng quân hợp nhất với Cứu quốc quân thành Việt Nam Giải phóng quân. Chiều 16/8/1945, tại Tân Trào, một đơn vị Giải phóng quân làm lễ xuất quân, tiến về giải phóng thị xã Thái Nguyên, mở đầu Tổng khởi nghĩa.\n\nĐúng như lời bản chỉ thị, đội quân ấy đã “đi suốt từ Nam chí Bắc”. Qua các cuộc kháng chiến giữ nước, từ ba mươi tư chiến sĩ ban đầu, nó lớn lên thành Quân đội nhân dân Việt Nam. Ngày 22/12/1944 được lấy làm ngày thành lập Quân đội nhân dân Việt Nam. Nhiều đội viên đầu tiên về sau trở thành cán bộ chỉ huy của quân đội trong các cuộc kháng chiến. Còn yêu cầu “chính trị trọng hơn quân sự” trong bản chỉ thị năm 1944 trở thành một nguyên tắc xây dựng quân đội: trước hết là đội quân của nhân dân, vì nhân dân.","doc":9},{"loai":"ban_co_biet","text":"Ngày 22/12 được lấy làm ngày thành lập Quân đội nhân dân Việt Nam; từ năm 1989, ngày này còn là Ngày hội Quốc phòng toàn dân.","nguon_ten":"Bộ Quốc phòng – Lịch sử Quân đội nhân dân Việt Nam","doc":10},{"loai":"anh","src":"textures/bang_w/G12_2_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “34 chiến sĩ đầu tiên (22/12/1944)”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Khu rừng Trần Hưng Đạo ở xã Tam Kim, huyện Nguyên Bình, ngày nay là khu di tích lịch sử gắn với sự ra đời của Đội Việt Nam Tuyên truyền Giải phóng quân. Mỗi dịp tháng 12, nhiều đoàn cán bộ, chiến sĩ, học sinh và cựu chiến binh tìm về đây, dâng hương tưởng niệm những người lính đầu tiên. Các địa điểm chiến thắng Phai Khắt, Nà Ngần cũng được ghi dấu, nhắc nhớ về hai trận đánh mở đầu truyền thống của quân đội ta.\n\nTrong gian trưng bày này, bảng “34 chiến sĩ đầu tiên” được đặt trong không gian vùng căn cứ Cao Bằng, cạnh những góc tái hiện Pác Bó. Sự sắp xếp ấy có dụng ý: đội quân chủ lực đầu tiên không ra đời ở một thao trường, mà từ chính vùng núi rừng nơi Hồ Chí Minh đã kiên nhẫn chuẩn bị từ đầu năm 1941. Từ hang Cốc Bó đến rừng Trần Hưng Đạo là gần bốn năm gây dựng cơ sở, huấn luyện cán bộ, tổ chức du kích. Ba mươi tư chiến sĩ là kết tinh của cả chặng đường ấy, và cũng là điểm khởi đầu của một chặng đường dài hơn nhiều.","doc":11}],"nguon":["Hồ Chí Minh Toàn tập, tập 3, NXB Chính trị quốc gia, 2011 (Chỉ thị thành lập Đội Việt Nam Tuyên truyền Giải phóng quân, tháng 12/1944)","Võ Nguyên Giáp, Từ nhân dân mà ra; Những năm tháng không thể nào quên (hồi ký)","Báo Nhân Dân, “Đội Việt Nam tuyên truyền giải phóng quân – đội quân chủ lực đầu tiên của Quân đội nhân dân Việt Nam (22-12-1944), đánh thắng hai trận đầu (Phai Khắt, Nà Ngần)” – https://nhandan.vn/doi-viet-nam-tuyen-truyen-giai-phong-quan-doi-quan-chu-luc-dau-tien-cua-quan-doi-nhan-dan-viet-nam-22-12-1944-danh-thang-hai-tran-dau-phai-khat-na-ngan-post219176.html","Báo Nhân Dân, “Việt Nam Tuyên truyền Giải phóng quân – Đội quân chủ lực đầu tiên của Quân đội nhân dân Việt Nam” – https://special.nhandan.vn/thanh-lap-doi-VN-tuyen-truyen-giai-phong-quan/index.html","Bộ Quốc phòng – Lịch sử Quân đội nhân dân Việt Nam","Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia"],"doc":[{"t":"Ba mươi tư chiến sĩ trong rừng Trần Hưng Đạo: ngày khai sinh đội quân chủ lực đầu tiên. Ba mươi tư người, ba mươi tư khẩu súng, phần lớn là súng trường và súng kíp. Đó là toàn bộ lực lượng làm lễ thành lập trong một khu rừng ở Nguyên Bình, Cao Bằng, ngày 22/12/1944. Bản chỉ thị ngắn của Hồ Chí Minh gọi đội quân nhỏ ấy là “khởi điểm của giải phóng quân”. Ba ngày sau, họ đánh trận đầu tiên, và thắng."},{"t":"Khu rừng giữa hai tổng mang tên anh hùng. Khu rừng ấy nằm giữa hai tổng mang tên hai vị anh hùng dân tộc, tổng Hoàng Hoa Thám và tổng Trần Hưng Đạo, thuộc châu Nguyên Bình, tỉnh Cao Bằng. Người trong phong trào quen gọi đó là rừng Trần Hưng Đạo. Hai cái tên ấy gợi lại hai thời kỳ chống ngoại xâm. Trần Hưng Đạo là vị tướng tài của nhà Trần, người chỉ huy quân dân đánh bại quân Nguyên Mông ở thế kỷ XIII. Hoàng Hoa Thám là thủ lĩnh cuộc khởi nghĩa Yên Thế, kiên trì chống thực dân Pháp gần ba mươi năm. Ngày nay, nơi ấy thuộc xóm Nà Sang, xã Tam Kim, huyện Nguyên Bình. Ngày 22/12/1944, giữa những tán cây rừng, ba mươi tư người đứng thành hàng làm lễ thành lập Đội Việt Nam Tuyên truyền Giải phóng quân. Người trực tiếp tổ chức và chỉ huy đội là đồng chí Võ Nguyên Giáp, được Hồ Chí Minh giao nhiệm vụ chỉ ít tuần trước đó. Trong buổi lễ, các đội viên trang nghiêm tuyên đọc Mười lời thề danh dự của người chiến sĩ, nguyện chiến đấu vì Tổ quốc, vì nhân dân. Không có quân phục chỉnh tề, không có doanh trại, không có kho tàng. Chỉ có một đội hình nhỏ giữa rừng, những khẩu súng đủ loại và một bản chỉ thị chưa đầy một trang giấy. Có lẽ ít ai trong số họ hình dung được rằng từ đội hình nhỏ bé này sẽ lớn lên cả một quân đội. Nhưng người viết bản chỉ thị thì đã nhìn thấy điều đó từ trước."},{"t":"Mùa thu 1944: một kế hoạch khởi nghĩa bị hoãn. Câu chuyện bắt đầu từ khoảng ba tháng trước. Tháng 9/1944, Hồ Chí Minh trở lại Pác Bó sau hơn hai năm vắng mặt, trong đó có hơn một năm bị giam trong các nhà lao của chính quyền Tưởng Giới Thạch ở Quảng Tây. Người thấy phong trào ở Cao Bằng đã lớn mạnh: Việt Minh có cơ sở ở khắp các châu, nhiều đội du kích đã được thành lập. Nhưng cũng trong thời gian ấy, thực dân Pháp ra sức càn quét, khủng bố vùng căn cứ. Trước tình hình đó, Liên tỉnh ủy Cao – Bắc – Lạng đã quyết định phát động khởi nghĩa vũ trang trong vùng. Người nghe báo cáo và phân tích: phong trào mới mạnh ở vài tỉnh miền núi, cả nước chưa sẵn sàng. Nếu nổi dậy lúc này, địch sẽ dồn lực lượng về đàn áp, cơ sở gây dựng bao năm có thể bị phá vỡ. Theo hồi ký của Đại tướng Võ Nguyên Giáp, Người nhận định thời kỳ cách mạng hòa bình phát triển đã qua, nhưng thời kỳ toàn dân khởi nghĩa chưa tới. Kế hoạch khởi nghĩa được hoãn lại. Nhưng Người không để phong trào đứng yên. Cần một hình thức mới, vừa giữ gìn được lực lượng, vừa đưa phong trào lên một bước cao hơn."},{"t":"Một đội quân mà chính trị trọng hơn quân sự. Hình thức mới ấy là một đội vũ trang tập trung. Người đề nghị chọn trong các đội du kích Cao – Bắc – Lạng những cán bộ, đội viên kiên quyết, hăng hái nhất, tập trung một phần lớn vũ khí, lập thành một đội chủ lực. Tháng 12/1944, Người viết bản chỉ thị thành lập Đội Việt Nam Tuyên truyền Giải phóng quân và giao cho đồng chí Võ Nguyên Giáp tổ chức. Bản chỉ thị rất ngắn, nhưng mỗi câu đều hàm chứa một nguyên tắc. Ngay ở phần đầu, chỉ thị giải thích chính cái tên: tên gọi của đội nghĩa là chính trị trọng hơn quân sự, đội trước hết là một đội tuyên truyền. Nhiệm vụ của đội không chỉ là đánh địch, mà là dùng hoạt động vũ trang để tuyên truyền, kêu gọi toàn dân đứng lên. Chỉ thị nhấn mạnh cuộc kháng chiến của ta là cuộc kháng chiến của toàn dân, cần phải động viên toàn dân, vũ trang toàn dân. Người còn gọi Đội Việt Nam Tuyên truyền Giải phóng quân là “đội đàn anh”, mong cho chóng có những “đội đàn em” khác. Một đội quân nhỏ, nhưng được hình dung như hạt nhân của cả một hệ thống lực lượng vũ trang nhân dân sau này."},{"t":"Nay Đông mai Tây, trận đầu phải thắng. Về cách đánh, bản chỉ thị yêu cầu vận dụng lối đánh du kích: bí mật, nhanh chóng, tích cực, “nay Đông mai Tây, lai vô ảnh, khứ vô tung”, nghĩa là đến không thấy bóng, đi không để dấu. Với một đội quân chỉ có vài chục người, vũ khí thô sơ, đối đầu trực diện với các đồn binh có công sự là điều không thể. Sức mạnh của đội nằm ở sự bất ngờ, ở khả năng xuất hiện rồi biến mất giữa núi rừng mà đồng bào che chở. Theo hồi ký của Đại tướng Võ Nguyên Giáp, Người còn dặn đội phải có hoạt động ngay trong vòng một tháng, và trận đầu nhất định phải thắng. Yêu cầu ấy không chỉ mang ý nghĩa quân sự. Một chiến thắng đầu tiên sẽ khẳng định uy tín của đội, gây tiếng vang trong nhân dân, làm kẻ địch hoang mang. Ngược lại, một thất bại ngay từ đầu có thể làm lung lay niềm tin của cả phong trào vừa mới được nhen nhóm. Bởi vậy, từ trước ngày làm lễ thành lập, những người chỉ huy đã phải điều tra, tính toán kỹ lưỡng cho trận ra quân."},{"t":"Tuy lúc đầu quy mô của nó còn nhỏ, nhưng tiền đồ của nó rất vẻ vang. Nó là khởi điểm của giải phóng quân, nó có thể đi suốt từ Nam chí Bắc, khắp đất nước Việt Nam. — Hồ Chí Minh"},{"t":"Ba mươi tư con người, ba mươi tư khẩu súng. Đội có ba mươi tư chiến sĩ, biên chế thành ba tiểu đội, có chi bộ Đảng lãnh đạo. Đội trưởng là đồng chí Hoàng Sâm, chính trị viên là đồng chí Xích Thắng. Đồng chí Hoàng Văn Thái phụ trách công tác kế hoạch và tình báo. Các đội viên được tuyển chọn từ những cán bộ và du kích ưu tú của phong trào Cao – Bắc – Lạng. Nhiều người là con em các dân tộc miền núi, đã được thử thách qua những năm hoạt động bí mật và những đợt khủng bố của địch. Vũ khí của đội là ba mươi tư khẩu súng các loại, đúng bằng số người. Theo nhiều tài liệu, trong đó có hai khẩu súng ngắn, mười bảy khẩu súng trường, một khẩu trung liên và mười bốn khẩu súng kíp. Súng kíp là loại súng nạp thuốc đằng nòng, dùng hạt nổ để kích hỏa, đồng bào miền núi vẫn dùng để đi săn. Thiếu thốn đủ bề, nhưng đội có một thứ mà không đồn binh nào có được: sự che chở của nhân dân trong vùng, từ bữa cơm, chỗ ngủ đến những tin tức về đường đi nước bước của địch."},{"t":"Bạn có biết? Đồng chí Hoàng Văn Thái, người phụ trách kế hoạch và tình báo của Đội năm 1944, về sau trở thành Tổng Tham mưu trưởng đầu tiên của Quân đội nhân dân Việt Nam."},{"t":"Phai Khắt, Nà Ngần: hai trận đầu tiên. Chỉ ba ngày sau lễ thành lập, đội ra quân. Mục tiêu đầu tiên là đồn Phai Khắt ở châu Nguyên Bình. Khoảng 17 giờ ngày 25/12/1944, đội bất ngờ tập kích đồn. Theo hồi ký của Đại tướng Võ Nguyên Giáp, các chiến sĩ đã cải trang để tiếp cận, đánh úp khi địch không kịp trở tay. Trận đánh diễn ra nhanh gọn, đồn Phai Khắt bị tiêu diệt, vũ khí trong đồn được thu về. Không để địch kịp đối phó, ngày hôm sau, 26/12/1944, đội tiếp tục đánh đồn Nà Ngần và lại giành thắng lợi. Hai ngày liền, hai đồn bị diệt, số vũ khí thu được trang bị thêm cho chính đội quân vừa ra đời. Tiếng súng Phai Khắt, Nà Ngần vang khắp vùng Cao – Bắc – Lạng, làm nức lòng đồng bào và khiến kẻ địch hoang mang. Yêu cầu “trận đầu phải thắng” đã được thực hiện trọn vẹn. Chiến thắng đến chỉ ba, bốn ngày sau lễ thành lập, sớm hơn nhiều so với thời hạn một tháng mà Người căn dặn. Từ đây, đánh thắng trận đầu trở thành một truyền thống của quân đội ta, được các thế hệ sau nhắc lại mỗi khi bước vào chiến dịch mới."},{"t":"Từ ba mươi tư người đến một quân đội. Mùa xuân năm 1945, thời cuộc chuyển biến rất nhanh. Ngày 9/3/1945, Nhật đảo chính lật đổ Pháp trên toàn Đông Dương. Ngày 15/4/1945, Hội nghị Quân sự cách mạng Bắc Kỳ quyết định thống nhất các lực lượng vũ trang cách mạng. Ngày 15/5/1945, tại Thái Nguyên, Đội Việt Nam Tuyên truyền Giải phóng quân hợp nhất với Cứu quốc quân thành Việt Nam Giải phóng quân. Chiều 16/8/1945, tại Tân Trào, một đơn vị Giải phóng quân làm lễ xuất quân, tiến về giải phóng thị xã Thái Nguyên, mở đầu Tổng khởi nghĩa. Đúng như lời bản chỉ thị, đội quân ấy đã “đi suốt từ Nam chí Bắc”. Qua các cuộc kháng chiến giữ nước, từ ba mươi tư chiến sĩ ban đầu, nó lớn lên thành Quân đội nhân dân Việt Nam. Ngày 22/12/1944 được lấy làm ngày thành lập Quân đội nhân dân Việt Nam. Nhiều đội viên đầu tiên về sau trở thành cán bộ chỉ huy của quân đội trong các cuộc kháng chiến. Còn yêu cầu “chính trị trọng hơn quân sự” trong bản chỉ thị năm 1944 trở thành một nguyên tắc xây dựng quân đội: trước hết là đội quân của nhân dân, vì nhân dân."},{"t":"Bạn có biết? Ngày 22/12 được lấy làm ngày thành lập Quân đội nhân dân Việt Nam; từ năm 1989, ngày này còn là Ngày hội Quốc phòng toàn dân."},{"t":"Dấu tích hôm nay. Khu rừng Trần Hưng Đạo ở xã Tam Kim, huyện Nguyên Bình, ngày nay là khu di tích lịch sử gắn với sự ra đời của Đội Việt Nam Tuyên truyền Giải phóng quân. Mỗi dịp tháng 12, nhiều đoàn cán bộ, chiến sĩ, học sinh và cựu chiến binh tìm về đây, dâng hương tưởng niệm những người lính đầu tiên. Các địa điểm chiến thắng Phai Khắt, Nà Ngần cũng được ghi dấu, nhắc nhớ về hai trận đánh mở đầu truyền thống của quân đội ta. Trong gian trưng bày này, bảng “34 chiến sĩ đầu tiên” được đặt trong không gian vùng căn cứ Cao Bằng, cạnh những góc tái hiện Pác Bó. Sự sắp xếp ấy có dụng ý: đội quân chủ lực đầu tiên không ra đời ở một thao trường, mà từ chính vùng núi rừng nơi Hồ Chí Minh đã kiên nhẫn chuẩn bị từ đầu năm 1941. Từ hang Cốc Bó đến rừng Trần Hưng Đạo là gần bốn năm gây dựng cơ sở, huấn luyện cán bộ, tổ chức du kích. Ba mươi tư chiến sĩ là kết tinh của cả chặng đường ấy, và cũng là điểm khởi đầu của một chặng đường dài hơn nhiều."}],"so_chu":1916},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ cột mốc 108 đến đường về Tân Trào: dòng thời gian Pác Bó 1940 – 1945","sapo":"Từ ngày qua cột mốc 108 đến ngày rời Pác Bó là hơn bốn năm ba tháng, nhưng Người chỉ thật sự ở vùng căn cứ khoảng một nửa quãng thời gian ấy. Phần còn lại là những tháng bị giam cầm và những chuyến đi xa. Dòng thời gian dưới đây xếp lại các mốc để thấy một nhịp điệu rõ ràng: chuẩn bị, chờ đợi, rồi chớp thời cơ.","bia":{"src":"textures/bai/G12_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Bốn năm, hai khoảng vắng","text":"Tính từ ngày 28/1/1941, khi Nguyễn Ái Quốc bước qua cột mốc 108, đến ngày 4/5/1945, khi Người rời Pác Bó về Tân Trào, là hơn bốn năm ba tháng. Nhưng nếu đánh dấu trên lịch những ngày Người thật sự có mặt ở vùng căn cứ Cao Bằng, ta sẽ thấy một bức tranh khác. Có hai khoảng vắng dài: hơn hai năm từ tháng 8/1942 đến tháng 9/1944, phần lớn trong các nhà lao ở Quảng Tây, và mấy tháng đầu năm 1945 khi Người sang Côn Minh. Cộng lại, Người chỉ ở Pác Bó và vùng lân cận khoảng một nửa quãng thời gian ấy.\n\nVì thế, dòng thời gian của gian Pác Bó không phải một đường thẳng đều đặn. Nó có những đoạn dồn dập, như mùa xuân và mùa hè năm 1941, khi chỉ trong vài tháng đã có hang Cốc Bó, Hội nghị Trung ương lần thứ tám, Mặt trận Việt Minh, báo Việt Nam độc lập. Nó cũng có những khoảng lặng đầy lo âu, khi ở căn cứ không ai biết tin Người. Bảng mốc dưới đây xếp các sự kiện theo thứ tự, từ những biến động năm 1940 đến ngày Người tới Tân Trào, kèm một mốc trở về năm 1961.","doc":1},{"loai":"moc","items":[["6/1940","Nước Pháp thua trận, ký đình chiến với phát xít Đức; Nguyễn Ái Quốc nhận định thời cơ cho cách mạng Việt Nam đang tới gần"],["22/9/1940","Quân Nhật đánh vào Lạng Sơn; chính quyền thực dân ở Đông Dương chịu khuất phục, nhân dân ta chịu cảnh “một cổ hai tròng”"],["27/9/1940","Khởi nghĩa Bắc Sơn (Lạng Sơn) bùng nổ"],["23/11/1940","Khởi nghĩa Nam Kỳ bùng nổ"],["Cuối 1940","Người tới vùng Tĩnh Tây (Quảng Tây, Trung Quốc) sát biên giới, mở lớp huấn luyện cho cán bộ Cao Bằng sang học"],["28/1/1941","Mùng 2 Tết Tân Tỵ: vượt cột mốc 108 về nước, ở nhà ông Lý Quốc Súng trong bản Pác Bó; bà con gọi Người là Già Thu"],["8/2/1941","Chuyển vào ở hang Cốc Bó; đặt tên suối Lê-nin, núi Các Mác"],["2 – 3/1941","Dịch cuốn Lịch sử Đảng Cộng sản (b) Liên Xô, mở lớp huấn luyện cán bộ; cảnh sống đi vào bài thơ “Tức cảnh Pác Bó”"],["10 – 19/5/1941","Chủ trì Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng tại lán Khuổi Nặm"],["19/5/1941","Mặt trận Việt Nam Độc lập Đồng minh (Việt Minh) thành lập, đúng ngày sinh lần thứ 51 của Người"],["6/6/1941","Thư “Kính cáo đồng bào”, kêu gọi toàn dân đoàn kết đánh Pháp, đuổi Nhật"],["1/8/1941","Báo Việt Nam độc lập do Người sáng lập ra số đầu tiên"],["2/1942","Việt Minh tuyên truyền bộ xuất bản bài diễn ca “Lịch sử nước ta” gồm 208 câu lục bát; cuối sách ghi “1945 – Việt Nam độc lập”"],["1942","Khắp các châu ở Cao Bằng có hội Cứu quốc, trong đó có ba “châu hoàn toàn”"],["13/8/1942","Lấy tên Hồ Chí Minh, lên đường sang Trung Quốc tranh thủ sự giúp đỡ quốc tế"],["29/8/1942","Bị chính quyền Tưởng Giới Thạch bắt ở Túc Vinh (Quảng Tây); trong tù viết tập thơ “Nhật ký trong tù”"],["1943","Ủy ban Việt Minh liên tỉnh Cao – Bắc – Lạng lập các ban “xung phong Nam tiến”, mở đường nối căn cứ Cao Bằng với Bắc Sơn – Võ Nhai"],["10/9/1943","Được trả tự do; sau đó hoạt động một thời gian ở Liễu Châu (Quảng Tây)"],["9/1944","Trở lại Pác Bó; đề nghị hoãn kế hoạch khởi nghĩa của Liên tỉnh ủy Cao – Bắc – Lạng"],["10/1944","Thư gửi đồng bào toàn quốc: cơ hội giải phóng “chỉ ở trong một năm hoặc năm rưỡi nữa”"],["12/1944","Viết chỉ thị thành lập Đội Việt Nam Tuyên truyền Giải phóng quân, giao Võ Nguyên Giáp tổ chức"],["22/12/1944","Đội thành lập với 34 chiến sĩ trong rừng Trần Hưng Đạo (Nguyên Bình, Cao Bằng)"],["25 – 26/12/1944","Đội đánh thắng hai trận đầu tiên: đồn Phai Khắt (khoảng 17 giờ ngày 25/12) và đồn Nà Ngần (26/12)"],["Đầu 1945","Sang Côn Minh (Trung Quốc) tìm cách liên lạc với lực lượng Đồng minh chống phát xít; cuối tháng 4 trở về Pác Bó"],["9/3/1945","Nhật đảo chính, lật đổ Pháp trên toàn cõi Đông Dương"],["15/4/1945","Hội nghị Quân sự cách mạng Bắc Kỳ quyết định thống nhất các lực lượng vũ trang cách mạng"],["4/5/1945","Rời Pác Bó đi về phía nam; từ 5 đến 8/5 dừng ở căn cứ Lam Sơn (Cao Bằng)"],["15/5/1945","Đội Việt Nam Tuyên truyền Giải phóng quân hợp nhất với Cứu quốc quân thành Việt Nam Giải phóng quân"],["17 – 19/5/1945","Dừng ở Nà Kiến, gặp Võ Nguyên Giáp nghe báo cáo tình hình"],["21/5/1945","Đến Tân Trào (Tuyên Quang), nơi sẽ chỉ đạo Tổng khởi nghĩa"],["4/6/1945","Khu giải phóng Việt Bắc thành lập, gồm hầu hết các tỉnh Cao Bằng, Bắc Kạn, Lạng Sơn, Hà Giang, Tuyên Quang, Thái Nguyên"],["20/2/1961","Chủ tịch Hồ Chí Minh về thăm lại Pác Bó, gặp đồng bào ở cánh đồng Nà Chang"]],"doc":2},{"loai":"anh","src":"textures/bang_w/G12_3_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ xa."},{"loai":"doan","tieu_de":"Năm 1940: thời cơ gõ cửa","text":"Những mốc đầu tiên của bảng nằm ở năm 1940, trước ngày về nước. Tháng 6/1940, nước Pháp thua trận trước phát xít Đức. Tháng 9/1940, Nhật đánh vào Lạng Sơn, chính quyền thực dân ở Đông Dương chịu khuất phục. Liền sau đó là khởi nghĩa Bắc Sơn, rồi khởi nghĩa Nam Kỳ. Các cuộc nổi dậy bị đàn áp, nhưng cho thấy lòng dân đã sẵn sàng. Với Nguyễn Ái Quốc lúc ấy đang ở Trung Quốc, đó là những tín hiệu cho thấy phải về nước ngay.\n\nCuối năm 1940, Người tới vùng Tĩnh Tây, Quảng Tây, sát biên giới Cao Bằng, mở lớp huấn luyện cho cán bộ từ Cao Bằng sang. Những học viên ấy trở về gây dựng cơ sở, chuẩn bị nơi đón Người. Vì vậy, bước chân qua cột mốc 108 không phải một cuộc phiêu lưu. Đó là bước cuối của một kế hoạch đã chuẩn bị nhiều tháng, từ chọn địa điểm, đào tạo cán bộ đến bảo đảm an toàn giữa lòng dân.","doc":3},{"loai":"doan","tieu_de":"Năm 1941: một năm của những lần đầu tiên","text":"Năm 1941 là năm dày đặc mốc nhất trong bảng. Ngày 28/1, Người về nước. Ngày 8/2, Người chuyển vào hang Cốc Bó. Tháng 5, Hội nghị Trung ương lần thứ tám họp ở lán Khuổi Nặm, và ngày 19/5, Mặt trận Việt Minh ra đời. Ngày 6/6, thư “Kính cáo đồng bào” được gửi đi. Ngày 1/8, báo Việt Nam độc lập ra số đầu tiên. Cũng trong năm ấy, Người viết bài diễn ca “Lịch sử nước ta”, dịch sách, soạn tài liệu huấn luyện.\n\nĐằng sau các mốc là một cách làm việc có hệ thống. Trước hết là chỗ đứng an toàn, rồi đến đường lối, rồi đến tổ chức, rồi đến công cụ tuyên truyền. Mỗi mốc mở đường cho mốc sau. Đến cuối năm 1941, vùng Pác Bó đã trở thành nơi Trung ương Đảng chỉ đạo phong trào cách mạng, dù chỉ gồm mấy hang đá và lán nứa giữa rừng. Các chuyên đề khác trong gian kể kỹ từng sự kiện này.","doc":4},{"loai":"anh","src":"textures/bang_w/G12_3_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"1942 – 1943: người vắng mặt, phong trào vẫn lớn","text":"Ngày 13/8/1942, Người lên đường sang Trung Quốc để tranh thủ sự giúp đỡ quốc tế, lần đầu dùng tên Hồ Chí Minh. Chỉ hơn hai tuần sau, ngày 29/8/1942, Người bị bắt ở Túc Vinh, Quảng Tây, và bị giải qua nhiều nhà lao trong hơn một năm. Tập thơ chữ Hán “Nhật ký trong tù” ra đời trong những ngày ấy. Ngày 10/9/1943, Người được trả tự do, rồi hoạt động một thời gian ở Liễu Châu.\n\nĐiều đáng chú ý là phong trào ở Cao Bằng vẫn tiếp tục lớn mạnh khi Người vắng mặt. Năm 1942, khắp các châu trong tỉnh đều có hội Cứu quốc, trong đó có ba “châu hoàn toàn”. Ủy ban Việt Minh liên tỉnh Cao – Bắc – Lạng lập các ban “xung phong Nam tiến”, mở đường liên lạc xuống căn cứ Bắc Sơn – Võ Nhai. Những cán bộ được Người huấn luyện năm 1941 đã tự đứng vững. Đó có lẽ là thước đo rõ nhất cho hiệu quả của những lớp học giữa rừng.","doc":5},{"loai":"ban_co_biet","text":"Tên Hồ Chí Minh được Người sử dụng từ tháng 8/1942, khi lên đường sang Trung Quốc; trước đó, ở Pác Bó, bà con biết Người với tên Già Thu, hay gọi thân mật là “ông Ké”.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","doc":6},{"loai":"doan","tieu_de":"Mùa thu 1944: biết dừng để đi xa","text":"Tháng 9/1944, Người trở lại Pác Bó. Trong vòng ba tháng, bảng thời gian ghi liền ba quyết định quan trọng. Ngay sau khi về, Người đề nghị hoãn kế hoạch khởi nghĩa của Liên tỉnh ủy Cao – Bắc – Lạng, vì cả nước chưa sẵn sàng. Tháng 10/1944, Người viết thư gửi đồng bào toàn quốc, nhận định cơ hội giải phóng chỉ còn trong “một năm hoặc năm rưỡi nữa”. Tháng 12/1944, Người chỉ thị thành lập Đội Việt Nam Tuyên truyền Giải phóng quân, và ngày 22/12/1944 đội ra đời trong rừng Trần Hưng Đạo.\n\nBa quyết định ấy thoạt nhìn có vẻ trái chiều: vừa kìm lại, vừa thúc giục, vừa chuẩn bị lực lượng. Đặt cạnh nhau trên dòng thời gian, chúng khớp thành một chiến lược nhất quán. Không để phong trào tổn thất vì một cuộc nổi dậy non, nhưng cũng không để nó đứng yên. Ngày 25 và 26/12/1944, đội quân ba mươi tư người đánh thắng hai trận Phai Khắt, Nà Ngần, mở đầu truyền thống của quân đội ta (xem chuyên đề “34 chiến sĩ đầu tiên”).","doc":7},{"loai":"anh","src":"textures/bai/G12_v6.jpg","chu_thich":"Không gian 3D tái hiện gian Pác Bó – Cao Bằng.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Mùa xuân 1945: mười bảy ngày về Tân Trào","text":"Đầu năm 1945, Người sang Côn Minh, Trung Quốc, tìm cách liên lạc với lực lượng Đồng minh chống phát xít. Trong thời gian đó, ngày 9/3/1945, Nhật đảo chính lật đổ Pháp trên toàn Đông Dương. Ngày 15/4/1945, Hội nghị Quân sự cách mạng Bắc Kỳ quyết định thống nhất các lực lượng vũ trang. Cuối tháng 4, Người về lại Pác Bó, nhưng chỉ ở thêm ít ngày.\n\nNgày 4/5/1945, Người rời Pác Bó, bắt đầu chuyến đi về phía nam. Từ ngày 5 đến 8/5, Người dừng ở căn cứ Lam Sơn của Cao Bằng, rồi đi qua các vùng Ngân Sơn, Chợ Rã, Chợ Đồn. Từ ngày 17 đến 19/5, tại Nà Kiến, Người gặp Võ Nguyên Giáp. Ngày 21/5/1945, sau mười bảy ngày đường, Người tới Tân Trào. Hai tuần sau, ngày 4/6/1945, Khu giải phóng Việt Bắc được thành lập. Dòng thời gian của gian Pác Bó khép lại ở đây, để mở sang chặng Tân Trào và mùa thu Cách mạng.","doc":8},{"loai":"ban_co_biet","text":"Chuyến đi từ Pác Bó về Tân Trào năm 1945 kéo dài mười bảy ngày, từ 4/5 đến 21/5; riêng ở Nà Kiến, Người dừng lại ba ngày để gặp Võ Nguyên Giáp, trước khi tới Tân Trào.","nguon_ten":"Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch, “Hồ Chí Minh chặng đường từ Pác Bó về Tân Trào” – https://nhasanbacho.vn/bai-viet/ho-chi-minh-chang-duong-tu-pac-bo-ve-tan-trao/","doc":9},{"loai":"anh","src":"textures/bang_w/G12_3_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Những mốc còn lại hôm nay","text":"Nhiều mốc trong bảng nay đã trở thành địa danh có thể đến thăm. Cột mốc 108 năm xưa nay mang số hiệu 675 trên đường biên giới Việt – Trung. Hang Cốc Bó, suối Lê-nin, lán Khuổi Nặm nằm trong Khu di tích lịch sử Pác Bó, được xếp hạng di tích quốc gia đặc biệt năm 2012. Khu rừng Trần Hưng Đạo ở Nguyên Bình, nơi ba mươi tư chiến sĩ làm lễ thành lập, cũng là một điểm di tích. Theo dấu chuyến đi tháng 5/1945, khách có thể đi tiếp tới Tân Trào ở Tuyên Quang.\n\nBảng thời gian còn một mốc nằm ngoài chặng 1941 – 1945. Ngày 20/2/1961, dịp Tết Tân Sửu, Chủ tịch Hồ Chí Minh trở lại thăm Pác Bó và gặp đồng bào ở cánh đồng Nà Chang, hai mươi năm sau ngày về nước. Mốc cuối cùng ấy nối người lãnh tụ với vùng đất đã che chở Người trong những năm khó khăn nhất. Nó cũng nhắc rằng mọi mốc son trong bảng đều in dấu công sức của đồng bào các dân tộc Cao Bằng.","doc":10}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, tập 3, NXB Chính trị quốc gia, 2011","Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch, “Hồ Chí Minh chặng đường từ Pác Bó về Tân Trào” – https://nhasanbacho.vn/bai-viet/ho-chi-minh-chang-duong-tu-pac-bo-ve-tan-trao/","Cục Di sản văn hóa, “Di tích lịch sử Pác Bó” – https://dsvh.gov.vn/di-tich-lich-su-pac-bo-2950","Sách giáo khoa Lịch sử 9, NXB Giáo dục Việt Nam","Bảo tàng Hồ Chí Minh"],"doc":[{"t":"Từ cột mốc 108 đến đường về Tân Trào: dòng thời gian Pác Bó 1940 – 1945. Từ ngày qua cột mốc 108 đến ngày rời Pác Bó là hơn bốn năm ba tháng, nhưng Người chỉ thật sự ở vùng căn cứ khoảng một nửa quãng thời gian ấy. Phần còn lại là những tháng bị giam cầm và những chuyến đi xa. Dòng thời gian dưới đây xếp lại các mốc để thấy một nhịp điệu rõ ràng: chuẩn bị, chờ đợi, rồi chớp thời cơ."},{"t":"Bốn năm, hai khoảng vắng. Tính từ ngày 28/1/1941, khi Nguyễn Ái Quốc bước qua cột mốc 108, đến ngày 4/5/1945, khi Người rời Pác Bó về Tân Trào, là hơn bốn năm ba tháng. Nhưng nếu đánh dấu trên lịch những ngày Người thật sự có mặt ở vùng căn cứ Cao Bằng, ta sẽ thấy một bức tranh khác. Có hai khoảng vắng dài: hơn hai năm từ tháng 8/1942 đến tháng 9/1944, phần lớn trong các nhà lao ở Quảng Tây, và mấy tháng đầu năm 1945 khi Người sang Côn Minh. Cộng lại, Người chỉ ở Pác Bó và vùng lân cận khoảng một nửa quãng thời gian ấy. Vì thế, dòng thời gian của gian Pác Bó không phải một đường thẳng đều đặn. Nó có những đoạn dồn dập, như mùa xuân và mùa hè năm 1941, khi chỉ trong vài tháng đã có hang Cốc Bó, Hội nghị Trung ương lần thứ tám, Mặt trận Việt Minh, báo Việt Nam độc lập. Nó cũng có những khoảng lặng đầy lo âu, khi ở căn cứ không ai biết tin Người. Bảng mốc dưới đây xếp các sự kiện theo thứ tự, từ những biến động năm 1940 đến ngày Người tới Tân Trào, kèm một mốc trở về năm 1961."},{"t":"Các mốc thời gian. 6/1940: Nước Pháp thua trận, ký đình chiến với phát xít Đức; Nguyễn Ái Quốc nhận định thời cơ cho cách mạng Việt Nam đang tới gần. 22/9/1940: Quân Nhật đánh vào Lạng Sơn; chính quyền thực dân ở Đông Dương chịu khuất phục, nhân dân ta chịu cảnh “một cổ hai tròng”. 27/9/1940: Khởi nghĩa Bắc Sơn (Lạng Sơn) bùng nổ. 23/11/1940: Khởi nghĩa Nam Kỳ bùng nổ. Cuối 1940: Người tới vùng Tĩnh Tây (Quảng Tây, Trung Quốc) sát biên giới, mở lớp huấn luyện cho cán bộ Cao Bằng sang học. 28/1/1941: Mùng 2 Tết Tân Tỵ: vượt cột mốc 108 về nước, ở nhà ông Lý Quốc Súng trong bản Pác Bó; bà con gọi Người là Già Thu. 8/2/1941: Chuyển vào ở hang Cốc Bó; đặt tên suối Lê-nin, núi Các Mác. 2 – 3/1941: Dịch cuốn Lịch sử Đảng Cộng sản (b) Liên Xô, mở lớp huấn luyện cán bộ; cảnh sống đi vào bài thơ “Tức cảnh Pác Bó”. 10 – 19/5/1941: Chủ trì Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng tại lán Khuổi Nặm. 19/5/1941: Mặt trận Việt Nam Độc lập Đồng minh (Việt Minh) thành lập, đúng ngày sinh lần thứ 51 của Người. 6/6/1941: Thư “Kính cáo đồng bào”, kêu gọi toàn dân đoàn kết đánh Pháp, đuổi Nhật. 1/8/1941: Báo Việt Nam độc lập do Người sáng lập ra số đầu tiên. 2/1942: Việt Minh tuyên truyền bộ xuất bản bài diễn ca “Lịch sử nước ta” gồm 208 câu lục bát; cuối sách ghi “1945 – Việt Nam độc lập”. 1942: Khắp các châu ở Cao Bằng có hội Cứu quốc, trong đó có ba “châu hoàn toàn”. 13/8/1942: Lấy tên Hồ Chí Minh, lên đường sang Trung Quốc tranh thủ sự giúp đỡ quốc tế. 29/8/1942: Bị chính quyền Tưởng Giới Thạch bắt ở Túc Vinh (Quảng Tây); trong tù viết tập thơ “Nhật ký trong tù”. 1943: Ủy ban Việt Minh liên tỉnh Cao – Bắc – Lạng lập các ban “xung phong Nam tiến”, mở đường nối căn cứ Cao Bằng với Bắc Sơn – Võ Nhai. 10/9/1943: Được trả tự do; sau đó hoạt động một thời gian ở Liễu Châu (Quảng Tây). 9/1944: Trở lại Pác Bó; đề nghị hoãn kế hoạch khởi nghĩa của Liên tỉnh ủy Cao – Bắc – Lạng. 10/1944: Thư gửi đồng bào toàn quốc: cơ hội giải phóng “chỉ ở trong một năm hoặc năm rưỡi nữa”. 12/1944: Viết chỉ thị thành lập Đội Việt Nam Tuyên truyền Giải phóng quân, giao Võ Nguyên Giáp tổ chức. 22/12/1944: Đội thành lập với 34 chiến sĩ trong rừng Trần Hưng Đạo (Nguyên Bình, Cao Bằng). 25 – 26/12/1944: Đội đánh thắng hai trận đầu tiên: đồn Phai Khắt (khoảng 17 giờ ngày 25/12) và đồn Nà Ngần (26/12). Đầu 1945: Sang Côn Minh (Trung Quốc) tìm cách liên lạc với lực lượng Đồng minh chống phát xít; cuối tháng 4 trở về Pác Bó. 9/3/1945: Nhật đảo chính, lật đổ Pháp trên toàn cõi Đông Dương. 15/4/1945: Hội nghị Quân sự cách mạng Bắc Kỳ quyết định thống nhất các lực lượng vũ trang cách mạng. 4/5/1945: Rời Pác Bó đi về phía nam; từ 5 đến 8/5 dừng ở căn cứ Lam Sơn (Cao Bằng). 15/5/1945: Đội Việt Nam Tuyên truyền Giải phóng quân hợp nhất với Cứu quốc quân thành Việt Nam Giải phóng quân. 17 – 19/5/1945: Dừng ở Nà Kiến, gặp Võ Nguyên Giáp nghe báo cáo tình hình. 21/5/1945: Đến Tân Trào (Tuyên Quang), nơi sẽ chỉ đạo Tổng khởi nghĩa. 4/6/1945: Khu giải phóng Việt Bắc thành lập, gồm hầu hết các tỉnh Cao Bằng, Bắc Kạn, Lạng Sơn, Hà Giang, Tuyên Quang, Thái Nguyên. 20/2/1961: Chủ tịch Hồ Chí Minh về thăm lại Pác Bó, gặp đồng bào ở cánh đồng Nà Chang."},{"t":"Năm 1940: thời cơ gõ cửa. Những mốc đầu tiên của bảng nằm ở năm 1940, trước ngày về nước. Tháng 6/1940, nước Pháp thua trận trước phát xít Đức. Tháng 9/1940, Nhật đánh vào Lạng Sơn, chính quyền thực dân ở Đông Dương chịu khuất phục. Liền sau đó là khởi nghĩa Bắc Sơn, rồi khởi nghĩa Nam Kỳ. Các cuộc nổi dậy bị đàn áp, nhưng cho thấy lòng dân đã sẵn sàng. Với Nguyễn Ái Quốc lúc ấy đang ở Trung Quốc, đó là những tín hiệu cho thấy phải về nước ngay. Cuối năm 1940, Người tới vùng Tĩnh Tây, Quảng Tây, sát biên giới Cao Bằng, mở lớp huấn luyện cho cán bộ từ Cao Bằng sang. Những học viên ấy trở về gây dựng cơ sở, chuẩn bị nơi đón Người. Vì vậy, bước chân qua cột mốc 108 không phải một cuộc phiêu lưu. Đó là bước cuối của một kế hoạch đã chuẩn bị nhiều tháng, từ chọn địa điểm, đào tạo cán bộ đến bảo đảm an toàn giữa lòng dân."},{"t":"Năm 1941: một năm của những lần đầu tiên. Năm 1941 là năm dày đặc mốc nhất trong bảng. Ngày 28/1, Người về nước. Ngày 8/2, Người chuyển vào hang Cốc Bó. Tháng 5, Hội nghị Trung ương lần thứ tám họp ở lán Khuổi Nặm, và ngày 19/5, Mặt trận Việt Minh ra đời. Ngày 6/6, thư “Kính cáo đồng bào” được gửi đi. Ngày 1/8, báo Việt Nam độc lập ra số đầu tiên. Cũng trong năm ấy, Người viết bài diễn ca “Lịch sử nước ta”, dịch sách, soạn tài liệu huấn luyện. Đằng sau các mốc là một cách làm việc có hệ thống. Trước hết là chỗ đứng an toàn, rồi đến đường lối, rồi đến tổ chức, rồi đến công cụ tuyên truyền. Mỗi mốc mở đường cho mốc sau. Đến cuối năm 1941, vùng Pác Bó đã trở thành nơi Trung ương Đảng chỉ đạo phong trào cách mạng, dù chỉ gồm mấy hang đá và lán nứa giữa rừng. Các chuyên đề khác trong gian kể kỹ từng sự kiện này."},{"t":"1942 – 1943: người vắng mặt, phong trào vẫn lớn. Ngày 13/8/1942, Người lên đường sang Trung Quốc để tranh thủ sự giúp đỡ quốc tế, lần đầu dùng tên Hồ Chí Minh. Chỉ hơn hai tuần sau, ngày 29/8/1942, Người bị bắt ở Túc Vinh, Quảng Tây, và bị giải qua nhiều nhà lao trong hơn một năm. Tập thơ chữ Hán “Nhật ký trong tù” ra đời trong những ngày ấy. Ngày 10/9/1943, Người được trả tự do, rồi hoạt động một thời gian ở Liễu Châu. Điều đáng chú ý là phong trào ở Cao Bằng vẫn tiếp tục lớn mạnh khi Người vắng mặt. Năm 1942, khắp các châu trong tỉnh đều có hội Cứu quốc, trong đó có ba “châu hoàn toàn”. Ủy ban Việt Minh liên tỉnh Cao – Bắc – Lạng lập các ban “xung phong Nam tiến”, mở đường liên lạc xuống căn cứ Bắc Sơn – Võ Nhai. Những cán bộ được Người huấn luyện năm 1941 đã tự đứng vững. Đó có lẽ là thước đo rõ nhất cho hiệu quả của những lớp học giữa rừng."},{"t":"Bạn có biết? Tên Hồ Chí Minh được Người sử dụng từ tháng 8/1942, khi lên đường sang Trung Quốc; trước đó, ở Pác Bó, bà con biết Người với tên Già Thu, hay gọi thân mật là “ông Ké”."},{"t":"Mùa thu 1944: biết dừng để đi xa. Tháng 9/1944, Người trở lại Pác Bó. Trong vòng ba tháng, bảng thời gian ghi liền ba quyết định quan trọng. Ngay sau khi về, Người đề nghị hoãn kế hoạch khởi nghĩa của Liên tỉnh ủy Cao – Bắc – Lạng, vì cả nước chưa sẵn sàng. Tháng 10/1944, Người viết thư gửi đồng bào toàn quốc, nhận định cơ hội giải phóng chỉ còn trong “một năm hoặc năm rưỡi nữa”. Tháng 12/1944, Người chỉ thị thành lập Đội Việt Nam Tuyên truyền Giải phóng quân, và ngày 22/12/1944 đội ra đời trong rừng Trần Hưng Đạo. Ba quyết định ấy thoạt nhìn có vẻ trái chiều: vừa kìm lại, vừa thúc giục, vừa chuẩn bị lực lượng. Đặt cạnh nhau trên dòng thời gian, chúng khớp thành một chiến lược nhất quán. Không để phong trào tổn thất vì một cuộc nổi dậy non, nhưng cũng không để nó đứng yên. Ngày 25 và 26/12/1944, đội quân ba mươi tư người đánh thắng hai trận Phai Khắt, Nà Ngần, mở đầu truyền thống của quân đội ta (xem chuyên đề “34 chiến sĩ đầu tiên”)."},{"t":"Mùa xuân 1945: mười bảy ngày về Tân Trào. Đầu năm 1945, Người sang Côn Minh, Trung Quốc, tìm cách liên lạc với lực lượng Đồng minh chống phát xít. Trong thời gian đó, ngày 9/3/1945, Nhật đảo chính lật đổ Pháp trên toàn Đông Dương. Ngày 15/4/1945, Hội nghị Quân sự cách mạng Bắc Kỳ quyết định thống nhất các lực lượng vũ trang. Cuối tháng 4, Người về lại Pác Bó, nhưng chỉ ở thêm ít ngày. Ngày 4/5/1945, Người rời Pác Bó, bắt đầu chuyến đi về phía nam. Từ ngày 5 đến 8/5, Người dừng ở căn cứ Lam Sơn của Cao Bằng, rồi đi qua các vùng Ngân Sơn, Chợ Rã, Chợ Đồn. Từ ngày 17 đến 19/5, tại Nà Kiến, Người gặp Võ Nguyên Giáp. Ngày 21/5/1945, sau mười bảy ngày đường, Người tới Tân Trào. Hai tuần sau, ngày 4/6/1945, Khu giải phóng Việt Bắc được thành lập. Dòng thời gian của gian Pác Bó khép lại ở đây, để mở sang chặng Tân Trào và mùa thu Cách mạng."},{"t":"Bạn có biết? Chuyến đi từ Pác Bó về Tân Trào năm 1945 kéo dài mười bảy ngày, từ 4/5 đến 21/5; riêng ở Nà Kiến, Người dừng lại ba ngày để gặp Võ Nguyên Giáp, trước khi tới Tân Trào."},{"t":"Những mốc còn lại hôm nay. Nhiều mốc trong bảng nay đã trở thành địa danh có thể đến thăm. Cột mốc 108 năm xưa nay mang số hiệu 675 trên đường biên giới Việt – Trung. Hang Cốc Bó, suối Lê-nin, lán Khuổi Nặm nằm trong Khu di tích lịch sử Pác Bó, được xếp hạng di tích quốc gia đặc biệt năm 2012. Khu rừng Trần Hưng Đạo ở Nguyên Bình, nơi ba mươi tư chiến sĩ làm lễ thành lập, cũng là một điểm di tích. Theo dấu chuyến đi tháng 5/1945, khách có thể đi tiếp tới Tân Trào ở Tuyên Quang. Bảng thời gian còn một mốc nằm ngoài chặng 1941 – 1945. Ngày 20/2/1961, dịp Tết Tân Sửu, Chủ tịch Hồ Chí Minh trở lại thăm Pác Bó và gặp đồng bào ở cánh đồng Nà Chang, hai mươi năm sau ngày về nước. Mốc cuối cùng ấy nối người lãnh tụ với vùng đất đã che chở Người trong những năm khó khăn nhất. Nó cũng nhắc rằng mọi mốc son trong bảng đều in dấu công sức của đồng bào các dân tộc Cao Bằng."}],"so_chu":1422},{"i":4,"tieu_de_bang":"Hang Cốc Bó, nơi Người ở những ngày đầu về nước","tieu_de":"Hang Cốc Bó qua một tấm ảnh: tám mươi mét vuông đá và mùa xuân năm 1941","sapo":"Một khoảng tối nhỏ dưới chân vách núi đá vôi, trước mặt là dòng suối trong. Nhìn thoáng qua, tấm ảnh chụp đầu năm 2016 chỉ như một góc thắng cảnh miền biên viễn. Nhưng sau cửa hang hẹp ấy, bảy mươi lăm năm trước, người vừa trở về sau ba mươi năm xa Tổ quốc đã sống những tuần giá rét đầu tiên trên quê hương. Vì sao Người chọn một hang đá làm nhà, và điều gì đã giữ an toàn cho Người?","bia":{"src":"textures/ht/ht_anh_coc_bo.jpg","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một khoảng tối dưới vách đá","text":"Tấm ảnh được chụp ngày 8/1/2016, giữa mùa đông vùng cao Cao Bằng. Trong khung hình là một cửa hang thấp nép dưới chân vách núi đá vôi, phía trước là dòng suối trong chảy qua lòng đá. Người chụp ký tên Tycho, đưa ảnh lên kho ảnh tự do Wikimedia Commons theo giấy phép CC BY-SA 3.0, nhờ vậy bảo tàng có thể sử dụng lại một cách hợp pháp, kèm tên tác giả.\n\nNếu không có dòng chú thích, người xem dễ nghĩ đây chỉ là một góc núi rừng như trăm nghìn góc núi rừng khác ở miền biên giới phía Bắc. Nhưng khoảng tối ấy là cửa hang Cốc Bó, thuộc bản Pác Bó, xã Trường Hà, huyện Hà Quảng. Bảy mươi lăm năm trước ngày bấm máy, cũng vào những tuần rét buốt đầu năm, nơi đây là chỗ ở của Nguyễn Ái Quốc. Người vừa trở về Tổ quốc sau ba mươi năm hoạt động ở nước ngoài, với tư cách đại diện Quốc tế Cộng sản, để trực tiếp lãnh đạo cách mạng trong nước. Tấm ảnh vì thế không chỉ ghi lại một cảnh vật. Nó đặt ra một câu hỏi: vì sao con người ấy lại chọn một hang đá làm nhà, và điều gì đã diễn ra sau cửa hang nhỏ bé này?","doc":1},{"loai":"anh","src":"textures/bang_w/G12_4_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hang Cốc Bó, nơi Người ở những ngày đầu về nước”, nhìn từ xa."},{"loai":"doan","tieu_de":"Mùa xuân Tân Tỵ, một cuộc trở về bí mật","text":"Trưa 28/1/1941, tức mùng 2 Tết Tân Tỵ, Nguyễn Ái Quốc cùng các đồng chí Lê Quảng Ba, Phùng Chí Kiên, Vũ Anh vượt qua cột mốc biên giới 108 về Pác Bó (xem chuyên đề Trở về Tổ quốc). Những ngày đầu, Người ở nhà ông Lý Quốc Súng trong bản. Từ ngày 8/2/1941, Người chuyển vào hang Cốc Bó và ở đó đến khoảng giữa tháng 3/1941.\n\nBối cảnh lúc ấy vô cùng căng thẳng. Phát xít Nhật đã kéo vào Đông Dương từ tháng 9/1940, nhân dân ta chịu cảnh một cổ hai tròng. Khởi nghĩa Bắc Sơn nổ ra cuối tháng 9, khởi nghĩa Nam Kỳ nổ ra ngày 23/11/1940, cả hai đều bị đàn áp đẫm máu. Sau đó, chính quyền thực dân mở những đợt khủng bố gắt gao, nhiều cán bộ bị bắt, nhiều cơ sở bị vỡ, mạng lưới mật thám được siết chặt khắp nơi. Ở vùng biên giới, sự xuất hiện của người lạ luôn bị dòm ngó. Trong hoàn cảnh đó, giữ bí mật tuyệt đối là điều kiện sống còn, không chỉ cho Người mà cho cả bộ máy lãnh đạo đang được gây dựng lại. Rời nhà dân vào ở trong hang là một bước trong kế hoạch giữ bí mật ấy.","doc":2},{"loai":"ban_co_biet","text":"Tháng 10/1929, Tòa án Nam triều ở Vinh đã xử vắng mặt và kết án tử hình Nguyễn Ái Quốc. Vì vậy, khi về nước năm 1941, Người vẫn là một người bị chính quyền thực dân truy nã, mọi dấu vết đều phải giữ kín tuyệt đối.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","doc":3},{"loai":"doan","tieu_de":"Tám mươi mét vuông đá","text":"Theo mô tả của Cục Di sản văn hóa, lòng hang Cốc Bó rộng khoảng 80 mét vuông, nhưng cửa hang rất hẹp, chỉ vừa một người đi. Chính cái cửa nhỏ ấy làm cho hang trở nên kín đáo giữa vách núi. Hang nằm dưới chân núi, sát đầu nguồn con suối, cách xa đường đi lại của bản. Pác Bó lại chỉ cách đường biên một quãng ngắn, nên khi có động, người trong hang có thể nhanh chóng lánh sang phía bên kia.\n\nĐá vôi vùng này bị nước bào mòn qua thời gian rất dài, tạo nên vô số hang hốc, khe ngách, rừng cây phủ kín sườn núi. Với người hoạt động bí mật, đó là một pháo đài tự nhiên. Nhưng pháo đài ấy cũng rất khắc nghiệt. Vách đá lạnh, nền hang ẩm, hơi nước từ dòng suối bốc lên, trong khi tháng Hai, tháng Ba ở vùng núi Cao Bằng vẫn còn rét buốt. Những vật dụng ít ỏi bên trong hang như tấm ván làm giường, bếp lửa nhỏ và chiếc hòm gỗ được kể riêng ở chuyên đề Hang Cốc Bó. Ở đây chỉ cần hình dung: người đứng đầu phong trào cách mạng đã sống những tuần đầu tiên trên quê hương trong một không gian đá chật hẹp và thiếu ánh sáng như thế.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_coc_bo.jpg","chu_thich":"Cửa hang Cốc Bó dưới chân vách núi đá vôi, Khu di tích lịch sử Pác Bó (Hà Quảng, Cao Bằng) – nơi Nguyễn Ái Quốc ở từ ngày 8/2 đến khoảng giữa tháng 3/1941. Ảnh: Tycho, ngày 8/1/2016, giấy phép CC BY-SA 3.0.","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Một người bị truy lùng hơn hai mươi năm","text":"Muốn hiểu vì sao phải cẩn trọng đến vậy, cần nhìn lại hành trình của Người. Từ năm 1919, khi bản Yêu sách của nhân dân An Nam ký tên Nguyễn Ái Quốc được gửi tới Hội nghị Véc-xây, mật thám Pháp đã theo dõi từng bước chân của người thanh niên ấy. Năm 1929, Người bị kết án tử hình vắng mặt. Năm 1931, Người bị nhà cầm quyền Anh bắt ở Hồng Kông và chỉ thoát được sau một vụ kiện kéo dài (xem chuyên đề về người tù Tống Văn Sơ).\n\nNhư vậy, khi đặt chân về Pác Bó, Người đã bị truy lùng hơn hai mươi năm. Một sơ hở nhỏ có thể dẫn tới hậu quả khôn lường. Vì thế Người mang tên Già Thu, ăn mặc, sinh hoạt như đồng bào địa phương, bà con quen gọi thân mật là ông Ké. Hang Cốc Bó là một phần của lớp vỏ bọc ấy: một chỗ ở không có địa chỉ, không có hàng xóm, chỉ có núi đá, rừng cây và tiếng suối. Từ nơi kín đáo ấy, Người vẫn nắm tình hình trong nước qua các cán bộ liên lạc, gặp gỡ những người được tin cậy, và chuẩn bị cho các công việc lớn của mùa xuân năm 1941.","doc":5},{"loai":"doan","tieu_de":"Tấm lá chắn là lòng dân","text":"Núi đá chỉ che được thân người, điều thực sự giữ được bí mật là lòng dân. Pác Bó là bản của đồng bào Tày, Nùng ở vùng đất mà phong trào cách mạng đã bén rễ từ đầu những năm 1930. Gia đình ông Lý Quốc Súng là những người đầu tiên cưu mang Người khi Người vừa qua biên giới. Những cán bộ người Cao Bằng như Lê Quảng Ba am hiểu tiếng nói, phong tục và từng lối mòn trong vùng, trở thành cầu nối giữa Người với cơ sở.\n\nBà con tiếp tế gạo, ngô, rau, canh gác các lối vào, đưa đường cho cán bộ đi lại, và nhất là giữ kín tuyệt đối sự có mặt của ông Ké. Người không sống tách biệt khỏi họ. Người cùng anh em cán bộ làm lụng, tăng gia, hỏi han đời sống của bà con trong bản. Về sau, sức mạnh của lòng dân được Người nói gọn trong một câu nổi tiếng: “Dễ trăm lần không dân cũng chịu, khó vạn lần dân liệu cũng xong”. Hang Cốc Bó trong tấm ảnh vì thế không chỉ là một chỗ ẩn náu. Nó là bằng chứng về sự đùm bọc của đồng bào các dân tộc vùng biên đối với cách mạng.","doc":6},{"loai":"anh","src":"textures/bang_w/G12_4_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hang Cốc Bó, nơi Người ở những ngày đầu về nước”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Rời hang, nhưng không rời Pác Bó","text":"Người ở hang Cốc Bó đến khoảng giữa tháng 3/1941. Sau đó, khi địch lùng sục gắt gao và công việc ngày một nhiều, Người chuyển sang lán Khuổi Nặm cùng một số nơi ở kín đáo khác trong vùng. Tháng 5/1941, tại Khuổi Nặm, Người chủ trì Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng (xem chuyên đề Lán Khuổi Nặm).\n\nTháng 8/1942, Người lên đường sang Trung Quốc với tên Hồ Chí Minh, bị chính quyền Tưởng Giới Thạch bắt giam hơn một năm. Tháng 9/1944, Người trở lại Pác Bó, rồi tháng 5/1945 rời Cao Bằng về Tân Trào. Trong suốt những năm ấy, hang Cốc Bó không còn là nơi ở thường xuyên. Nhưng những tuần trong hang là quãng thời gian đặt nền móng. Chính ở đây, Người bắt đầu dịch sách, soạn tài liệu huấn luyện, gặp gỡ cán bộ và chuẩn bị nội dung cho hội nghị tháng Năm. Cũng cảnh sống nơi đây đã đi vào bài thơ “Tức cảnh Pác Bó” với câu mở đầu quen thuộc “Sáng ra bờ suối, tối vào hang” (xem chuyên đề Lời Bác). Một hang đá nhỏ ở đầu nguồn đã trở thành điểm xuất phát của cả một giai đoạn cách mạng.","doc":7},{"loai":"doan","tieu_de":"Hai mươi năm sau, người Chủ tịch trở lại","text":"Ngày 20/2/1961, trong những ngày Tết Tân Sửu, Chủ tịch Hồ Chí Minh về thăm Pác Bó. Hai mươi năm đã trôi qua kể từ mùa xuân Tân Tỵ. Hai mươi năm trước, Người sống ở đây như một chiến sĩ hoạt động bí mật, trong hang đá, với tên gọi Già Thu. Nay Người trở lại với tư cách Chủ tịch nước Việt Nam Dân chủ Cộng hòa, trong khi đất nước còn tạm thời chia cắt và miền Bắc đang xây dựng cuộc sống mới.\n\nTheo tư liệu của Cục Di sản văn hóa, trong chuyến thăm này, Người đến thăm khu ruộng Nà Chang và nói chuyện với nhân dân Pác Bó. Chi tiết ấy rất đáng suy ngẫm. Hai mươi năm trước, bà con đã che giấu, nuôi nấng Người giữa núi rừng. Hai mươi năm sau, điều Người quan tâm khi trở lại là ruộng đồng, là đời sống và sản xuất của chính những người dân ấy. Với những người từng tiếp tế, canh gác cho ông Ké năm nào, cuộc gặp gỡ mùa xuân năm 1961 là một kỷ niệm không thể quên. Với lịch sử, đó là một vòng tròn khép lại: từ hang đá bí mật đến ngày Người trở về như người đứng đầu một nhà nước độc lập.","doc":8},{"loai":"ban_co_biet","text":"Ngày 10/5/2012, Thủ tướng Chính phủ ký Quyết định số 548/QĐ-TTg xếp hạng Di tích lịch sử Pác Bó, trong đó có hang Cốc Bó, là di tích quốc gia đặc biệt, bậc xếp hạng cao nhất đối với di tích ở Việt Nam.","nguon_ten":"Cục Di sản văn hóa, “Di tích lịch sử Pác Bó” – https://dsvh.gov.vn/di-tich-lich-su-pac-bo-2950","doc":9},{"loai":"anh","src":"textures/bang_w/G12_4_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hang Cốc Bó, nơi Người ở những ngày đầu về nước”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, hang Cốc Bó là một điểm trung tâm của Khu di tích lịch sử Pác Bó. Quần thể di tích trải dọc thung lũng đầu nguồn, gồm cột mốc biên giới năm xưa nay mang số hiệu 675, nhà ông Lý Quốc Súng, hang Cốc Bó, suối Lê-nin, núi Các Mác, “bàn đá chông chênh” và lán Khuổi Nặm. Đi qua các điểm ấy, người xem có thể lần theo đúng trình tự những tuần đầu của năm 1941: vượt biên giới, dừng chân trong bản, rồi vào ở giữa núi rừng.\n\nTấm ảnh năm 2016 trong gian trưng bày chỉ là một lát cắt nhỏ của khung cảnh ấy. Nó được chụp vào tháng Giêng dương lịch, gần đúng mùa mà Người đã sống trong hang, khi núi rừng còn chìm trong khí lạnh. Nhìn cửa hang hẹp, người xem có thể hình dung những đêm rét bên bếp lửa nhỏ, những buổi sáng ra bờ suối làm việc, những cuộc gặp gỡ lặng lẽ với cán bộ từ xa đến. Hơn tám mươi năm đã qua, cửa hang vẫn nằm đó dưới vách núi. Nó nhắc rằng con đường dẫn tới ngày độc lập mùa thu năm 1945 đã bắt đầu từ một nơi giản dị đến như vậy.","doc":10}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1 và tập 2, NXB Chính trị quốc gia","Cục Di sản văn hóa, “Di tích lịch sử Pác Bó” – https://dsvh.gov.vn/di-tich-lich-su-pac-bo-2950","Báo Nhân Dân, “85 năm Ngày Bác Hồ trở về Tổ quốc, mở ra thời kỳ mới của cách mạng Việt Nam” – https://nhandan.vn/85-nam-ngay-bac-ho-tro-ve-to-quoc-mo-ra-thoi-ky-moi-cua-cach-mang-viet-nam-post939544.html","Khu di tích lịch sử Pác Bó (Cao Bằng)","Bảo tàng Hồ Chí Minh","Ảnh: Tycho, Wikimedia Commons, 2016, CC BY-SA 3.0"],"doc":[{"t":"Hang Cốc Bó qua một tấm ảnh: tám mươi mét vuông đá và mùa xuân năm 1941. Một khoảng tối nhỏ dưới chân vách núi đá vôi, trước mặt là dòng suối trong. Nhìn thoáng qua, tấm ảnh chụp đầu năm 2016 chỉ như một góc thắng cảnh miền biên viễn. Nhưng sau cửa hang hẹp ấy, bảy mươi lăm năm trước, người vừa trở về sau ba mươi năm xa Tổ quốc đã sống những tuần giá rét đầu tiên trên quê hương. Vì sao Người chọn một hang đá làm nhà, và điều gì đã giữ an toàn cho Người?"},{"t":"Một khoảng tối dưới vách đá. Tấm ảnh được chụp ngày 8/1/2016, giữa mùa đông vùng cao Cao Bằng. Trong khung hình là một cửa hang thấp nép dưới chân vách núi đá vôi, phía trước là dòng suối trong chảy qua lòng đá. Người chụp ký tên Tycho, đưa ảnh lên kho ảnh tự do Wikimedia Commons theo giấy phép CC BY-SA 3.0, nhờ vậy bảo tàng có thể sử dụng lại một cách hợp pháp, kèm tên tác giả. Nếu không có dòng chú thích, người xem dễ nghĩ đây chỉ là một góc núi rừng như trăm nghìn góc núi rừng khác ở miền biên giới phía Bắc. Nhưng khoảng tối ấy là cửa hang Cốc Bó, thuộc bản Pác Bó, xã Trường Hà, huyện Hà Quảng. Bảy mươi lăm năm trước ngày bấm máy, cũng vào những tuần rét buốt đầu năm, nơi đây là chỗ ở của Nguyễn Ái Quốc. Người vừa trở về Tổ quốc sau ba mươi năm hoạt động ở nước ngoài, với tư cách đại diện Quốc tế Cộng sản, để trực tiếp lãnh đạo cách mạng trong nước. Tấm ảnh vì thế không chỉ ghi lại một cảnh vật. Nó đặt ra một câu hỏi: vì sao con người ấy lại chọn một hang đá làm nhà, và điều gì đã diễn ra sau cửa hang nhỏ bé này?"},{"t":"Mùa xuân Tân Tỵ, một cuộc trở về bí mật. Trưa 28/1/1941, tức mùng 2 Tết Tân Tỵ, Nguyễn Ái Quốc cùng các đồng chí Lê Quảng Ba, Phùng Chí Kiên, Vũ Anh vượt qua cột mốc biên giới 108 về Pác Bó (xem chuyên đề Trở về Tổ quốc). Những ngày đầu, Người ở nhà ông Lý Quốc Súng trong bản. Từ ngày 8/2/1941, Người chuyển vào hang Cốc Bó và ở đó đến khoảng giữa tháng 3/1941. Bối cảnh lúc ấy vô cùng căng thẳng. Phát xít Nhật đã kéo vào Đông Dương từ tháng 9/1940, nhân dân ta chịu cảnh một cổ hai tròng. Khởi nghĩa Bắc Sơn nổ ra cuối tháng 9, khởi nghĩa Nam Kỳ nổ ra ngày 23/11/1940, cả hai đều bị đàn áp đẫm máu. Sau đó, chính quyền thực dân mở những đợt khủng bố gắt gao, nhiều cán bộ bị bắt, nhiều cơ sở bị vỡ, mạng lưới mật thám được siết chặt khắp nơi. Ở vùng biên giới, sự xuất hiện của người lạ luôn bị dòm ngó. Trong hoàn cảnh đó, giữ bí mật tuyệt đối là điều kiện sống còn, không chỉ cho Người mà cho cả bộ máy lãnh đạo đang được gây dựng lại. Rời nhà dân vào ở trong hang là một bước trong kế hoạch giữ bí mật ấy."},{"t":"Bạn có biết? Tháng 10/1929, Tòa án Nam triều ở Vinh đã xử vắng mặt và kết án tử hình Nguyễn Ái Quốc. Vì vậy, khi về nước năm 1941, Người vẫn là một người bị chính quyền thực dân truy nã, mọi dấu vết đều phải giữ kín tuyệt đối."},{"t":"Tám mươi mét vuông đá. Theo mô tả của Cục Di sản văn hóa, lòng hang Cốc Bó rộng khoảng 80 mét vuông, nhưng cửa hang rất hẹp, chỉ vừa một người đi. Chính cái cửa nhỏ ấy làm cho hang trở nên kín đáo giữa vách núi. Hang nằm dưới chân núi, sát đầu nguồn con suối, cách xa đường đi lại của bản. Pác Bó lại chỉ cách đường biên một quãng ngắn, nên khi có động, người trong hang có thể nhanh chóng lánh sang phía bên kia. Đá vôi vùng này bị nước bào mòn qua thời gian rất dài, tạo nên vô số hang hốc, khe ngách, rừng cây phủ kín sườn núi. Với người hoạt động bí mật, đó là một pháo đài tự nhiên. Nhưng pháo đài ấy cũng rất khắc nghiệt. Vách đá lạnh, nền hang ẩm, hơi nước từ dòng suối bốc lên, trong khi tháng Hai, tháng Ba ở vùng núi Cao Bằng vẫn còn rét buốt. Những vật dụng ít ỏi bên trong hang như tấm ván làm giường, bếp lửa nhỏ và chiếc hòm gỗ được kể riêng ở chuyên đề Hang Cốc Bó. Ở đây chỉ cần hình dung: người đứng đầu phong trào cách mạng đã sống những tuần đầu tiên trên quê hương trong một không gian đá chật hẹp và thiếu ánh sáng như thế."},{"t":"Một người bị truy lùng hơn hai mươi năm. Muốn hiểu vì sao phải cẩn trọng đến vậy, cần nhìn lại hành trình của Người. Từ năm 1919, khi bản Yêu sách của nhân dân An Nam ký tên Nguyễn Ái Quốc được gửi tới Hội nghị Véc-xây, mật thám Pháp đã theo dõi từng bước chân của người thanh niên ấy. Năm 1929, Người bị kết án tử hình vắng mặt. Năm 1931, Người bị nhà cầm quyền Anh bắt ở Hồng Kông và chỉ thoát được sau một vụ kiện kéo dài (xem chuyên đề về người tù Tống Văn Sơ). Như vậy, khi đặt chân về Pác Bó, Người đã bị truy lùng hơn hai mươi năm. Một sơ hở nhỏ có thể dẫn tới hậu quả khôn lường. Vì thế Người mang tên Già Thu, ăn mặc, sinh hoạt như đồng bào địa phương, bà con quen gọi thân mật là ông Ké. Hang Cốc Bó là một phần của lớp vỏ bọc ấy: một chỗ ở không có địa chỉ, không có hàng xóm, chỉ có núi đá, rừng cây và tiếng suối. Từ nơi kín đáo ấy, Người vẫn nắm tình hình trong nước qua các cán bộ liên lạc, gặp gỡ những người được tin cậy, và chuẩn bị cho các công việc lớn của mùa xuân năm 1941."},{"t":"Tấm lá chắn là lòng dân. Núi đá chỉ che được thân người, điều thực sự giữ được bí mật là lòng dân. Pác Bó là bản của đồng bào Tày, Nùng ở vùng đất mà phong trào cách mạng đã bén rễ từ đầu những năm 1930. Gia đình ông Lý Quốc Súng là những người đầu tiên cưu mang Người khi Người vừa qua biên giới. Những cán bộ người Cao Bằng như Lê Quảng Ba am hiểu tiếng nói, phong tục và từng lối mòn trong vùng, trở thành cầu nối giữa Người với cơ sở. Bà con tiếp tế gạo, ngô, rau, canh gác các lối vào, đưa đường cho cán bộ đi lại, và nhất là giữ kín tuyệt đối sự có mặt của ông Ké. Người không sống tách biệt khỏi họ. Người cùng anh em cán bộ làm lụng, tăng gia, hỏi han đời sống của bà con trong bản. Về sau, sức mạnh của lòng dân được Người nói gọn trong một câu nổi tiếng: “Dễ trăm lần không dân cũng chịu, khó vạn lần dân liệu cũng xong”. Hang Cốc Bó trong tấm ảnh vì thế không chỉ là một chỗ ẩn náu. Nó là bằng chứng về sự đùm bọc của đồng bào các dân tộc vùng biên đối với cách mạng."},{"t":"Rời hang, nhưng không rời Pác Bó. Người ở hang Cốc Bó đến khoảng giữa tháng 3/1941. Sau đó, khi địch lùng sục gắt gao và công việc ngày một nhiều, Người chuyển sang lán Khuổi Nặm cùng một số nơi ở kín đáo khác trong vùng. Tháng 5/1941, tại Khuổi Nặm, Người chủ trì Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng (xem chuyên đề Lán Khuổi Nặm). Tháng 8/1942, Người lên đường sang Trung Quốc với tên Hồ Chí Minh, bị chính quyền Tưởng Giới Thạch bắt giam hơn một năm. Tháng 9/1944, Người trở lại Pác Bó, rồi tháng 5/1945 rời Cao Bằng về Tân Trào. Trong suốt những năm ấy, hang Cốc Bó không còn là nơi ở thường xuyên. Nhưng những tuần trong hang là quãng thời gian đặt nền móng. Chính ở đây, Người bắt đầu dịch sách, soạn tài liệu huấn luyện, gặp gỡ cán bộ và chuẩn bị nội dung cho hội nghị tháng Năm. Cũng cảnh sống nơi đây đã đi vào bài thơ “Tức cảnh Pác Bó” với câu mở đầu quen thuộc “Sáng ra bờ suối, tối vào hang” (xem chuyên đề Lời Bác). Một hang đá nhỏ ở đầu nguồn đã trở thành điểm xuất phát của cả một giai đoạn cách mạng."},{"t":"Hai mươi năm sau, người Chủ tịch trở lại. Ngày 20/2/1961, trong những ngày Tết Tân Sửu, Chủ tịch Hồ Chí Minh về thăm Pác Bó. Hai mươi năm đã trôi qua kể từ mùa xuân Tân Tỵ. Hai mươi năm trước, Người sống ở đây như một chiến sĩ hoạt động bí mật, trong hang đá, với tên gọi Già Thu. Nay Người trở lại với tư cách Chủ tịch nước Việt Nam Dân chủ Cộng hòa, trong khi đất nước còn tạm thời chia cắt và miền Bắc đang xây dựng cuộc sống mới. Theo tư liệu của Cục Di sản văn hóa, trong chuyến thăm này, Người đến thăm khu ruộng Nà Chang và nói chuyện với nhân dân Pác Bó. Chi tiết ấy rất đáng suy ngẫm. Hai mươi năm trước, bà con đã che giấu, nuôi nấng Người giữa núi rừng. Hai mươi năm sau, điều Người quan tâm khi trở lại là ruộng đồng, là đời sống và sản xuất của chính những người dân ấy. Với những người từng tiếp tế, canh gác cho ông Ké năm nào, cuộc gặp gỡ mùa xuân năm 1961 là một kỷ niệm không thể quên. Với lịch sử, đó là một vòng tròn khép lại: từ hang đá bí mật đến ngày Người trở về như người đứng đầu một nhà nước độc lập."},{"t":"Bạn có biết? Ngày 10/5/2012, Thủ tướng Chính phủ ký Quyết định số 548/QĐ-TTg xếp hạng Di tích lịch sử Pác Bó, trong đó có hang Cốc Bó, là di tích quốc gia đặc biệt, bậc xếp hạng cao nhất đối với di tích ở Việt Nam."},{"t":"Dấu tích hôm nay. Ngày nay, hang Cốc Bó là một điểm trung tâm của Khu di tích lịch sử Pác Bó. Quần thể di tích trải dọc thung lũng đầu nguồn, gồm cột mốc biên giới năm xưa nay mang số hiệu 675, nhà ông Lý Quốc Súng, hang Cốc Bó, suối Lê-nin, núi Các Mác, “bàn đá chông chênh” và lán Khuổi Nặm. Đi qua các điểm ấy, người xem có thể lần theo đúng trình tự những tuần đầu của năm 1941: vượt biên giới, dừng chân trong bản, rồi vào ở giữa núi rừng. Tấm ảnh năm 2016 trong gian trưng bày chỉ là một lát cắt nhỏ của khung cảnh ấy. Nó được chụp vào tháng Giêng dương lịch, gần đúng mùa mà Người đã sống trong hang, khi núi rừng còn chìm trong khí lạnh. Nhìn cửa hang hẹp, người xem có thể hình dung những đêm rét bên bếp lửa nhỏ, những buổi sáng ra bờ suối làm việc, những cuộc gặp gỡ lặng lẽ với cán bộ từ xa đến. Hơn tám mươi năm đã qua, cửa hang vẫn nằm đó dưới vách núi. Nó nhắc rằng con đường dẫn tới ngày độc lập mùa thu năm 1945 đã bắt đầu từ một nơi giản dị đến như vậy."}],"so_chu":1917},{"i":5,"tieu_de_bang":"Suối Lê-nin dưới chân núi Các Mác","tieu_de":"Suối Lê-nin, núi Các Mác: hai cái tên Nguyễn Ái Quốc gửi vào núi sông đầu nguồn","sapo":"Một dòng suối xanh trong chảy dưới chân ngọn núi đá vôi, cảnh vật như bao thung lũng khác ở miền biên viễn Cao Bằng. Điều khác biệt nằm ở tên gọi. Mùa xuân năm 1941, người vừa trở về sau ba mươi năm đã đặt cho dòng suối và ngọn núi tên của hai con người mà Người coi là những bậc soi đường. Câu chuyện của hai cái tên ấy bắt đầu từ một trang báo ở Paris hơn hai mươi năm trước.","bia":{"src":"textures/ht/ht_anh_pac_bo.jpg","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Buổi chiều bên dòng suối đầu nguồn","text":"Tấm ảnh được chụp lúc gần bốn giờ chiều ngày 8/1/2016, cùng ngày với tấm ảnh cửa hang Cốc Bó. Khung hình ghi lại dòng suối nước xanh trong dưới chân một ngọn núi đá vôi sừng sững. Trong tiếng Tày, Pác Bó nghĩa là đầu nguồn, nơi dòng nước bắt đầu chảy ra từ lòng núi. Con suối ở đây chảy trên lòng cuội, hai bờ là cỏ lau và những tảng đá phủ rêu.\n\nHang Cốc Bó nằm ngay gần đầu nguồn ấy. Với người ở trong hang, con suối vừa là nguồn nước sinh hoạt, vừa là nơi làm việc mỗi ngày, như câu thơ “Sáng ra bờ suối, tối vào hang”. Mùa xuân năm 1941, Nguyễn Ái Quốc đặt cho dòng suối cái tên suối Lê-nin, và cho ngọn núi phía sau hang cái tên núi Các Mác. Hơn tám mươi năm đã qua, hai cái tên ấy vẫn là tên gọi của các điểm trong khu di tích, xuất hiện trong lời thuyết minh, trong sách báo và trong trí nhớ của nhiều thế hệ người Việt. Cảnh vật trong ảnh vì thế mang hai lớp nghĩa: một thắng cảnh thiên nhiên của miền biên viễn, và một lời khẳng định về lý tưởng của người đã đặt tên cho nó.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_pac_bo.jpg","chu_thich":"Suối Lê-nin dưới chân núi Các Mác, Khu di tích lịch sử Pác Bó (Hà Quảng, Cao Bằng). Ảnh: Tycho, chiều 8/1/2016, giấy phép CC BY-SA 3.0.","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Hai cái tên đặt giữa núi rừng","text":"Người đặt những cái tên ấy trong các tuần ở hang Cốc Bó, khoảng tháng 2 và tháng 3/1941. Dòng suối chảy ngay trước cửa hang, ngọn núi sừng sững phía sau. Hằng ngày, đi ra đi vào, Người và những cán bộ quanh mình đều ở giữa hai cái tên ấy. Người không dựng bia, không treo khẩu hiệu. Người chỉ gọi tên núi, tên suối, và để những cái tên đi vào lời ăn tiếng nói thường ngày.\n\nThời điểm đặt tên cũng rất đáng chú ý. Đó là lúc tổ chức Đảng trong nước vừa trải qua những tổn thất nặng nề sau các cuộc khởi nghĩa cuối năm 1940, nhiều cán bộ chủ chốt bị bắt. Phong trào cần được củng cố lại cả về tổ chức lẫn tư tưởng. Người trở về với tư cách đại diện Quốc tế Cộng sản, mang theo kinh nghiệm hơn hai mươi năm hoạt động trong phong trào cộng sản quốc tế. Cũng trong những tuần ấy, Người dịch cuốn Lịch sử Đảng Cộng sản (b) Liên Xô làm tài liệu huấn luyện cán bộ (xem chuyên đề Bàn đá bên suối Lê-nin). Đặt tên suối Lê-nin, núi Các Mác vì thế là một cách nói rằng vùng đầu nguồn nhỏ bé này là nơi khởi đầu của một sự nghiệp có lý tưởng dẫn đường.","doc":2},{"loai":"doan","tieu_de":"Paris, tháng 7/1920: gặp Lê-nin trên trang báo","text":"Với Nguyễn Ái Quốc, cái tên Lê-nin gắn với một ngày ở Paris hơn hai mươi năm trước. Tháng 7/1920, báo Nhân đạo, tức L'Humanité, khi ấy là cơ quan của Đảng Xã hội Pháp, đăng bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lê-nin. Người thanh niên ba mươi tuổi, khi ấy làm thợ sửa ảnh và viết báo để sống, đã tìm đọc văn bản ấy. Trong luận cương có nhiều chữ chính trị khó hiểu, nhưng Người cứ đọc đi đọc lại, cho đến khi hiểu được phần chính.\n\nLần đầu tiên, Người tìm thấy một lý luận nói rõ con đường giải phóng cho các dân tộc thuộc địa, gắn cuộc đấu tranh của họ với phong trào cách mạng thế giới. Bốn mươi năm sau, tháng 4/1960, nhân kỷ niệm 90 năm ngày sinh Lê-nin, Người viết bài “Con đường dẫn tôi đến chủ nghĩa Lênin” cho một tạp chí của Liên Xô. Trong đó, Người kể lại khoảnh khắc đọc bản luận cương bằng những dòng đầy cảm xúc, hiếm thấy trong lối viết vốn giản dị, kiệm lời của Người. Đoạn văn ấy về sau được trích dẫn rất nhiều khi nói về bước ngoặt tư tưởng của Người.","doc":3},{"loai":"trich","text":"Luận cương của Lênin làm cho tôi rất cảm động, phấn khởi, sáng tỏ, tin tưởng biết bao! Tôi vui mừng đến phát khóc lên. Ngồi một mình trong buồng mà tôi nói to lên như đang nói trước quần chúng đông đảo: “Hỡi đồng bào bị đọa đày đau khổ! Đây là cái cần thiết cho chúng ta, đây là con đường giải phóng chúng ta!”","nguoi":"Hồ Chí Minh","nguon_ten":"“Con đường dẫn tôi đến chủ nghĩa Lênin” (4/1960) – Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia","doc":4},{"loai":"anh","src":"textures/bang_w/G12_5_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Suối Lê-nin dưới chân núi Các Mác”, nhìn từ xa."},{"loai":"doan","tieu_de":"Từ lòng yêu nước đến Quốc tế thứ ba","text":"Người cũng nói rất thật về động lực ban đầu của mình. Trong cùng bài viết năm 1960, Người kể: “Lúc đầu, chính là chủ nghĩa yêu nước, chứ chưa phải chủ nghĩa cộng sản đã đưa tôi tin theo Lênin, tin theo Quốc tế thứ ba”. Câu nói ấy giúp hiểu vì sao hai cái tên ở Pác Bó gắn liền với cuộc trở về của Người. Lý tưởng mà Mác, Lê-nin đại diện đã đến với Người qua con đường của lòng yêu nước, của khát vọng giải phóng dân tộc mình.\n\nTừ năm 1920, con đường của Người gắn chặt với phong trào cộng sản quốc tế. Người cùng những người bạn từ các thuộc địa lập Hội Liên hiệp thuộc địa năm 1921, ra báo Người cùng khổ năm 1922, viết cuốn Bản án chế độ thực dân Pháp xuất bản năm 1925. Người sang Liên Xô học tập, làm việc, rồi về Quảng Châu huấn luyện những thanh niên Việt Nam đầu tiên theo con đường cách mạng vô sản. Hơn hai mươi năm sau trang báo ở Paris, dưới chân núi đá Cao Bằng, những cái tên Người đặt cho núi sông là sự tiếp nối tự nhiên của hành trình ấy.","doc":5},{"loai":"ban_co_biet","text":"Tại Đại hội Đảng Xã hội Pháp họp ở thành phố Tua cuối tháng 12/1920, Nguyễn Ái Quốc là đại biểu duy nhất của Đông Dương. Người bỏ phiếu tán thành gia nhập Quốc tế thứ ba, trở thành một trong những người tham gia sáng lập Đảng Cộng sản Pháp.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia; Bảo tàng Hồ Chí Minh","doc":6},{"loai":"doan","tieu_de":"Mác và Lê-nin trong những trang sách của Người","text":"Các Mác, sống từ năm 1818 đến năm 1883, là nhà tư tưởng người Đức, cùng Ăng-ghen viết Tuyên ngôn của Đảng Cộng sản năm 1848, và là tác giả bộ Tư bản. Lê-nin, sống từ năm 1870 đến năm 1924, là người lãnh đạo Cách mạng Tháng Mười Nga năm 1917 và sáng lập Quốc tế Cộng sản năm 1919. Với Nguyễn Ái Quốc, Mác là người đặt nền móng cho học thuyết, còn Lê-nin là người đã chỉ ra con đường cụ thể cho các dân tộc bị áp bức.\n\nNăm 1927, các bài giảng của Người cho lớp thanh niên Việt Nam ở Quảng Châu được in thành cuốn Đường Kách mệnh. Trong đó, Người viết: “Bây giờ học thuyết nhiều, chủ nghĩa nhiều, nhưng chủ nghĩa chân chính nhất, chắc chắn nhất, cách mệnh nhất là chủ nghĩa Lênin”. Mười bốn năm sau, ở Pác Bó, Người lại mở lớp huấn luyện cho thanh niên các dân tộc Cao Bằng, lại soạn tài liệu, lại dịch sách lý luận. Dòng suối mang tên Lê-nin chảy qua vùng đất nơi những lớp học ấy diễn ra, như một sợi dây nối lớp học Quảng Châu năm 1927 với núi rừng Pác Bó năm 1941.","doc":7},{"loai":"ban_co_biet","text":"Nguyễn Ái Quốc sang Liên Xô vào mùa hè năm 1923 nhưng không kịp gặp Lê-nin, khi ấy đang ốm nặng. Lê-nin qua đời ngày 21/1/1924; Người đã viết bài tưởng niệm đăng trên báo Sự thật của Liên Xô.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, tập 1; Hồ Chí Minh Toàn tập, tập 1, NXB Chính trị quốc gia","doc":8},{"loai":"anh","src":"textures/bang_w/G12_5_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Suối Lê-nin dưới chân núi Các Mác”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"“Đây suối Lê-nin, kia núi Mác”","text":"Hai cái tên ấy còn đi vào thơ. Cũng năm 1941, ngoài bài “Tức cảnh Pác Bó” quen thuộc, Người làm bài thơ bốn câu “Pác Bó hùng vĩ”. Bài thơ mở ra bằng một không gian mênh mang, non xa, nước xa, rồi khẳng định một điều giản dị: một đất nước không cần phải rộng lớn thênh thang mới đáng gọi là giang sơn. Ngay giữa thung lũng hẹp này có suối Lê-nin, có núi Mác, và có đôi bàn tay con người đang dựng xây cơ đồ.\n\nChữ “sơn hà” trong câu cuối gợi nhớ những áng văn yêu nước từ thời Lý, Trần, khi cha ông khẳng định chủ quyền của núi sông nước Việt. Người đặt cạnh nhau hai lớp hình ảnh: tên của hai nhà tư tưởng cách mạng thế giới và khái niệm núi sông, đất nước rất phương Đông. Bài thơ vì thế nói gọn một quan niệm của Người: con đường cách mạng tiếp thu từ bên ngoài phải bén rễ vào chính núi sông, con người Việt Nam. Và việc dựng nước ấy bắt đầu từ “hai tay”, tức từ lao động và hành động cụ thể của mỗi người.","doc":9},{"loai":"trich","text":"Non xa xa, nước xa xa, / Nào phải thênh thang mới gọi là; / Đây suối Lê-nin, kia núi Mác, / Hai tay xây dựng một sơn hà.","nguoi":"Hồ Chí Minh","nguon_ten":"Bài thơ “Pác Bó hùng vĩ”, 1941","doc":10},{"loai":"doan","tieu_de":"Những cái tên ở lại","text":"Tháng 5/1941, cách hang Cốc Bó không xa, Hội nghị Trung ương lần thứ tám họp tại lán Khuổi Nặm, quyết định thành lập Mặt trận Việt Minh (xem chuyên đề Lán Khuổi Nặm). Tháng 8/1942, Người rời căn cứ sang Trung Quốc, tháng 9/1944 trở lại Pác Bó, rồi tháng 5/1945 về Tân Trào. Người đi rồi, nhưng những cái tên Người đặt năm 1941 thì ở lại. Đồng bào trong vùng, cán bộ, rồi các thế hệ sau đều gọi con suối là suối Lê-nin, ngọn núi là núi Các Mác.\n\nNgày 20/2/1961, Chủ tịch Hồ Chí Minh về thăm Pác Bó, nói chuyện với nhân dân và thăm khu ruộng Nà Chang. Hai mươi năm sau ngày đặt tên, Người trở lại vùng đầu nguồn với tư cách Chủ tịch nước. Năm 2012, Di tích lịch sử Pác Bó được xếp hạng di tích quốc gia đặc biệt; suối Lê-nin và núi Các Mác là những thành tố quan trọng của quần thể di tích ấy. Từ một lời đặt tên giữa núi rừng, hai địa danh đã trở thành một phần của bản đồ lịch sử Việt Nam, được nhắc đến trong sách giáo khoa và trong những chuyến về nguồn của biết bao đoàn khách.","doc":11},{"loai":"anh","src":"textures/bang_w/G12_5_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Suối Lê-nin dưới chân núi Các Mác”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, suối Lê-nin vẫn chảy qua trước cửa hang Cốc Bó, nước xanh trong, soi bóng núi Các Mác. Bên bờ suối, phiến đá mà Người dùng làm bàn làm việc vẫn được giữ gìn, gắn với câu thơ “Bàn đá chông chênh dịch sử Đảng”. Du khách đến Khu di tích Pác Bó có thể men theo bờ suối, dừng chân bên bàn đá, rồi ngước nhìn ngọn núi phía sau hang để hình dung không gian sống và làm việc của Người mùa xuân năm 1941.\n\nTấm ảnh năm 2016 trong gian trưng bày ghi lại khung cảnh ấy vào một buổi chiều mùa đông. Không gian 3D của gian dựng lại thung lũng Pác Bó để người xem hình dung vị trí của dòng suối, ngọn núi so với hang Cốc Bó và bàn đá. Điều đáng nhớ nhất là ý nghĩa của hai địa danh: năm 1941, giữa lúc cách mạng còn trong vòng bí mật, lực lượng còn mỏng, người vừa trở về đã gửi niềm tin của mình vào tên núi, tên sông. Và từ chính thung lũng hẹp ấy, đúng như câu thơ của Người, đôi bàn tay của cả một dân tộc đã bắt đầu dựng xây sơn hà.","doc":12}],"nguon":["Hồ Chí Minh, “Con đường dẫn tôi đến chủ nghĩa Lênin” (1960) và “Đường Kách mệnh” (1927) – Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia, 2011","Hồ Chí Minh – Biên niên tiểu sử, tập 1 và tập 2, NXB Chính trị quốc gia","Báo Nhân Dân, “85 năm Ngày Bác Hồ trở về Tổ quốc, mở ra thời kỳ mới của cách mạng Việt Nam” – https://nhandan.vn/85-nam-ngay-bac-ho-tro-ve-to-quoc-mo-ra-thoi-ky-moi-cua-cach-mang-viet-nam-post939544.html","Cục Di sản văn hóa, “Di tích lịch sử Pác Bó” – https://dsvh.gov.vn/di-tich-lich-su-pac-bo-2950","Khu di tích lịch sử Pác Bó (Cao Bằng); Bảo tàng Hồ Chí Minh","Ảnh: Tycho, Wikimedia Commons, 2016, CC BY-SA 3.0"],"doc":[{"t":"Suối Lê-nin, núi Các Mác: hai cái tên Nguyễn Ái Quốc gửi vào núi sông đầu nguồn. Một dòng suối xanh trong chảy dưới chân ngọn núi đá vôi, cảnh vật như bao thung lũng khác ở miền biên viễn Cao Bằng. Điều khác biệt nằm ở tên gọi. Mùa xuân năm 1941, người vừa trở về sau ba mươi năm đã đặt cho dòng suối và ngọn núi tên của hai con người mà Người coi là những bậc soi đường. Câu chuyện của hai cái tên ấy bắt đầu từ một trang báo ở Paris hơn hai mươi năm trước."},{"t":"Buổi chiều bên dòng suối đầu nguồn. Tấm ảnh được chụp lúc gần bốn giờ chiều ngày 8/1/2016, cùng ngày với tấm ảnh cửa hang Cốc Bó. Khung hình ghi lại dòng suối nước xanh trong dưới chân một ngọn núi đá vôi sừng sững. Trong tiếng Tày, Pác Bó nghĩa là đầu nguồn, nơi dòng nước bắt đầu chảy ra từ lòng núi. Con suối ở đây chảy trên lòng cuội, hai bờ là cỏ lau và những tảng đá phủ rêu. Hang Cốc Bó nằm ngay gần đầu nguồn ấy. Với người ở trong hang, con suối vừa là nguồn nước sinh hoạt, vừa là nơi làm việc mỗi ngày, như câu thơ “Sáng ra bờ suối, tối vào hang”. Mùa xuân năm 1941, Nguyễn Ái Quốc đặt cho dòng suối cái tên suối Lê-nin, và cho ngọn núi phía sau hang cái tên núi Các Mác. Hơn tám mươi năm đã qua, hai cái tên ấy vẫn là tên gọi của các điểm trong khu di tích, xuất hiện trong lời thuyết minh, trong sách báo và trong trí nhớ của nhiều thế hệ người Việt. Cảnh vật trong ảnh vì thế mang hai lớp nghĩa: một thắng cảnh thiên nhiên của miền biên viễn, và một lời khẳng định về lý tưởng của người đã đặt tên cho nó."},{"t":"Hai cái tên đặt giữa núi rừng. Người đặt những cái tên ấy trong các tuần ở hang Cốc Bó, khoảng tháng 2 và tháng 3/1941. Dòng suối chảy ngay trước cửa hang, ngọn núi sừng sững phía sau. Hằng ngày, đi ra đi vào, Người và những cán bộ quanh mình đều ở giữa hai cái tên ấy. Người không dựng bia, không treo khẩu hiệu. Người chỉ gọi tên núi, tên suối, và để những cái tên đi vào lời ăn tiếng nói thường ngày. Thời điểm đặt tên cũng rất đáng chú ý. Đó là lúc tổ chức Đảng trong nước vừa trải qua những tổn thất nặng nề sau các cuộc khởi nghĩa cuối năm 1940, nhiều cán bộ chủ chốt bị bắt. Phong trào cần được củng cố lại cả về tổ chức lẫn tư tưởng. Người trở về với tư cách đại diện Quốc tế Cộng sản, mang theo kinh nghiệm hơn hai mươi năm hoạt động trong phong trào cộng sản quốc tế. Cũng trong những tuần ấy, Người dịch cuốn Lịch sử Đảng Cộng sản (b) Liên Xô làm tài liệu huấn luyện cán bộ (xem chuyên đề Bàn đá bên suối Lê-nin). Đặt tên suối Lê-nin, núi Các Mác vì thế là một cách nói rằng vùng đầu nguồn nhỏ bé này là nơi khởi đầu của một sự nghiệp có lý tưởng dẫn đường."},{"t":"Paris, tháng 7/1920: gặp Lê-nin trên trang báo. Với Nguyễn Ái Quốc, cái tên Lê-nin gắn với một ngày ở Paris hơn hai mươi năm trước. Tháng 7/1920, báo Nhân đạo, tức L'Humanité, khi ấy là cơ quan của Đảng Xã hội Pháp, đăng bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lê-nin. Người thanh niên ba mươi tuổi, khi ấy làm thợ sửa ảnh và viết báo để sống, đã tìm đọc văn bản ấy. Trong luận cương có nhiều chữ chính trị khó hiểu, nhưng Người cứ đọc đi đọc lại, cho đến khi hiểu được phần chính. Lần đầu tiên, Người tìm thấy một lý luận nói rõ con đường giải phóng cho các dân tộc thuộc địa, gắn cuộc đấu tranh của họ với phong trào cách mạng thế giới. Bốn mươi năm sau, tháng 4/1960, nhân kỷ niệm 90 năm ngày sinh Lê-nin, Người viết bài “Con đường dẫn tôi đến chủ nghĩa Lênin” cho một tạp chí của Liên Xô. Trong đó, Người kể lại khoảnh khắc đọc bản luận cương bằng những dòng đầy cảm xúc, hiếm thấy trong lối viết vốn giản dị, kiệm lời của Người. Đoạn văn ấy về sau được trích dẫn rất nhiều khi nói về bước ngoặt tư tưởng của Người."},{"t":"Luận cương của Lênin làm cho tôi rất cảm động, phấn khởi, sáng tỏ, tin tưởng biết bao! Tôi vui mừng đến phát khóc lên. Ngồi một mình trong buồng mà tôi nói to lên như đang nói trước quần chúng đông đảo: “Hỡi đồng bào bị đọa đày đau khổ! Đây là cái cần thiết cho chúng ta, đây là con đường giải phóng chúng ta!” — Hồ Chí Minh"},{"t":"Từ lòng yêu nước đến Quốc tế thứ ba. Người cũng nói rất thật về động lực ban đầu của mình. Trong cùng bài viết năm 1960, Người kể: “Lúc đầu, chính là chủ nghĩa yêu nước, chứ chưa phải chủ nghĩa cộng sản đã đưa tôi tin theo Lênin, tin theo Quốc tế thứ ba”. Câu nói ấy giúp hiểu vì sao hai cái tên ở Pác Bó gắn liền với cuộc trở về của Người. Lý tưởng mà Mác, Lê-nin đại diện đã đến với Người qua con đường của lòng yêu nước, của khát vọng giải phóng dân tộc mình. Từ năm 1920, con đường của Người gắn chặt với phong trào cộng sản quốc tế. Người cùng những người bạn từ các thuộc địa lập Hội Liên hiệp thuộc địa năm 1921, ra báo Người cùng khổ năm 1922, viết cuốn Bản án chế độ thực dân Pháp xuất bản năm 1925. Người sang Liên Xô học tập, làm việc, rồi về Quảng Châu huấn luyện những thanh niên Việt Nam đầu tiên theo con đường cách mạng vô sản. Hơn hai mươi năm sau trang báo ở Paris, dưới chân núi đá Cao Bằng, những cái tên Người đặt cho núi sông là sự tiếp nối tự nhiên của hành trình ấy."},{"t":"Bạn có biết? Tại Đại hội Đảng Xã hội Pháp họp ở thành phố Tua cuối tháng 12/1920, Nguyễn Ái Quốc là đại biểu duy nhất của Đông Dương. Người bỏ phiếu tán thành gia nhập Quốc tế thứ ba, trở thành một trong những người tham gia sáng lập Đảng Cộng sản Pháp."},{"t":"Mác và Lê-nin trong những trang sách của Người. Các Mác, sống từ năm 1818 đến năm 1883, là nhà tư tưởng người Đức, cùng Ăng-ghen viết Tuyên ngôn của Đảng Cộng sản năm 1848, và là tác giả bộ Tư bản. Lê-nin, sống từ năm 1870 đến năm 1924, là người lãnh đạo Cách mạng Tháng Mười Nga năm 1917 và sáng lập Quốc tế Cộng sản năm 1919. Với Nguyễn Ái Quốc, Mác là người đặt nền móng cho học thuyết, còn Lê-nin là người đã chỉ ra con đường cụ thể cho các dân tộc bị áp bức. Năm 1927, các bài giảng của Người cho lớp thanh niên Việt Nam ở Quảng Châu được in thành cuốn Đường Kách mệnh. Trong đó, Người viết: “Bây giờ học thuyết nhiều, chủ nghĩa nhiều, nhưng chủ nghĩa chân chính nhất, chắc chắn nhất, cách mệnh nhất là chủ nghĩa Lênin”. Mười bốn năm sau, ở Pác Bó, Người lại mở lớp huấn luyện cho thanh niên các dân tộc Cao Bằng, lại soạn tài liệu, lại dịch sách lý luận. Dòng suối mang tên Lê-nin chảy qua vùng đất nơi những lớp học ấy diễn ra, như một sợi dây nối lớp học Quảng Châu năm 1927 với núi rừng Pác Bó năm 1941."},{"t":"Bạn có biết? Nguyễn Ái Quốc sang Liên Xô vào mùa hè năm 1923 nhưng không kịp gặp Lê-nin, khi ấy đang ốm nặng. Lê-nin qua đời ngày 21/1/1924; Người đã viết bài tưởng niệm đăng trên báo Sự thật của Liên Xô."},{"t":"“Đây suối Lê-nin, kia núi Mác”. Hai cái tên ấy còn đi vào thơ. Cũng năm 1941, ngoài bài “Tức cảnh Pác Bó” quen thuộc, Người làm bài thơ bốn câu “Pác Bó hùng vĩ”. Bài thơ mở ra bằng một không gian mênh mang, non xa, nước xa, rồi khẳng định một điều giản dị: một đất nước không cần phải rộng lớn thênh thang mới đáng gọi là giang sơn. Ngay giữa thung lũng hẹp này có suối Lê-nin, có núi Mác, và có đôi bàn tay con người đang dựng xây cơ đồ. Chữ “sơn hà” trong câu cuối gợi nhớ những áng văn yêu nước từ thời Lý, Trần, khi cha ông khẳng định chủ quyền của núi sông nước Việt. Người đặt cạnh nhau hai lớp hình ảnh: tên của hai nhà tư tưởng cách mạng thế giới và khái niệm núi sông, đất nước rất phương Đông. Bài thơ vì thế nói gọn một quan niệm của Người: con đường cách mạng tiếp thu từ bên ngoài phải bén rễ vào chính núi sông, con người Việt Nam. Và việc dựng nước ấy bắt đầu từ “hai tay”, tức từ lao động và hành động cụ thể của mỗi người."},{"t":"Non xa xa, nước xa xa, / Nào phải thênh thang mới gọi là; / Đây suối Lê-nin, kia núi Mác, / Hai tay xây dựng một sơn hà. — Hồ Chí Minh"},{"t":"Những cái tên ở lại. Tháng 5/1941, cách hang Cốc Bó không xa, Hội nghị Trung ương lần thứ tám họp tại lán Khuổi Nặm, quyết định thành lập Mặt trận Việt Minh (xem chuyên đề Lán Khuổi Nặm). Tháng 8/1942, Người rời căn cứ sang Trung Quốc, tháng 9/1944 trở lại Pác Bó, rồi tháng 5/1945 về Tân Trào. Người đi rồi, nhưng những cái tên Người đặt năm 1941 thì ở lại. Đồng bào trong vùng, cán bộ, rồi các thế hệ sau đều gọi con suối là suối Lê-nin, ngọn núi là núi Các Mác. Ngày 20/2/1961, Chủ tịch Hồ Chí Minh về thăm Pác Bó, nói chuyện với nhân dân và thăm khu ruộng Nà Chang. Hai mươi năm sau ngày đặt tên, Người trở lại vùng đầu nguồn với tư cách Chủ tịch nước. Năm 2012, Di tích lịch sử Pác Bó được xếp hạng di tích quốc gia đặc biệt; suối Lê-nin và núi Các Mác là những thành tố quan trọng của quần thể di tích ấy. Từ một lời đặt tên giữa núi rừng, hai địa danh đã trở thành một phần của bản đồ lịch sử Việt Nam, được nhắc đến trong sách giáo khoa và trong những chuyến về nguồn của biết bao đoàn khách."},{"t":"Dấu tích hôm nay. Ngày nay, suối Lê-nin vẫn chảy qua trước cửa hang Cốc Bó, nước xanh trong, soi bóng núi Các Mác. Bên bờ suối, phiến đá mà Người dùng làm bàn làm việc vẫn được giữ gìn, gắn với câu thơ “Bàn đá chông chênh dịch sử Đảng”. Du khách đến Khu di tích Pác Bó có thể men theo bờ suối, dừng chân bên bàn đá, rồi ngước nhìn ngọn núi phía sau hang để hình dung không gian sống và làm việc của Người mùa xuân năm 1941. Tấm ảnh năm 2016 trong gian trưng bày ghi lại khung cảnh ấy vào một buổi chiều mùa đông. Không gian 3D của gian dựng lại thung lũng Pác Bó để người xem hình dung vị trí của dòng suối, ngọn núi so với hang Cốc Bó và bàn đá. Điều đáng nhớ nhất là ý nghĩa của hai địa danh: năm 1941, giữa lúc cách mạng còn trong vòng bí mật, lực lượng còn mỏng, người vừa trở về đã gửi niềm tin của mình vào tên núi, tên sông. Và từ chính thung lũng hẹp ấy, đúng như câu thơ của Người, đôi bàn tay của cả một dân tộc đã bắt đầu dựng xây sơn hà."}],"so_chu":1966},{"i":6,"tieu_de_bang":"Lời Bác: “Cuộc đời cách mạng thật là sang”","tieu_de":"Bốn câu thơ bên suối Lê-nin: vì sao cuộc đời cách mạng lại “thật là sang”?","sapo":"Hang đá ẩm lạnh, bữa ăn chỉ có cháo ngô và rau măng, bàn làm việc là một phiến đá chênh vênh bên suối. Vậy mà người chiến sĩ năm mươi tuổi, vừa trở về sau ba mươi năm xa Tổ quốc, lại kết luận: cuộc đời cách mạng “thật là sang”. Bốn câu thơ viết năm 1941 ở Pác Bó giấu trong mình cả một quan niệm sống.","bia":{"src":"textures/ht/ht_anh_pac_bo.jpg","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Hai mươi tám chữ viết trong mùa xuân gian khó","text":"Trên bảng này chỉ có bốn câu thơ, tất cả hai mươi tám chữ. Đó là bài “Tức cảnh Pác Bó”, một trong những bài thơ quen thuộc nhất của Chủ tịch Hồ Chí Minh, được nhiều thế hệ học sinh thuộc lòng. Nhưng đằng sau vẻ nhẹ nhàng, vui tươi của bốn câu thơ là một hoàn cảnh hết sức ngặt nghèo.\n\nNgười viết bài thơ năm ấy đã năm mươi tuổi, vừa trở về Tổ quốc sau ba mươi năm bôn ba. Người đang sống trong một hang đá ẩm lạnh sát biên giới, giữa lúc kẻ thù ráo riết truy lùng những người cộng sản. Bữa ăn thiếu thốn, chỗ làm việc là một phiến đá bên suối. Vậy mà câu kết của bài thơ lại là một lời khẳng định đầy tự hào: cuộc đời cách mạng “thật là sang”. Bài thơ nhỏ ấy vừa là một trang nhật ký, vừa là bức chân dung tinh thần của Người.","doc":1},{"loai":"trich","text":"Sáng ra bờ suối, tối vào hang / Cháo bẹ rau măng vẫn sẵn sàng / Bàn đá chông chênh dịch sử Đảng / Cuộc đời cách mạng thật là sang.","nguoi":"Hồ Chí Minh","nguon_ten":"Tức cảnh Pác Bó, 1941 – Hồ Chí Minh Toàn tập, tập 3, NXB Chính trị quốc gia, 2011","doc":2},{"loai":"doan","tieu_de":"Hoàn cảnh ra đời","text":"Bài thơ ra đời năm 1941, trong quãng thời gian Người ở hang Cốc Bó, từ ngày 8/2 đến khoảng giữa tháng 3. Đó là những tuần đầu tiên Người sống trên đất nước sau gần ba mươi năm xa cách. Tháng Hai, tháng Ba ở vùng núi đá Cao Bằng trời còn rét, nền hang lúc nào cũng ẩm. Lương thực chủ yếu dựa vào sự tiếp tế của đồng bào trong bản.\n\nCông việc thì dồn dập. Người vừa dịch sách lý luận, vừa soạn tài liệu, mở lớp huấn luyện cho cán bộ, vừa chuẩn bị cho Hội nghị Trung ương sẽ họp vào tháng Năm. Giữa những bộn bề ấy, Người ghi lại cảnh sống trước mắt bằng bốn câu thơ tiếng Việt, với giọng điệu thoải mái, hóm hỉnh. Chính vì được viết trong hoàn cảnh ấy, bài thơ trở thành một tư liệu quý. Nó cho biết Người sống thế nào, làm việc gì, và nhìn nhận những thiếu thốn của mình ra sao trong những ngày đầu tiên trở về Tổ quốc.","doc":3},{"loai":"anh","src":"textures/bang_w/G12_6_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lời Bác: “Cuộc đời cách mạng thật là sang””, nhìn từ xa."},{"loai":"doan","tieu_de":"“Sáng ra bờ suối, tối vào hang”","text":"Câu thơ đầu như một thời gian biểu. Nhịp thơ chia đôi rõ ràng: “Sáng ra bờ suối” và “tối vào hang”. Hai cặp đối lập sáng và tối, ra và vào tạo nên một vòng khép kín, đều đặn, ngày nào cũng như ngày nào. Bờ suối ở đây chính là bờ suối Lê-nin chảy trước cửa hang Cốc Bó (xem chuyên đề Suối Lê-nin dưới chân núi Các Mác).\n\nNhịp sống ấy có lý do rất thực tế. Ban ngày, ngoài bờ suối có ánh sáng để đọc, viết, dịch sách, trong khi lòng hang tối và chật. Ban đêm, trở vào hang là để nghỉ ngơi, sưởi lửa và giữ an toàn. Nhưng câu thơ không than thở về sự bất tiện ấy. Nó được kể bằng giọng bình thản của một người đã quen với nếp sống mới, thậm chí thấy thú vị với nó. Chỉ bảy chữ, câu thơ vẽ được cả không gian sống lẫn nhịp sinh hoạt của người chiến sĩ giữa núi rừng.","doc":4},{"loai":"doan","tieu_de":"“Cháo bẹ rau măng vẫn sẵn sàng”","text":"Câu thứ hai nói về bữa ăn. “Cháo bẹ” là cháo ngô, “bẹ” là tên gọi cây ngô ở vùng này. Trên những sườn núi đá vôi Cao Bằng, đồng bào trồng ngô trong các hốc đá, và ngô là lương thực chính của nhiều gia đình. Rau măng thì hái trong rừng. Đó là những món ăn đạm bạc nhất của người dân vùng cao lúc bấy giờ.\n\nHai chữ “vẫn sẵn sàng” có thể hiểu theo hai lớp nghĩa. Lớp thứ nhất: cháo bẹ, rau măng lúc nào cũng có sẵn, không lo thiếu. Lớp thứ hai sâu hơn: người ăn bữa ăn ấy vẫn luôn thanh thản và sẵn sàng cho công việc. Người đọc có thể nhớ tới câu thơ của Trạng Trình Nguyễn Bỉnh Khiêm: “Thu ăn măng trúc, đông ăn giá”. Cùng là măng rừng, nhưng bậc ẩn sĩ thế kỷ XVI tìm sự thanh nhàn ngoài vòng danh lợi. Còn người chiến sĩ năm 1941 ăn măng rừng để giữ sức cho một cuộc chiến đấu lớn.","doc":5},{"loai":"ban_co_biet","text":"Trong tiếng địa phương, “bẹ” là cây ngô; “cháo bẹ” tức là cháo ngô, món ăn thường ngày của đồng bào vùng núi đá Cao Bằng thời ấy và cũng là bữa ăn quen thuộc của Người ở Pác Bó.","nguon_ten":"Sách giáo khoa Ngữ văn 8, NXB Giáo dục Việt Nam – chú thích bài “Tức cảnh Pác Bó”","doc":6},{"loai":"doan","tieu_de":"“Bàn đá chông chênh dịch sử Đảng”","text":"Câu thứ ba chuyển sang công việc. Bàn làm việc là một phiến đá bên suối, mặt đá gồ ghề, đặt giấy bút lên thì chông chênh, không vững. Còn công việc thì rất lớn: dịch cuốn Lịch sử Đảng Cộng sản (b) Liên Xô sang tiếng Việt, làm tài liệu huấn luyện cán bộ (xem chuyên đề Bàn đá bên suối Lê-nin). Cuốn sách này là một giáo trình tóm tắt ra đời ở Mát-xcơ-va năm 1938, tức chỉ khoảng ba năm trước đó.\n\nCâu thơ đặt cạnh nhau hai hình ảnh trái ngược. Một bên là cái bàn chênh vênh, tạm bợ. Một bên là việc dịch sử Đảng, đòi hỏi sự vững vàng về lý luận và sự chính xác đến từng câu chữ. Chính sự tương phản ấy làm nổi bật tư thế của Người: điều kiện vật chất có thể chông chênh, nhưng ý chí và lý tưởng thì vững như đá núi. Đây cũng là câu duy nhất trong bài nói tới một công việc cụ thể, và nó chuẩn bị cho câu kết bất ngờ.","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_pac_bo.jpg","chu_thich":"Suối Lê-nin dưới chân núi Các Mác, Pác Bó – “bờ suối” trong câu thơ mở đầu bài “Tức cảnh Pác Bó”. Ảnh: Tycho, 2016, giấy phép CC BY-SA 3.0.","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"“Cuộc đời cách mạng thật là sang”","text":"Ba câu đầu kể những điều kham khổ: hang đá, cháo ngô, bàn đá chênh vênh. Người đọc chờ đợi một lời than, hoặc ít nhất một lời tự an ủi. Nhưng câu kết lại bất ngờ: tất cả những điều ấy làm nên một cuộc đời “thật là sang”. Chữ “sang” thường dùng cho sự giàu có, quyền quý, nhà cao cửa rộng. Đặt chữ ấy ngay sau cháo bẹ, rau măng, Người tạo nên một nụ cười hóm hỉnh.\n\nNhưng đó không chỉ là một câu đùa. Cái sang ở đây là sự giàu có về tinh thần. Sau gần ba mươi năm bôn ba, được sống trên đất nước mình, giữa đồng bào mình, được trực tiếp làm việc cho sự nghiệp giải phóng dân tộc, với Người là niềm hạnh phúc lớn. Người từng sống ở Paris, Luân Đôn, Mát-xcơ-va, những thành phố hoa lệ bậc nhất thế giới. Vậy mà chính ở hang đá Pác Bó, Người gọi cuộc sống của mình là “sang”. Cái sang ấy đo bằng ý nghĩa của công việc, không đo bằng tiện nghi vật chất. Năm năm sau, khi đã là Chủ tịch nước, Người nói rõ điều mình mong muốn nhất trong đời.","doc":8},{"loai":"trich","text":"Tôi chỉ có một sự ham muốn, ham muốn tột bậc, là làm sao cho nước ta được hoàn toàn độc lập, dân ta được hoàn toàn tự do, đồng bào ai cũng có cơm ăn áo mặc, ai cũng được học hành.","nguoi":"Hồ Chí Minh","nguon_ten":"Trả lời các nhà báo nước ngoài, tháng 1/1946 – Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia","doc":9},{"loai":"doan","tieu_de":"Một bài tứ tuyệt rất Việt","text":"Về hình thức, “Tức cảnh Pác Bó” là một bài thất ngôn tứ tuyệt: bốn câu, mỗi câu bảy chữ, thể thơ cổ điển quen thuộc từ thơ Đường. Bài thơ gieo vần “ang” ở cuối câu một, câu hai và câu bốn: hang, sàng, sang. Câu ba kết thúc bằng chữ “Đảng” mang thanh trắc, đúng luật của thể thơ. Người được học chữ Hán từ nhỏ, thân phụ là cụ Phó bảng Nguyễn Sinh Sắc, nên am hiểu thi pháp cổ điển.\n\nNhưng bài thơ không khoác áo cổ kính. Lời thơ là tiếng Việt mộc mạc như lời nói hằng ngày: sáng ra, tối vào, cháo bẹ, rau măng. Không có điển cố, không có từ ngữ khó hiểu. Nhan đề “Tức cảnh”, nghĩa là nhân cảnh trước mắt mà làm thơ, gợi dáng dấp cổ điển, còn nội dung thì gần gũi như một câu chuyện kể. Sự kết hợp ấy làm nên nét riêng của thơ Hồ Chí Minh: vừa có cốt cách cổ điển, vừa hiện đại, ai đọc cũng hiểu, ai nghe cũng nhớ.","doc":10},{"loai":"ban_co_biet","text":"Hơn một năm sau bài thơ tiếng Việt viết ở Pác Bó, trong những nhà tù của chính quyền Tưởng Giới Thạch ở Quảng Tây (1942 – 1943), Người lại làm thơ bằng chữ Hán; những bài thơ ấy về sau được biết đến với tên tập “Nhật ký trong tù”.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","doc":11},{"loai":"anh","src":"textures/bang_w/G12_6_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lời Bác: “Cuộc đời cách mạng thật là sang””, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Cùng một nụ cười ở Việt Bắc","text":"“Tức cảnh Pác Bó” không đứng riêng. Cùng thời gian ấy, Người còn làm bài “Pác Bó hùng vĩ” với câu thơ “Đây suối Lê-nin, kia núi Mác” (xem chuyên đề Suối Lê-nin dưới chân núi Các Mác). Những năm 1941 – 1942, Người viết nhiều bài ca, bài diễn ca theo thể lục bát để tuyên truyền, vận động đồng bào (xem chuyên đề “Lịch sử nước ta” và dự báo năm 1945).\n\nSáu, bảy năm sau, trong kháng chiến chống thực dân Pháp, cũng ở chiến khu Việt Bắc, Người viết “Cảnh khuya” năm 1947 và “Rằm tháng giêng” năm 1948. Nhưng trong thơ vẫn là trăng, là tiếng suối, là con thuyền chở đầy ánh trăng trên dòng sông, và một tâm hồn bình thản trước thử thách. Đặt “Tức cảnh Pác Bó” cạnh những bài thơ ấy, ta thấy một mạch liền: giữa núi rừng và hiểm nguy, người chiến sĩ vẫn giữ được niềm vui, sự ung dung và niềm tin vào thắng lợi. Bài thơ bốn câu ở Pác Bó có thể xem là một trong những bài mở đầu mạch thơ ấy.","doc":12},{"loai":"anh","src":"textures/bang_w/G12_6_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lời Bác: “Cuộc đời cách mạng thật là sang””, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Tiếng vọng hôm nay","text":"Bài thơ từ lâu đã có trong sách giáo khoa Ngữ văn lớp 8, trở thành một trong những bài thơ Hồ Chí Minh được học sinh cả nước thuộc lòng. Câu kết “Cuộc đời cách mạng thật là sang” thường được nhắc lại khi nói về lối sống giản dị, lạc quan của những người cách mạng thế hệ đầu, những người coi gian khổ là chuyện bình thường của lý tưởng mình đã chọn.\n\nỞ Khu di tích lịch sử Pác Bó, những hình ảnh trong bài thơ vẫn còn hiện hữu: bờ suối Lê-nin, cửa hang Cốc Bó, phiến đá bên suối được gọi là “bàn đá chông chênh”. Đến đây, du khách có thể đọc lại bốn câu thơ ngay tại nơi chúng ra đời, và nhận ra rằng mỗi hình ảnh trong bài đều có một địa chỉ thật. Và người xem hôm nay có thể hình dung một con người năm mươi tuổi đã tìm thấy sự “sang” của đời mình trong những điều giản dị nhất.","doc":13}],"nguon":["Hồ Chí Minh, “Tức cảnh Pác Bó” (1941) – Hồ Chí Minh Toàn tập, tập 3, NXB Chính trị quốc gia, 2011","Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","Sách giáo khoa Ngữ văn 8, NXB Giáo dục Việt Nam","Cục Di sản văn hóa, “Di tích lịch sử Pác Bó” – https://dsvh.gov.vn/di-tich-lich-su-pac-bo-2950","Bảo tàng Hồ Chí Minh"],"doc":[{"t":"Bốn câu thơ bên suối Lê-nin: vì sao cuộc đời cách mạng lại “thật là sang”?. Hang đá ẩm lạnh, bữa ăn chỉ có cháo ngô và rau măng, bàn làm việc là một phiến đá chênh vênh bên suối. Vậy mà người chiến sĩ năm mươi tuổi, vừa trở về sau ba mươi năm xa Tổ quốc, lại kết luận: cuộc đời cách mạng “thật là sang”. Bốn câu thơ viết năm 1941 ở Pác Bó giấu trong mình cả một quan niệm sống."},{"t":"Hai mươi tám chữ viết trong mùa xuân gian khó. Trên bảng này chỉ có bốn câu thơ, tất cả hai mươi tám chữ. Đó là bài “Tức cảnh Pác Bó”, một trong những bài thơ quen thuộc nhất của Chủ tịch Hồ Chí Minh, được nhiều thế hệ học sinh thuộc lòng. Nhưng đằng sau vẻ nhẹ nhàng, vui tươi của bốn câu thơ là một hoàn cảnh hết sức ngặt nghèo. Người viết bài thơ năm ấy đã năm mươi tuổi, vừa trở về Tổ quốc sau ba mươi năm bôn ba. Người đang sống trong một hang đá ẩm lạnh sát biên giới, giữa lúc kẻ thù ráo riết truy lùng những người cộng sản. Bữa ăn thiếu thốn, chỗ làm việc là một phiến đá bên suối. Vậy mà câu kết của bài thơ lại là một lời khẳng định đầy tự hào: cuộc đời cách mạng “thật là sang”. Bài thơ nhỏ ấy vừa là một trang nhật ký, vừa là bức chân dung tinh thần của Người."},{"t":"Sáng ra bờ suối, tối vào hang / Cháo bẹ rau măng vẫn sẵn sàng / Bàn đá chông chênh dịch sử Đảng / Cuộc đời cách mạng thật là sang. — Hồ Chí Minh"},{"t":"Hoàn cảnh ra đời. Bài thơ ra đời năm 1941, trong quãng thời gian Người ở hang Cốc Bó, từ ngày 8/2 đến khoảng giữa tháng 3. Đó là những tuần đầu tiên Người sống trên đất nước sau gần ba mươi năm xa cách. Tháng Hai, tháng Ba ở vùng núi đá Cao Bằng trời còn rét, nền hang lúc nào cũng ẩm. Lương thực chủ yếu dựa vào sự tiếp tế của đồng bào trong bản. Công việc thì dồn dập. Người vừa dịch sách lý luận, vừa soạn tài liệu, mở lớp huấn luyện cho cán bộ, vừa chuẩn bị cho Hội nghị Trung ương sẽ họp vào tháng Năm. Giữa những bộn bề ấy, Người ghi lại cảnh sống trước mắt bằng bốn câu thơ tiếng Việt, với giọng điệu thoải mái, hóm hỉnh. Chính vì được viết trong hoàn cảnh ấy, bài thơ trở thành một tư liệu quý. Nó cho biết Người sống thế nào, làm việc gì, và nhìn nhận những thiếu thốn của mình ra sao trong những ngày đầu tiên trở về Tổ quốc."},{"t":"“Sáng ra bờ suối, tối vào hang”. Câu thơ đầu như một thời gian biểu. Nhịp thơ chia đôi rõ ràng: “Sáng ra bờ suối” và “tối vào hang”. Hai cặp đối lập sáng và tối, ra và vào tạo nên một vòng khép kín, đều đặn, ngày nào cũng như ngày nào. Bờ suối ở đây chính là bờ suối Lê-nin chảy trước cửa hang Cốc Bó (xem chuyên đề Suối Lê-nin dưới chân núi Các Mác). Nhịp sống ấy có lý do rất thực tế. Ban ngày, ngoài bờ suối có ánh sáng để đọc, viết, dịch sách, trong khi lòng hang tối và chật. Ban đêm, trở vào hang là để nghỉ ngơi, sưởi lửa và giữ an toàn. Nhưng câu thơ không than thở về sự bất tiện ấy. Nó được kể bằng giọng bình thản của một người đã quen với nếp sống mới, thậm chí thấy thú vị với nó. Chỉ bảy chữ, câu thơ vẽ được cả không gian sống lẫn nhịp sinh hoạt của người chiến sĩ giữa núi rừng."},{"t":"“Cháo bẹ rau măng vẫn sẵn sàng”. Câu thứ hai nói về bữa ăn. “Cháo bẹ” là cháo ngô, “bẹ” là tên gọi cây ngô ở vùng này. Trên những sườn núi đá vôi Cao Bằng, đồng bào trồng ngô trong các hốc đá, và ngô là lương thực chính của nhiều gia đình. Rau măng thì hái trong rừng. Đó là những món ăn đạm bạc nhất của người dân vùng cao lúc bấy giờ. Hai chữ “vẫn sẵn sàng” có thể hiểu theo hai lớp nghĩa. Lớp thứ nhất: cháo bẹ, rau măng lúc nào cũng có sẵn, không lo thiếu. Lớp thứ hai sâu hơn: người ăn bữa ăn ấy vẫn luôn thanh thản và sẵn sàng cho công việc. Người đọc có thể nhớ tới câu thơ của Trạng Trình Nguyễn Bỉnh Khiêm: “Thu ăn măng trúc, đông ăn giá”. Cùng là măng rừng, nhưng bậc ẩn sĩ thế kỷ XVI tìm sự thanh nhàn ngoài vòng danh lợi. Còn người chiến sĩ năm 1941 ăn măng rừng để giữ sức cho một cuộc chiến đấu lớn."},{"t":"Bạn có biết? Trong tiếng địa phương, “bẹ” là cây ngô; “cháo bẹ” tức là cháo ngô, món ăn thường ngày của đồng bào vùng núi đá Cao Bằng thời ấy và cũng là bữa ăn quen thuộc của Người ở Pác Bó."},{"t":"“Bàn đá chông chênh dịch sử Đảng”. Câu thứ ba chuyển sang công việc. Bàn làm việc là một phiến đá bên suối, mặt đá gồ ghề, đặt giấy bút lên thì chông chênh, không vững. Còn công việc thì rất lớn: dịch cuốn Lịch sử Đảng Cộng sản (b) Liên Xô sang tiếng Việt, làm tài liệu huấn luyện cán bộ (xem chuyên đề Bàn đá bên suối Lê-nin). Cuốn sách này là một giáo trình tóm tắt ra đời ở Mát-xcơ-va năm 1938, tức chỉ khoảng ba năm trước đó. Câu thơ đặt cạnh nhau hai hình ảnh trái ngược. Một bên là cái bàn chênh vênh, tạm bợ. Một bên là việc dịch sử Đảng, đòi hỏi sự vững vàng về lý luận và sự chính xác đến từng câu chữ. Chính sự tương phản ấy làm nổi bật tư thế của Người: điều kiện vật chất có thể chông chênh, nhưng ý chí và lý tưởng thì vững như đá núi. Đây cũng là câu duy nhất trong bài nói tới một công việc cụ thể, và nó chuẩn bị cho câu kết bất ngờ."},{"t":"“Cuộc đời cách mạng thật là sang”. Ba câu đầu kể những điều kham khổ: hang đá, cháo ngô, bàn đá chênh vênh. Người đọc chờ đợi một lời than, hoặc ít nhất một lời tự an ủi. Nhưng câu kết lại bất ngờ: tất cả những điều ấy làm nên một cuộc đời “thật là sang”. Chữ “sang” thường dùng cho sự giàu có, quyền quý, nhà cao cửa rộng. Đặt chữ ấy ngay sau cháo bẹ, rau măng, Người tạo nên một nụ cười hóm hỉnh. Nhưng đó không chỉ là một câu đùa. Cái sang ở đây là sự giàu có về tinh thần. Sau gần ba mươi năm bôn ba, được sống trên đất nước mình, giữa đồng bào mình, được trực tiếp làm việc cho sự nghiệp giải phóng dân tộc, với Người là niềm hạnh phúc lớn. Người từng sống ở Paris, Luân Đôn, Mát-xcơ-va, những thành phố hoa lệ bậc nhất thế giới. Vậy mà chính ở hang đá Pác Bó, Người gọi cuộc sống của mình là “sang”. Cái sang ấy đo bằng ý nghĩa của công việc, không đo bằng tiện nghi vật chất. Năm năm sau, khi đã là Chủ tịch nước, Người nói rõ điều mình mong muốn nhất trong đời."},{"t":"Tôi chỉ có một sự ham muốn, ham muốn tột bậc, là làm sao cho nước ta được hoàn toàn độc lập, dân ta được hoàn toàn tự do, đồng bào ai cũng có cơm ăn áo mặc, ai cũng được học hành. — Hồ Chí Minh"},{"t":"Một bài tứ tuyệt rất Việt. Về hình thức, “Tức cảnh Pác Bó” là một bài thất ngôn tứ tuyệt: bốn câu, mỗi câu bảy chữ, thể thơ cổ điển quen thuộc từ thơ Đường. Bài thơ gieo vần “ang” ở cuối câu một, câu hai và câu bốn: hang, sàng, sang. Câu ba kết thúc bằng chữ “Đảng” mang thanh trắc, đúng luật của thể thơ. Người được học chữ Hán từ nhỏ, thân phụ là cụ Phó bảng Nguyễn Sinh Sắc, nên am hiểu thi pháp cổ điển. Nhưng bài thơ không khoác áo cổ kính. Lời thơ là tiếng Việt mộc mạc như lời nói hằng ngày: sáng ra, tối vào, cháo bẹ, rau măng. Không có điển cố, không có từ ngữ khó hiểu. Nhan đề “Tức cảnh”, nghĩa là nhân cảnh trước mắt mà làm thơ, gợi dáng dấp cổ điển, còn nội dung thì gần gũi như một câu chuyện kể. Sự kết hợp ấy làm nên nét riêng của thơ Hồ Chí Minh: vừa có cốt cách cổ điển, vừa hiện đại, ai đọc cũng hiểu, ai nghe cũng nhớ."},{"t":"Bạn có biết? Hơn một năm sau bài thơ tiếng Việt viết ở Pác Bó, trong những nhà tù của chính quyền Tưởng Giới Thạch ở Quảng Tây (1942 – 1943), Người lại làm thơ bằng chữ Hán; những bài thơ ấy về sau được biết đến với tên tập “Nhật ký trong tù”."},{"t":"Cùng một nụ cười ở Việt Bắc. “Tức cảnh Pác Bó” không đứng riêng. Cùng thời gian ấy, Người còn làm bài “Pác Bó hùng vĩ” với câu thơ “Đây suối Lê-nin, kia núi Mác” (xem chuyên đề Suối Lê-nin dưới chân núi Các Mác). Những năm 1941 – 1942, Người viết nhiều bài ca, bài diễn ca theo thể lục bát để tuyên truyền, vận động đồng bào (xem chuyên đề “Lịch sử nước ta” và dự báo năm 1945). Sáu, bảy năm sau, trong kháng chiến chống thực dân Pháp, cũng ở chiến khu Việt Bắc, Người viết “Cảnh khuya” năm 1947 và “Rằm tháng giêng” năm 1948. Nhưng trong thơ vẫn là trăng, là tiếng suối, là con thuyền chở đầy ánh trăng trên dòng sông, và một tâm hồn bình thản trước thử thách. Đặt “Tức cảnh Pác Bó” cạnh những bài thơ ấy, ta thấy một mạch liền: giữa núi rừng và hiểm nguy, người chiến sĩ vẫn giữ được niềm vui, sự ung dung và niềm tin vào thắng lợi. Bài thơ bốn câu ở Pác Bó có thể xem là một trong những bài mở đầu mạch thơ ấy."},{"t":"Tiếng vọng hôm nay. Bài thơ từ lâu đã có trong sách giáo khoa Ngữ văn lớp 8, trở thành một trong những bài thơ Hồ Chí Minh được học sinh cả nước thuộc lòng. Câu kết “Cuộc đời cách mạng thật là sang” thường được nhắc lại khi nói về lối sống giản dị, lạc quan của những người cách mạng thế hệ đầu, những người coi gian khổ là chuyện bình thường của lý tưởng mình đã chọn. Ở Khu di tích lịch sử Pác Bó, những hình ảnh trong bài thơ vẫn còn hiện hữu: bờ suối Lê-nin, cửa hang Cốc Bó, phiến đá bên suối được gọi là “bàn đá chông chênh”. Đến đây, du khách có thể đọc lại bốn câu thơ ngay tại nơi chúng ra đời, và nhận ra rằng mỗi hình ảnh trong bài đều có một địa chỉ thật. Và người xem hôm nay có thể hình dung một con người năm mươi tuổi đã tìm thấy sự “sang” của đời mình trong những điều giản dị nhất."}],"so_chu":1851},{"i":7,"tieu_de_bang":"Trở về Tổ quốc (28/1/1941)","tieu_de":"Cột mốc 108, trưa mùng 2 Tết Tân Tỵ: ba mươi năm khép lại trong một bước chân","sapo":"Trưa 28/1/1941, khi bà con vùng biên còn đang vui Tết, một nhóm nhỏ lặng lẽ vượt qua cột mốc đá ở đầu thung lũng Pác Bó. Trong nhóm có một người đã rời Tổ quốc từ mùa hè năm 1911. Để đi tới bước chân ấy, Người đã vòng qua Diên An, Quế Lâm, Côn Minh và một lớp học nhỏ sát biên giới.","bia":{"src":"textures/bai/G12_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Trưa mùng 2 Tết Tân Tỵ","text":"Trưa ngày 28/1/1941, tức mùng 2 Tết Tân Tỵ, ở các bản vùng biên Hà Quảng, đồng bào Tày, Nùng còn đang vui những ngày đầu năm mới. Giữa không khí ấy, một nhóm nhỏ lặng lẽ đi theo lối mòn giữa những triền núi đá, vượt qua cột mốc biên giới số 108 để vào thung lũng Pác Bó. Trong nhóm có các đồng chí Lê Quảng Ba, Phùng Chí Kiên, Vũ Anh, và một người đàn ông năm mươi tuổi được anh em gọi là Già Thu.\n\nÍt ai trong bản biết rằng Già Thu chính là Nguyễn Ái Quốc, người đã rời Tổ quốc từ gần ba mươi năm trước. Các tài liệu kể rằng khoảnh khắc đặt chân qua cột mốc, Người vô cùng xúc động. Phía sau là ba mươi năm bôn ba khắp năm châu. Phía trước là một đất nước đang chịu cảnh một cổ hai tròng dưới ách Pháp – Nhật, và một phong trào cách mạng vừa trải qua những tổn thất nặng nề. Bước chân qua cột mốc đá ấy khép lại một hành trình tìm đường, và mở ra giai đoạn Người trực tiếp lãnh đạo cách mạng ngay trên đất nước mình.","doc":1},{"loai":"anh","src":"textures/bang_w/G12_7_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Trở về Tổ quốc (28/1/1941)”, nhìn từ xa."},{"loai":"doan","tieu_de":"Ba mươi năm, hai đầu đất nước","text":"Ngày 5/6/1911, người thanh niên Nguyễn Tất Thành, với tên Văn Ba, làm phụ bếp trên con tàu Amiral Latouche-Tréville, rời bến Nhà Rồng ở Sài Gòn. Gần ba mươi năm sau, Người trở về qua một lối mòn nơi địa đầu phía Bắc. Điểm đi và điểm về của hành trình nằm ở hai đầu đất nước, như thể Người đã đi trọn một vòng quanh thế giới để trở về với Tổ quốc.\n\nTrong ba mươi năm ấy, Người sống và hoạt động ở nhiều nước châu Âu, châu Phi, châu Mỹ, châu Á. Người làm đủ nghề để sống, từ phụ bếp, cào tuyết đến thợ sửa ảnh. Người mang nhiều tên gọi khác nhau: Nguyễn Ái Quốc ở Paris, Lý Thụy ở Quảng Châu, Tống Văn Sơ ở Hồng Kông, Hồ Quang ở Quế Lâm. Mỗi cái tên gắn với một chặng đường, một nhiệm vụ. Già Thu là tên gọi mới nhất, tên của người vừa trở về giữa núi rừng Cao Bằng. Chỉ hơn một năm sau, tháng 8/1942, Người sẽ dùng một cái tên khác, cái tên cả thế giới biết đến: Hồ Chí Minh.","doc":2},{"loai":"doan","tieu_de":"Con đường vòng qua Trung Quốc","text":"Con đường trở về bắt đầu từ mùa thu năm 1938, khi Người rời Liên Xô sang Trung Quốc. Người đến Diên An, rồi hoạt động ở Quế Lâm với tên Hồ Quang, tìm cách bắt liên lạc với tổ chức Đảng trong nước. Năm 1940, Người có mặt ở Côn Minh, nơi có cơ sở của Đảng ở nước ngoài. Tại đây, tháng 6/1940, Người gặp hai thanh niên từ trong nước sang là Phạm Văn Đồng và Võ Nguyên Giáp.\n\nCũng tháng ấy, nước Pháp thất thủ trước phát xít Đức. Theo hồi ký của Đại tướng Võ Nguyên Giáp, Người nhận định việc Pháp mất nước là cơ hội rất thuận lợi cho cách mạng Việt Nam, phải tìm mọi cách về nước để tranh thủ thời cơ. Tháng 9/1940, quân Nhật tấn công Lạng Sơn, bắt đầu kéo vào Đông Dương. Tháng 10/1940, Người trở lại Quế Lâm, rồi đến Tĩnh Tây, một huyện của tỉnh Quảng Tây giáp Cao Bằng. Từ đây, Người theo dõi sát tình hình trong nước và chuẩn bị cán bộ cho chuyến trở về.","doc":3},{"loai":"ban_co_biet","text":"Tài liệu giảng dạy của lớp huấn luyện chính trị mà Người mở sát biên giới đầu năm 1941 được in đá thành một cuốn sách nhỏ mang tên “Con đường giải phóng”.","nguon_ten":"Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch, “Lãnh tụ Nguyễn Ái Quốc và lớp huấn luyện chính trị trước khi về nước” – https://nhasanbacho.vn/bai-viet/lanh-tu-nguyen-ai-quoc-va-lop-huan-luyen-chinh-tri-truoc-khi-ve-nuoc-3039/","doc":4},{"loai":"doan","tieu_de":"Lớp học sát biên giới","text":"Khoảng đầu tháng 1/1941, Người chuyển đến làng Nậm Quang, sát biên giới Việt – Trung. Tại đây, Người mở một lớp huấn luyện chính trị cho khoảng 43 thanh niên Cao Bằng. Tham gia tổ chức lớp học có các đồng chí Phùng Chí Kiên, Vũ Anh, Phạm Văn Đồng và Võ Nguyên Giáp. Nội dung gồm ba phần: tình hình thế giới và trong nước, cách tổ chức quần chúng, và phương pháp cách mạng nhằm xây dựng một mặt trận dân tộc rộng rãi.\n\nĐại tướng Võ Nguyên Giáp về sau nhớ lại cách chuẩn bị bài giảng rất kỹ lưỡng. Mọi người họp bàn, thống nhất đề cương rồi mới viết. Viết xong lại họp, cùng đọc và sửa chữa. Cuối mỗi bài, học viên được hỏi những câu rất thực tế, chẳng hạn trở về địa phương sẽ làm gì, làm như thế nào. Cách dạy ấy cho thấy Người không muốn đào tạo những người thuộc lý thuyết, mà muốn có những cán bộ biết bắt tay vào việc ngay. Sau lớp học, các học viên trở về Cao Bằng để gây dựng và phát triển cơ sở cách mạng, chuẩn bị cho những bước đi tiếp theo.","doc":5},{"loai":"doan","tieu_de":"Vì sao là lúc ấy?","text":"Quyết định về nước năm 1941 không phải là một bước đi ngẫu hứng. Tháng 11/1939, Hội nghị Trung ương lần thứ sáu đã chuyển hướng chỉ đạo, đặt nhiệm vụ giải phóng dân tộc lên hàng đầu. Tháng 11/1940, Hội nghị Trung ương lần thứ bảy tiếp tục khẳng định hướng đi ấy. Nhưng cuối năm 1940, khởi nghĩa Bắc Sơn và khởi nghĩa Nam Kỳ bị đàn áp, nhiều cán bộ lãnh đạo bị bắt. Phong trào trong nước cần một sự chỉ đạo trực tiếp, thống nhất và có uy tín.\n\nNgười trở về với tư cách đại diện Quốc tế Cộng sản, là người đã chủ trì hội nghị hợp nhất thành lập Đảng đầu năm 1930, mang theo vốn hiểu biết sâu rộng về tình hình thế giới. Chọn Cao Bằng làm nơi đặt chân là chọn một vùng có phong trào cách mạng từ sớm, có địa hình hiểm trở và nằm sát biên giới (xem bảng giới thiệu gian Pác Bó – Cao Bằng). Chưa đầy bốn tháng sau, những tính toán ấy được thể hiện rõ trong các quyết định của Hội nghị Trung ương lần thứ tám.","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_coc_bo.jpg","chu_thich":"Hang Cốc Bó ở Pác Bó, nơi Nguyễn Ái Quốc chuyển vào ở từ ngày 8/2/1941, mười một ngày sau khi vượt cột mốc 108 về nước. Ảnh: Tycho, 2016, giấy phép CC BY-SA 3.0.","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Cột mốc 108, chứng nhân bằng đá","text":"Cột mốc nơi Người bước qua là một cột mốc cổ trên đường biên giới Việt – Trung. Những cột mốc loại này được dựng từ cuối thế kỷ XIX, sau khi Pháp và nhà Thanh ký các công ước hoạch định biên giới giữa Bắc Kỳ và Trung Quốc. Mỗi mốc được đánh số, và mốc số 108 nằm ở đầu thung lũng Pác Bó. Với nhà cầm quyền thời ấy, nó chỉ là một dấu mốc hành chính giữa hai vùng lãnh thổ.\n\nNhưng từ trưa 28/1/1941, cột mốc ấy mang một ý nghĩa khác. Nó đánh dấu nơi người con đi xa đặt chân về đất mẹ. Sau khi Việt Nam và Trung Quốc hoàn thành phân giới, cắm mốc trên toàn tuyến biên giới đất liền năm 2008, vị trí này mang số hiệu mới là mốc 675. Dù vậy, trong sách vở và trong ký ức của nhiều thế hệ, nó vẫn được gọi thân thuộc là cột mốc 108. Gần ba mươi năm sau ngày Người về nước, nhà thơ Tố Hữu đã viết về khoảnh khắc ấy trong bài “Theo chân Bác”, sáng tác năm 1970, bằng những câu thơ nhiều người thuộc lòng.","doc":7},{"loai":"trich","text":"Bác đã về đây, Tổ quốc ơi! / Nhớ thương, hòn đá hóa thành người / Ba mươi năm ấy chân không nghỉ / Mà đến bây giờ mới tới nơi.","nguoi":"Tố Hữu","nguon_ten":"Bài thơ “Theo chân Bác”, 1970","doc":8},{"loai":"ban_co_biet","text":"Cột mốc 108 là một trong những cột mốc cổ trên biên giới Việt – Trung; trên mặt đá có khắc chữ Hán và chữ Pháp, dấu vết của thời kỳ Pháp và nhà Thanh hoạch định biên giới.","nguon_ten":"Cục Di sản văn hóa, “Di tích lịch sử Pác Bó” – https://dsvh.gov.vn/di-tich-lich-su-pac-bo-2950","doc":9},{"loai":"doan","tieu_de":"Những ngày đầu trên đất mẹ","text":"Qua biên giới, Người được đưa về bản Pác Bó, ở nhà ông Lý Quốc Súng từ ngày 28/1 đến ngày 7/2/1941. Đó là những ngày đầu năm mới, bản làng còn vương không khí Tết. Với bà con, người khách mới là một ông già tên Già Thu, về sau được gọi thân mật là ông Ké. Từ ngày 8/2/1941, để giữ bí mật tuyệt đối, Người chuyển vào ở hang Cốc Bó (xem chuyên đề Hang Cốc Bó, nơi Người ở những ngày đầu về nước).\n\nNgay từ những ngày đầu, Người bắt tay vào công việc. Người gặp gỡ cán bộ địa phương, nghe báo cáo về tình hình phong trào, tìm hiểu đời sống của đồng bào. Người bắt đầu dịch sách, soạn tài liệu, mở lớp huấn luyện, và chuẩn bị cho một hội nghị Trung ương quan trọng. Cuộc sống rất kham khổ, nhưng trong bài thơ “Tức cảnh Pác Bó”, Người lại gọi đó là cuộc đời “thật là sang” (xem chuyên đề Lời Bác). Chỉ trong vài tháng, vùng đầu nguồn yên tĩnh ấy đã trở thành nơi đưa ra những quyết định quan trọng bậc nhất của cách mạng cả nước.","doc":10},{"loai":"anh","src":"textures/bang_w/G12_7_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Trở về Tổ quốc (28/1/1941)”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Từ một bước chân đến ngày độc lập","text":"Những gì diễn ra sau bước chân qua cột mốc 108 cho thấy tầm vóc của cuộc trở về. Chưa đầy bốn tháng sau, từ ngày 10 đến 19/5/1941, Hội nghị Trung ương lần thứ tám họp tại lán Khuổi Nặm dưới sự chủ trì của Người, quyết định thành lập Mặt trận Việt Minh (xem chuyên đề Lán Khuổi Nặm). Cao Bằng được chọn làm nơi thí điểm xây dựng các hội Cứu quốc. Ngày 1/8/1941, báo Việt Nam độc lập do Người sáng lập ra số đầu tiên.\n\nNhững năm tiếp theo là một chặng đường nhiều thử thách. Tháng 8/1942, Người sang Trung Quốc và bị bắt giam hơn một năm. Tháng 9/1944, Người trở lại Pác Bó. Ngày 22/12/1944, Đội Việt Nam Tuyên truyền Giải phóng quân ra đời theo chỉ thị của Người. Tháng 5/1945, Người rời Cao Bằng về Tân Trào. Ngày 2/9/1945, tại Quảng trường Ba Đình, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập. Từ cột mốc biên giới tới Ba Đình là bốn năm bảy tháng, một quãng thời gian ngắn ngủi so với ba mươi năm tìm đường.","doc":11},{"loai":"moc","items":[["5/6/1911","Nguyễn Tất Thành rời bến Nhà Rồng, Sài Gòn, ra đi tìm đường cứu nước"],["Mùa thu 1938","Rời Liên Xô sang Trung Quốc, đến Diên An, rồi hoạt động ở Quế Lâm với tên Hồ Quang"],["6/1940","Ở Côn Minh, gặp Phạm Văn Đồng, Võ Nguyên Giáp; nhận định thời cơ về nước đã đến gần"],["9/1940","Quân Nhật tấn công Lạng Sơn, bắt đầu kéo vào Đông Dương"],["10/1940","Trở lại Quế Lâm, rồi đến Tĩnh Tây, huyện giáp biên giới Cao Bằng"],["Đầu 1941","Mở lớp huấn luyện chính trị cho khoảng 43 thanh niên Cao Bằng ở làng Nậm Quang, sát biên giới"],["28/1/1941","Trưa mùng 2 Tết Tân Tỵ, cùng Lê Quảng Ba, Phùng Chí Kiên, Vũ Anh vượt cột mốc 108 về Pác Bó"],["28/1 – 7/2/1941","Ở nhà ông Lý Quốc Súng trong bản Pác Bó"],["8/2/1941","Chuyển vào ở hang Cốc Bó"],["10 – 19/5/1941","Chủ trì Hội nghị Trung ương lần thứ tám tại Khuổi Nặm, thành lập Mặt trận Việt Minh"],["1/8/1941","Báo Việt Nam độc lập ra số đầu tiên"],["5/1945","Rời Cao Bằng về Tân Trào, chuẩn bị Tổng khởi nghĩa"],["2/9/1945","Đọc Tuyên ngôn Độc lập tại Quảng trường Ba Đình"]],"doc":12},{"loai":"ban_co_biet","text":"Phùng Chí Kiên, một trong những người cùng Người vượt cột mốc 108 ngày 28/1/1941, đã hy sinh ngay trong năm 1941, khi đang chỉ huy lực lượng vũ trang cách mạng.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia; Bảo tàng Hồ Chí Minh","doc":13},{"loai":"anh","src":"textures/bang_w/G12_7_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Trở về Tổ quốc (28/1/1941)”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, cột mốc năm xưa, nay là mốc 675, là một điểm tham quan quen thuộc của Khu di tích lịch sử Pác Bó, được xếp hạng di tích quốc gia đặc biệt năm 2012. Từ cột mốc, người đến thăm có thể lần lượt ghé nhà ông Lý Quốc Súng, hang Cốc Bó, suối Lê-nin và núi Các Mác, theo đúng trình tự những ngày đầu năm 1941. Mỗi điểm dừng là một chặng của mùa xuân trở về.\n\nNgày 28/1 hằng năm được nhắc đến như Ngày Bác Hồ trở về Tổ quốc. Năm 2026, tròn 85 năm sự kiện ấy, Báo Nhân Dân đã có bài nhìn lại ngày trở về như sự mở ra thời kỳ mới của cách mạng Việt Nam. Trong gian trưng bày, không gian 3D tái hiện thung lũng Pác Bó để người xem hình dung con đường nhỏ giữa những triền núi đá. Đứng trước bảng này, người xem có thể tự hỏi: điều gì đã khiến một người năm mươi tuổi, sau ba mươi năm xa quê, chọn trở về đúng lúc gian nguy nhất? Câu trả lời nằm trong toàn bộ những gì diễn ra sau đó, từ hang Cốc Bó tới Quảng trường Ba Đình.","doc":14}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","Báo Nhân Dân, “85 năm Ngày Bác Hồ trở về Tổ quốc, mở ra thời kỳ mới của cách mạng Việt Nam” – https://nhandan.vn/85-nam-ngay-bac-ho-tro-ve-to-quoc-mo-ra-thoi-ky-moi-cua-cach-mang-viet-nam-post939544.html","Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch, “Lãnh tụ Nguyễn Ái Quốc và lớp huấn luyện chính trị trước khi về nước” – https://nhasanbacho.vn/bai-viet/lanh-tu-nguyen-ai-quoc-va-lop-huan-luyen-chinh-tri-truoc-khi-ve-nuoc-3039/","Cục Di sản văn hóa, “Di tích lịch sử Pác Bó” – https://dsvh.gov.vn/di-tich-lich-su-pac-bo-2950","Võ Nguyên Giáp, Những năm tháng không thể nào quên (hồi ký, Hữu Mai thể hiện)","Tố Hữu, “Theo chân Bác” (1970)"],"doc":[{"t":"Cột mốc 108, trưa mùng 2 Tết Tân Tỵ: ba mươi năm khép lại trong một bước chân. Trưa 28/1/1941, khi bà con vùng biên còn đang vui Tết, một nhóm nhỏ lặng lẽ vượt qua cột mốc đá ở đầu thung lũng Pác Bó. Trong nhóm có một người đã rời Tổ quốc từ mùa hè năm 1911. Để đi tới bước chân ấy, Người đã vòng qua Diên An, Quế Lâm, Côn Minh và một lớp học nhỏ sát biên giới."},{"t":"Trưa mùng 2 Tết Tân Tỵ. Trưa ngày 28/1/1941, tức mùng 2 Tết Tân Tỵ, ở các bản vùng biên Hà Quảng, đồng bào Tày, Nùng còn đang vui những ngày đầu năm mới. Giữa không khí ấy, một nhóm nhỏ lặng lẽ đi theo lối mòn giữa những triền núi đá, vượt qua cột mốc biên giới số 108 để vào thung lũng Pác Bó. Trong nhóm có các đồng chí Lê Quảng Ba, Phùng Chí Kiên, Vũ Anh, và một người đàn ông năm mươi tuổi được anh em gọi là Già Thu. Ít ai trong bản biết rằng Già Thu chính là Nguyễn Ái Quốc, người đã rời Tổ quốc từ gần ba mươi năm trước. Các tài liệu kể rằng khoảnh khắc đặt chân qua cột mốc, Người vô cùng xúc động. Phía sau là ba mươi năm bôn ba khắp năm châu. Phía trước là một đất nước đang chịu cảnh một cổ hai tròng dưới ách Pháp – Nhật, và một phong trào cách mạng vừa trải qua những tổn thất nặng nề. Bước chân qua cột mốc đá ấy khép lại một hành trình tìm đường, và mở ra giai đoạn Người trực tiếp lãnh đạo cách mạng ngay trên đất nước mình."},{"t":"Ba mươi năm, hai đầu đất nước. Ngày 5/6/1911, người thanh niên Nguyễn Tất Thành, với tên Văn Ba, làm phụ bếp trên con tàu Amiral Latouche-Tréville, rời bến Nhà Rồng ở Sài Gòn. Gần ba mươi năm sau, Người trở về qua một lối mòn nơi địa đầu phía Bắc. Điểm đi và điểm về của hành trình nằm ở hai đầu đất nước, như thể Người đã đi trọn một vòng quanh thế giới để trở về với Tổ quốc. Trong ba mươi năm ấy, Người sống và hoạt động ở nhiều nước châu Âu, châu Phi, châu Mỹ, châu Á. Người làm đủ nghề để sống, từ phụ bếp, cào tuyết đến thợ sửa ảnh. Người mang nhiều tên gọi khác nhau: Nguyễn Ái Quốc ở Paris, Lý Thụy ở Quảng Châu, Tống Văn Sơ ở Hồng Kông, Hồ Quang ở Quế Lâm. Mỗi cái tên gắn với một chặng đường, một nhiệm vụ. Già Thu là tên gọi mới nhất, tên của người vừa trở về giữa núi rừng Cao Bằng. Chỉ hơn một năm sau, tháng 8/1942, Người sẽ dùng một cái tên khác, cái tên cả thế giới biết đến: Hồ Chí Minh."},{"t":"Con đường vòng qua Trung Quốc. Con đường trở về bắt đầu từ mùa thu năm 1938, khi Người rời Liên Xô sang Trung Quốc. Người đến Diên An, rồi hoạt động ở Quế Lâm với tên Hồ Quang, tìm cách bắt liên lạc với tổ chức Đảng trong nước. Năm 1940, Người có mặt ở Côn Minh, nơi có cơ sở của Đảng ở nước ngoài. Tại đây, tháng 6/1940, Người gặp hai thanh niên từ trong nước sang là Phạm Văn Đồng và Võ Nguyên Giáp. Cũng tháng ấy, nước Pháp thất thủ trước phát xít Đức. Theo hồi ký của Đại tướng Võ Nguyên Giáp, Người nhận định việc Pháp mất nước là cơ hội rất thuận lợi cho cách mạng Việt Nam, phải tìm mọi cách về nước để tranh thủ thời cơ. Tháng 9/1940, quân Nhật tấn công Lạng Sơn, bắt đầu kéo vào Đông Dương. Tháng 10/1940, Người trở lại Quế Lâm, rồi đến Tĩnh Tây, một huyện của tỉnh Quảng Tây giáp Cao Bằng. Từ đây, Người theo dõi sát tình hình trong nước và chuẩn bị cán bộ cho chuyến trở về."},{"t":"Bạn có biết? Tài liệu giảng dạy của lớp huấn luyện chính trị mà Người mở sát biên giới đầu năm 1941 được in đá thành một cuốn sách nhỏ mang tên “Con đường giải phóng”."},{"t":"Lớp học sát biên giới. Khoảng đầu tháng 1/1941, Người chuyển đến làng Nậm Quang, sát biên giới Việt – Trung. Tại đây, Người mở một lớp huấn luyện chính trị cho khoảng 43 thanh niên Cao Bằng. Tham gia tổ chức lớp học có các đồng chí Phùng Chí Kiên, Vũ Anh, Phạm Văn Đồng và Võ Nguyên Giáp. Nội dung gồm ba phần: tình hình thế giới và trong nước, cách tổ chức quần chúng, và phương pháp cách mạng nhằm xây dựng một mặt trận dân tộc rộng rãi. Đại tướng Võ Nguyên Giáp về sau nhớ lại cách chuẩn bị bài giảng rất kỹ lưỡng. Mọi người họp bàn, thống nhất đề cương rồi mới viết. Viết xong lại họp, cùng đọc và sửa chữa. Cuối mỗi bài, học viên được hỏi những câu rất thực tế, chẳng hạn trở về địa phương sẽ làm gì, làm như thế nào. Cách dạy ấy cho thấy Người không muốn đào tạo những người thuộc lý thuyết, mà muốn có những cán bộ biết bắt tay vào việc ngay. Sau lớp học, các học viên trở về Cao Bằng để gây dựng và phát triển cơ sở cách mạng, chuẩn bị cho những bước đi tiếp theo."},{"t":"Vì sao là lúc ấy?. Quyết định về nước năm 1941 không phải là một bước đi ngẫu hứng. Tháng 11/1939, Hội nghị Trung ương lần thứ sáu đã chuyển hướng chỉ đạo, đặt nhiệm vụ giải phóng dân tộc lên hàng đầu. Tháng 11/1940, Hội nghị Trung ương lần thứ bảy tiếp tục khẳng định hướng đi ấy. Nhưng cuối năm 1940, khởi nghĩa Bắc Sơn và khởi nghĩa Nam Kỳ bị đàn áp, nhiều cán bộ lãnh đạo bị bắt. Phong trào trong nước cần một sự chỉ đạo trực tiếp, thống nhất và có uy tín. Người trở về với tư cách đại diện Quốc tế Cộng sản, là người đã chủ trì hội nghị hợp nhất thành lập Đảng đầu năm 1930, mang theo vốn hiểu biết sâu rộng về tình hình thế giới. Chọn Cao Bằng làm nơi đặt chân là chọn một vùng có phong trào cách mạng từ sớm, có địa hình hiểm trở và nằm sát biên giới (xem bảng giới thiệu gian Pác Bó – Cao Bằng). Chưa đầy bốn tháng sau, những tính toán ấy được thể hiện rõ trong các quyết định của Hội nghị Trung ương lần thứ tám."},{"t":"Cột mốc 108, chứng nhân bằng đá. Cột mốc nơi Người bước qua là một cột mốc cổ trên đường biên giới Việt – Trung. Những cột mốc loại này được dựng từ cuối thế kỷ XIX, sau khi Pháp và nhà Thanh ký các công ước hoạch định biên giới giữa Bắc Kỳ và Trung Quốc. Mỗi mốc được đánh số, và mốc số 108 nằm ở đầu thung lũng Pác Bó. Với nhà cầm quyền thời ấy, nó chỉ là một dấu mốc hành chính giữa hai vùng lãnh thổ. Nhưng từ trưa 28/1/1941, cột mốc ấy mang một ý nghĩa khác. Nó đánh dấu nơi người con đi xa đặt chân về đất mẹ. Sau khi Việt Nam và Trung Quốc hoàn thành phân giới, cắm mốc trên toàn tuyến biên giới đất liền năm 2008, vị trí này mang số hiệu mới là mốc 675. Dù vậy, trong sách vở và trong ký ức của nhiều thế hệ, nó vẫn được gọi thân thuộc là cột mốc 108. Gần ba mươi năm sau ngày Người về nước, nhà thơ Tố Hữu đã viết về khoảnh khắc ấy trong bài “Theo chân Bác”, sáng tác năm 1970, bằng những câu thơ nhiều người thuộc lòng."},{"t":"Bác đã về đây, Tổ quốc ơi! / Nhớ thương, hòn đá hóa thành người / Ba mươi năm ấy chân không nghỉ / Mà đến bây giờ mới tới nơi. — Tố Hữu"},{"t":"Bạn có biết? Cột mốc 108 là một trong những cột mốc cổ trên biên giới Việt – Trung; trên mặt đá có khắc chữ Hán và chữ Pháp, dấu vết của thời kỳ Pháp và nhà Thanh hoạch định biên giới."},{"t":"Những ngày đầu trên đất mẹ. Qua biên giới, Người được đưa về bản Pác Bó, ở nhà ông Lý Quốc Súng từ ngày 28/1 đến ngày 7/2/1941. Đó là những ngày đầu năm mới, bản làng còn vương không khí Tết. Với bà con, người khách mới là một ông già tên Già Thu, về sau được gọi thân mật là ông Ké. Từ ngày 8/2/1941, để giữ bí mật tuyệt đối, Người chuyển vào ở hang Cốc Bó (xem chuyên đề Hang Cốc Bó, nơi Người ở những ngày đầu về nước). Ngay từ những ngày đầu, Người bắt tay vào công việc. Người gặp gỡ cán bộ địa phương, nghe báo cáo về tình hình phong trào, tìm hiểu đời sống của đồng bào. Người bắt đầu dịch sách, soạn tài liệu, mở lớp huấn luyện, và chuẩn bị cho một hội nghị Trung ương quan trọng. Cuộc sống rất kham khổ, nhưng trong bài thơ “Tức cảnh Pác Bó”, Người lại gọi đó là cuộc đời “thật là sang” (xem chuyên đề Lời Bác). Chỉ trong vài tháng, vùng đầu nguồn yên tĩnh ấy đã trở thành nơi đưa ra những quyết định quan trọng bậc nhất của cách mạng cả nước."},{"t":"Từ một bước chân đến ngày độc lập. Những gì diễn ra sau bước chân qua cột mốc 108 cho thấy tầm vóc của cuộc trở về. Chưa đầy bốn tháng sau, từ ngày 10 đến 19/5/1941, Hội nghị Trung ương lần thứ tám họp tại lán Khuổi Nặm dưới sự chủ trì của Người, quyết định thành lập Mặt trận Việt Minh (xem chuyên đề Lán Khuổi Nặm). Cao Bằng được chọn làm nơi thí điểm xây dựng các hội Cứu quốc. Ngày 1/8/1941, báo Việt Nam độc lập do Người sáng lập ra số đầu tiên. Những năm tiếp theo là một chặng đường nhiều thử thách. Tháng 8/1942, Người sang Trung Quốc và bị bắt giam hơn một năm. Tháng 9/1944, Người trở lại Pác Bó. Ngày 22/12/1944, Đội Việt Nam Tuyên truyền Giải phóng quân ra đời theo chỉ thị của Người. Tháng 5/1945, Người rời Cao Bằng về Tân Trào. Ngày 2/9/1945, tại Quảng trường Ba Đình, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập. Từ cột mốc biên giới tới Ba Đình là bốn năm bảy tháng, một quãng thời gian ngắn ngủi so với ba mươi năm tìm đường."},{"t":"Các mốc thời gian. 5/6/1911: Nguyễn Tất Thành rời bến Nhà Rồng, Sài Gòn, ra đi tìm đường cứu nước. Mùa thu 1938: Rời Liên Xô sang Trung Quốc, đến Diên An, rồi hoạt động ở Quế Lâm với tên Hồ Quang. 6/1940: Ở Côn Minh, gặp Phạm Văn Đồng, Võ Nguyên Giáp; nhận định thời cơ về nước đã đến gần. 9/1940: Quân Nhật tấn công Lạng Sơn, bắt đầu kéo vào Đông Dương. 10/1940: Trở lại Quế Lâm, rồi đến Tĩnh Tây, huyện giáp biên giới Cao Bằng. Đầu 1941: Mở lớp huấn luyện chính trị cho khoảng 43 thanh niên Cao Bằng ở làng Nậm Quang, sát biên giới. 28/1/1941: Trưa mùng 2 Tết Tân Tỵ, cùng Lê Quảng Ba, Phùng Chí Kiên, Vũ Anh vượt cột mốc 108 về Pác Bó. 28/1 – 7/2/1941: Ở nhà ông Lý Quốc Súng trong bản Pác Bó. 8/2/1941: Chuyển vào ở hang Cốc Bó. 10 – 19/5/1941: Chủ trì Hội nghị Trung ương lần thứ tám tại Khuổi Nặm, thành lập Mặt trận Việt Minh. 1/8/1941: Báo Việt Nam độc lập ra số đầu tiên. 5/1945: Rời Cao Bằng về Tân Trào, chuẩn bị Tổng khởi nghĩa. 2/9/1945: Đọc Tuyên ngôn Độc lập tại Quảng trường Ba Đình."},{"t":"Bạn có biết? Phùng Chí Kiên, một trong những người cùng Người vượt cột mốc 108 ngày 28/1/1941, đã hy sinh ngay trong năm 1941, khi đang chỉ huy lực lượng vũ trang cách mạng."},{"t":"Dấu tích hôm nay. Ngày nay, cột mốc năm xưa, nay là mốc 675, là một điểm tham quan quen thuộc của Khu di tích lịch sử Pác Bó, được xếp hạng di tích quốc gia đặc biệt năm 2012. Từ cột mốc, người đến thăm có thể lần lượt ghé nhà ông Lý Quốc Súng, hang Cốc Bó, suối Lê-nin và núi Các Mác, theo đúng trình tự những ngày đầu năm 1941. Mỗi điểm dừng là một chặng của mùa xuân trở về. Ngày 28/1 hằng năm được nhắc đến như Ngày Bác Hồ trở về Tổ quốc. Năm 2026, tròn 85 năm sự kiện ấy, Báo Nhân Dân đã có bài nhìn lại ngày trở về như sự mở ra thời kỳ mới của cách mạng Việt Nam. Trong gian trưng bày, không gian 3D tái hiện thung lũng Pác Bó để người xem hình dung con đường nhỏ giữa những triền núi đá. Đứng trước bảng này, người xem có thể tự hỏi: điều gì đã khiến một người năm mươi tuổi, sau ba mươi năm xa quê, chọn trở về đúng lúc gian nguy nhất? Câu trả lời nằm trong toàn bộ những gì diễn ra sau đó, từ hang Cốc Bó tới Quảng trường Ba Đình."}],"so_chu":1979},{"i":8,"tieu_de_bang":"Hang Cốc Bó","tieu_de":"Bên trong hang Cốc Bó: giường gỗ kê trên đá, bếp lửa nhỏ và chiếc hòm tài liệu","sapo":"Cửa hang hẹp đến mức chỉ một người lách qua được. Bên trong, mấy cây gỗ gác lên tảng đá là giường, một bếp lửa nhỏ là lò sưởi, một chiếc hòm gỗ là tủ hồ sơ. Đó là toàn bộ nơi ăn chốn ở của người đứng đầu phong trào cách mạng Việt Nam mùa xuân năm 1941. Căn nhà bằng đá ấy kể gì về con người đã sống trong nó?","bia":{"src":"textures/ht/ht_anh_coc_bo.jpg","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Lách qua cửa hang","text":"Muốn vào hang Cốc Bó, người ta phải nghiêng mình lách qua một cửa hang hẹp, chỉ vừa một người đi. Qua khỏi cửa, lòng hang mở rộng hơn, theo hồ sơ di tích của Cục Di sản văn hóa thì rộng chừng tám mươi mét vuông. Ánh sáng ban ngày chỉ hắt vào từ phía cửa, càng vào sâu càng mờ tối. Nền hang ẩm, vách đá vôi lạnh, hơi lạnh của lòng núi tỏa ra suốt đêm. Ngay dưới chân hang là đầu nguồn con suối mà Người đặt tên là suối Lê-nin.\n\nKhông gian ấy chẳng có gì giống một ngôi nhà. Không cửa, không vách ngăn, không đồ đạc theo nghĩa thông thường. Mọi thứ làm nên sự sống ở đây đều do chính những người ở tự tay sắp đặt: vài cây gỗ kê làm chỗ nằm, một bếp lửa, một chiếc hòm. Từ ngày 8/2/1941, đó là nơi ăn, chốn ngủ và cũng là nơi làm việc của Nguyễn Ái Quốc, người mà bà con trong bản chỉ biết với cái tên Già Thu. Sự đơn sơ đến tận cùng ấy khiến hang Cốc Bó trở thành một hiện vật lặng lẽ mà giàu sức kể về những ngày đầu Người trở về.","doc":1},{"loai":"doan","tieu_de":"Mười một ngày dưới mái nhà sàn","text":"Hang đá không phải chỗ dừng chân đầu tiên. Theo hồ sơ di tích, từ ngày 28/1 đến ngày 7/2/1941, Người ở tạm nhà ông Lý Quốc Súng trong bản Pác Bó, một ngôi nhà sàn theo lối quen thuộc của đồng bào vùng biên. Những ngày ấy trùng dịp Tết Tân Tỵ, bản làng còn vương không khí đầu xuân. Với bà con, người khách mới đến là một ông cụ tên Thu, ăn mặc, sinh hoạt giản dị như mọi người trong bản.\n\nNhưng một ngôi nhà giữa bản, dù chủ nhà hết lòng che giấu, vẫn khó giữ kín lâu sự có mặt của một người lạ. Mật thám và tay sai của chính quyền thực dân lại thường xuyên dò la vùng biên giới. Vì thế, sau mười một ngày, Người cùng các đồng chí chuyển lên hang Cốc Bó ở đầu nguồn, xa hẳn đường đi lối lại. Những lý do chọn hang đá làm nơi ở đã được kể trong chuyên đề “Hang Cốc Bó, nơi Người ở những ngày đầu về nước”. Ở đây, chúng ta bước hẳn vào bên trong, để xem Người đã sống và làm việc ra sao giữa bốn bức vách đá.","doc":2},{"loai":"anh","src":"textures/bang_w/G12_8_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hang Cốc Bó”, nhìn từ xa."},{"loai":"doan","tieu_de":"Một mùa xuân nhiều sóng gió","text":"Để hiểu vì sao người đứng đầu phong trào phải sống trong một hang đá, cần nhìn lại những tháng trước đó. Tháng 6/1940, nước Pháp đầu hàng phát xít Đức. Tháng 9/1940, quân Nhật tiến vào Đông Dương, nhân dân ta bắt đầu chịu cảnh một cổ hai tròng. Cũng trong mấy tháng ấy, khởi nghĩa Bắc Sơn, khởi nghĩa Nam Kỳ và binh biến Đô Lương lần lượt nổ ra rồi bị đàn áp đẫm máu. Nhiều cán bộ, đảng viên bị bắt, bị giết, nhiều cơ sở bị vỡ.\n\nMạng lưới mật thám dày đặc, việc lùng bắt người cách mạng càng thêm gắt gao. Trong hoàn cảnh ấy, sự an toàn của người vừa trở về có ý nghĩa sống còn với cả phong trào. Hang Cốc Bó vì thế không chỉ là chỗ tránh rét, tránh mưa. Đó là nơi giữ an toàn cho người lãnh đạo, để Người tổng kết những bài học xương máu vừa qua và chuẩn bị cho những quyết định lớn sắp tới. Căn hang nhỏ ở đầu nguồn, trong những tuần ấy, gánh trên mình một trách nhiệm lớn hơn nhiều so với vóc dáng khiêm nhường của nó.","doc":3},{"loai":"ban_co_biet","text":"Nhà ông Lý Quốc Súng, nơi Người ở mười một ngày đầu tiên sau khi về nước, từ 28/1 đến 7/2/1941, được dựng khoảng năm 1937 theo kiểu nhà sàn của đồng bào địa phương. Ngôi nhà nay là một điểm di tích trong quần thể Pác Bó.","nguon_ten":"Cục Di sản văn hóa (Bộ Văn hóa, Thể thao và Du lịch) – “Di tích lịch sử Pác Bó”, https://dsvh.gov.vn/di-tich-lich-su-pac-bo-2950","doc":4},{"loai":"doan","tieu_de":"Chiếc giường gác trên đá","text":"Chỗ nằm của Người được làm theo cách giản dị nhất: gác hai cây gỗ lên những tảng đá, ghép ván lên trên làm mặt nằm. Cách kê cao ấy giúp người nằm tránh hơi ẩm từ nền hang bốc lên, cũng giống như đồng bào vùng núi vẫn làm nhà sàn để tránh ẩm thấp, rắn rết. Mặt nằm là gỗ cứng, xung quanh là hơi lạnh của đá và của dòng suối đầu nguồn.\n\nNằm trên chiếc giường ấy, có thể nghe tiếng suối chảy dưới chân hang và tiếng gió lùa qua cửa đá. Suốt ba mươi năm bôn ba, Người đã quen với những chỗ ngủ tạm bợ: khoang tàu biển, căn phòng trọ nhỏ ở Pa-ri, những nơi ẩn náu ở Xiêm, ở Hương Cảng. Nay đã về đến đất mẹ, chỗ nằm vẫn chỉ là vài cây gỗ. Thế nhưng từ những ngày này, sau ngần ấy năm, Người được sống giữa phong trào trong nước, nghe cán bộ báo cáo tận nơi, thay vì chờ tin qua những đường dây liên lạc xa xôi và chậm trễ.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_coc_bo.jpg","chu_thich":"Cửa hang Cốc Bó dưới chân vách núi đá vôi, Pác Bó, Cao Bằng – nơi Nguyễn Ái Quốc ở từ ngày 8/2/1941. Ảnh chụp năm 2016.","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Bếp lửa những đêm rét","text":"Góc hang có một bếp lửa nhỏ. Tháng Hai, tháng Ba ở vùng núi đá biên giới Cao Bằng vẫn còn những đợt rét buốt. Đêm xuống, hơi lạnh từ vách đá và từ dòng suối đầu nguồn thấm vào người. Bếp lửa là nguồn sưởi ấm chính của những người ở trong hang, đồng thời là thứ ánh sáng hiếm hoi giữa lòng núi tối.\n\nBếp lửa cũng là chỗ nấu những bữa ăn đạm bạc mà bài thơ “Tức cảnh Pác Bó” đã ghi lại: cháo bẹ, tức cháo ngô, với rau măng hái trong rừng. Ý nghĩa của bài thơ được kể riêng trong chuyên đề Lời Bác. Theo hồ sơ di tích, trong hang còn chỗ Người ngồi làm việc với cán bộ cách mạng và dịch những tài liệu quan trọng. Như vậy, căn hang không chỉ để ngủ. Bên ánh lửa, những buổi làm việc với anh em cán bộ vẫn diễn ra, và những trang tài liệu vẫn được viết tiếp. Một nếp sinh hoạt đều đặn, ngăn nắp được giữ gìn, dù chỗ ở chỉ là một hang đá ẩm lạnh nơi đầu nguồn.","doc":6},{"loai":"doan","tieu_de":"Chiếc hòm gỗ, tủ hồ sơ của phong trào","text":"Trong hang có một chiếc hòm gỗ dùng để cất tài liệu, sách báo. Với người làm cách mạng bí mật, giấy tờ vừa quý giá vừa nguy hiểm. Quý vì đó là sách lý luận, là bản dịch đang làm dở, là tin tức từ các địa phương gửi lên. Nguy hiểm vì chỉ một tờ giấy rơi vào tay địch cũng có thể làm lộ cả một đường dây liên lạc. Hang đá lại ẩm, giấy dễ mục, mực dễ nhòe, nên chiếc hòm vừa giữ bí mật vừa giữ cho giấy khô ráo.\n\nNhững trang sách và bản thảo làm dở ở phiến đá bên suối cần một chỗ cất giữ kín đáo khi Người trở về hang. Công việc bên phiến đá ấy được kể riêng trong chuyên đề “Bàn đá bên suối Lê-nin”. Chiếc hòm trong không gian 3D của gian trưng bày là đồ vật minh họa, gợi lại vật dụng đơn sơ mà quan trọng bậc nhất ấy. Nó nhắc rằng cuộc đấu tranh giành độc lập bắt đầu không chỉ bằng súng đạn, mà trước hết bằng chữ nghĩa, bằng sự chuẩn bị kiên nhẫn về tư tưởng và tổ chức.","doc":7},{"loai":"ban_co_biet","text":"Trong hang Cốc Bó còn dấu tích dòng chữ “Nhất cửu tứ nhất niên nhị nguyệt bát nhật”, đọc theo âm Hán Việt nghĩa là ngày 8 tháng 2 năm 1941, đúng ngày Người chuyển vào ở hang.","nguon_ten":"Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh – “Người về đem tới mùa xuân – Bài 1: Pác Bó in dấu chân Người”, https://hochiminh.vn/tin-tuc/nguoi-ve-dem-toi-mua-xuan-bai-1-pac-bo-in-dau-chan-nguoi.html","doc":8},{"loai":"doan","tieu_de":"Những người tìm đến hang","text":"Căn hang hẹp nhưng không hề đóng kín với phong trào. Trong những tuần ở Cốc Bó, Người vừa dịch sách, soạn tài liệu, vừa gặp gỡ cán bộ, tìm hiểu tình hình trong nước và chuẩn bị cho Hội nghị Trung ương lần thứ tám. Cán bộ từ các nơi theo đường dây bí mật tìm về đầu nguồn, báo cáo tình hình, nhận chỉ thị rồi lại lặng lẽ trở về cơ sở. Người mở lớp huấn luyện cán bộ ngay tại vùng Pác Bó, học viên là thanh niên các dân tộc trong vùng.\n\nBảo vệ và tiếp tế cho hang là việc của anh em cán bộ và của đồng bào quanh vùng, những người giữ kín tuyệt đối sự có mặt của “ông Ké”. Mỗi bước chân lên hang đều phải cẩn trọng, mỗi người đến đều phải được tin cậy. Nhờ vậy, căn hang nhỏ trở thành một trung tâm chỉ đạo thu nhỏ. Ở đó, kinh nghiệm ba mươi năm hoạt động ở nước ngoài gặp thực tiễn nóng hổi của phong trào trong nước, để từ đó hình thành đường lối cho chặng đường mới của cách mạng.","doc":9},{"loai":"anh","src":"textures/bang_w/G12_8_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hang Cốc Bó”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Rời hang đá","text":"Theo hồ sơ di tích, Người ở hang Cốc Bó đến khoảng giữa tháng 3/1941. Nguyên tắc sống còn của hoạt động bí mật là không ở một chỗ quá lâu, nhất là khi địch bắt đầu dò la, lùng sục vùng biên. Cuối tháng 3/1941, Người dùng hang Lũng Lạn làm nơi ở, một hang nhỏ hơn, rộng khoảng năm mươi mét vuông. Sau đó, nơi ở và làm việc chính của Người là lán Khuổi Nặm nép bên bìa rừng, cũng là nơi Người ở lâu nhất trong vùng Pác Bó, được kể trong chuyên đề “Lán Khuổi Nặm”.\n\nDù chỉ gắn với Người trong những tuần đầu tiên, hang Cốc Bó đã trở thành biểu tượng của cả thời kỳ Pác Bó. Bởi đó là nơi ở đầu tiên của Người trong căn cứ địa, nơi những ngày gian khổ nhất được ghi lại trong câu thơ “Sáng ra bờ suối, tối vào hang”. Hai mươi năm sau, tháng 2/1961, đã là Chủ tịch nước, Người trở lại thăm Pác Bó, thăm đồng bào đã từng che chở mình trong những năm tháng ấy.","doc":10},{"loai":"anh","src":"textures/bang_w/G12_8_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hang Cốc Bó”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, hang Cốc Bó là điểm trung tâm của Khu di tích lịch sử Pác Bó, được Thủ tướng Chính phủ xếp hạng di tích quốc gia đặc biệt theo Quyết định số 548/QĐ-TTg ngày 10/5/2012. Theo Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh, đường lên hang có 79 bậc đá dài ngắn khác nhau, tượng trưng cho 79 mùa xuân của Người. Khách tham quan vẫn phải cúi mình lách qua cửa hang hẹp như năm xưa, để hình dung chỗ nằm kê trên đá và bếp lửa sưởi những đêm rét.\n\nTrong gian trưng bày của Bảo tàng Hành trình 3D, góc hang Cốc Bó có chiếc hòm gỗ và chiếc bát gỗ bên bếp. Đó đều là đồ vật minh họa, giúp người xem hình dung cuộc sống của Người mùa xuân năm 1941; bấm vào từng đồ vật, bạn sẽ đọc được câu chuyện riêng của nó. Còn căn hang thật ở Pác Bó vẫn lặng lẽ dưới chân núi, bên dòng suối trong, như một chứng nhân của những ngày gian khổ mà rạng rỡ, khi con đường dẫn tới mùa thu độc lập bắt đầu từ một hang đá.","doc":11},{"loai":"ban_co_biet","text":"Hang Lũng Lạn, nơi Người chuyển đến sau hang Cốc Bó vào cuối tháng 3/1941, chỉ rộng khoảng năm mươi mét vuông, trong khi lòng hang Cốc Bó rộng chừng tám mươi mét vuông.","nguon_ten":"Cục Di sản văn hóa (Bộ Văn hóa, Thể thao và Du lịch) – “Di tích lịch sử Pác Bó”, https://dsvh.gov.vn/di-tich-lich-su-pac-bo-2950","doc":12}],"nguon":["Cục Di sản văn hóa (Bộ Văn hóa, Thể thao và Du lịch) – “Di tích lịch sử Pác Bó”, https://dsvh.gov.vn/di-tich-lich-su-pac-bo-2950","Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh – “Người về đem tới mùa xuân – Bài 1: Pác Bó in dấu chân Người”, https://hochiminh.vn/tin-tuc/nguoi-ve-dem-toi-mua-xuan-bai-1-pac-bo-in-dau-chan-nguoi.html","Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","Khu di tích lịch sử Pác Bó (Cao Bằng)","Quyết định số 548/QĐ-TTg ngày 10/5/2012 của Thủ tướng Chính phủ về việc xếp hạng di tích quốc gia đặc biệt","Hồ Chí Minh, “Tức cảnh Pác Bó” (1941), Hồ Chí Minh Toàn tập, tập 3, NXB Chính trị quốc gia, 2011"],"doc":[{"t":"Bên trong hang Cốc Bó: giường gỗ kê trên đá, bếp lửa nhỏ và chiếc hòm tài liệu. Cửa hang hẹp đến mức chỉ một người lách qua được. Bên trong, mấy cây gỗ gác lên tảng đá là giường, một bếp lửa nhỏ là lò sưởi, một chiếc hòm gỗ là tủ hồ sơ. Đó là toàn bộ nơi ăn chốn ở của người đứng đầu phong trào cách mạng Việt Nam mùa xuân năm 1941. Căn nhà bằng đá ấy kể gì về con người đã sống trong nó?"},{"t":"Lách qua cửa hang. Muốn vào hang Cốc Bó, người ta phải nghiêng mình lách qua một cửa hang hẹp, chỉ vừa một người đi. Qua khỏi cửa, lòng hang mở rộng hơn, theo hồ sơ di tích của Cục Di sản văn hóa thì rộng chừng tám mươi mét vuông. Ánh sáng ban ngày chỉ hắt vào từ phía cửa, càng vào sâu càng mờ tối. Nền hang ẩm, vách đá vôi lạnh, hơi lạnh của lòng núi tỏa ra suốt đêm. Ngay dưới chân hang là đầu nguồn con suối mà Người đặt tên là suối Lê-nin. Không gian ấy chẳng có gì giống một ngôi nhà. Không cửa, không vách ngăn, không đồ đạc theo nghĩa thông thường. Mọi thứ làm nên sự sống ở đây đều do chính những người ở tự tay sắp đặt: vài cây gỗ kê làm chỗ nằm, một bếp lửa, một chiếc hòm. Từ ngày 8/2/1941, đó là nơi ăn, chốn ngủ và cũng là nơi làm việc của Nguyễn Ái Quốc, người mà bà con trong bản chỉ biết với cái tên Già Thu. Sự đơn sơ đến tận cùng ấy khiến hang Cốc Bó trở thành một hiện vật lặng lẽ mà giàu sức kể về những ngày đầu Người trở về."},{"t":"Mười một ngày dưới mái nhà sàn. Hang đá không phải chỗ dừng chân đầu tiên. Theo hồ sơ di tích, từ ngày 28/1 đến ngày 7/2/1941, Người ở tạm nhà ông Lý Quốc Súng trong bản Pác Bó, một ngôi nhà sàn theo lối quen thuộc của đồng bào vùng biên. Những ngày ấy trùng dịp Tết Tân Tỵ, bản làng còn vương không khí đầu xuân. Với bà con, người khách mới đến là một ông cụ tên Thu, ăn mặc, sinh hoạt giản dị như mọi người trong bản. Nhưng một ngôi nhà giữa bản, dù chủ nhà hết lòng che giấu, vẫn khó giữ kín lâu sự có mặt của một người lạ. Mật thám và tay sai của chính quyền thực dân lại thường xuyên dò la vùng biên giới. Vì thế, sau mười một ngày, Người cùng các đồng chí chuyển lên hang Cốc Bó ở đầu nguồn, xa hẳn đường đi lối lại. Những lý do chọn hang đá làm nơi ở đã được kể trong chuyên đề “Hang Cốc Bó, nơi Người ở những ngày đầu về nước”. Ở đây, chúng ta bước hẳn vào bên trong, để xem Người đã sống và làm việc ra sao giữa bốn bức vách đá."},{"t":"Một mùa xuân nhiều sóng gió. Để hiểu vì sao người đứng đầu phong trào phải sống trong một hang đá, cần nhìn lại những tháng trước đó. Tháng 6/1940, nước Pháp đầu hàng phát xít Đức. Tháng 9/1940, quân Nhật tiến vào Đông Dương, nhân dân ta bắt đầu chịu cảnh một cổ hai tròng. Cũng trong mấy tháng ấy, khởi nghĩa Bắc Sơn, khởi nghĩa Nam Kỳ và binh biến Đô Lương lần lượt nổ ra rồi bị đàn áp đẫm máu. Nhiều cán bộ, đảng viên bị bắt, bị giết, nhiều cơ sở bị vỡ. Mạng lưới mật thám dày đặc, việc lùng bắt người cách mạng càng thêm gắt gao. Trong hoàn cảnh ấy, sự an toàn của người vừa trở về có ý nghĩa sống còn với cả phong trào. Hang Cốc Bó vì thế không chỉ là chỗ tránh rét, tránh mưa. Đó là nơi giữ an toàn cho người lãnh đạo, để Người tổng kết những bài học xương máu vừa qua và chuẩn bị cho những quyết định lớn sắp tới. Căn hang nhỏ ở đầu nguồn, trong những tuần ấy, gánh trên mình một trách nhiệm lớn hơn nhiều so với vóc dáng khiêm nhường của nó."},{"t":"Bạn có biết? Nhà ông Lý Quốc Súng, nơi Người ở mười một ngày đầu tiên sau khi về nước, từ 28/1 đến 7/2/1941, được dựng khoảng năm 1937 theo kiểu nhà sàn của đồng bào địa phương. Ngôi nhà nay là một điểm di tích trong quần thể Pác Bó."},{"t":"Chiếc giường gác trên đá. Chỗ nằm của Người được làm theo cách giản dị nhất: gác hai cây gỗ lên những tảng đá, ghép ván lên trên làm mặt nằm. Cách kê cao ấy giúp người nằm tránh hơi ẩm từ nền hang bốc lên, cũng giống như đồng bào vùng núi vẫn làm nhà sàn để tránh ẩm thấp, rắn rết. Mặt nằm là gỗ cứng, xung quanh là hơi lạnh của đá và của dòng suối đầu nguồn. Nằm trên chiếc giường ấy, có thể nghe tiếng suối chảy dưới chân hang và tiếng gió lùa qua cửa đá. Suốt ba mươi năm bôn ba, Người đã quen với những chỗ ngủ tạm bợ: khoang tàu biển, căn phòng trọ nhỏ ở Pa-ri, những nơi ẩn náu ở Xiêm, ở Hương Cảng. Nay đã về đến đất mẹ, chỗ nằm vẫn chỉ là vài cây gỗ. Thế nhưng từ những ngày này, sau ngần ấy năm, Người được sống giữa phong trào trong nước, nghe cán bộ báo cáo tận nơi, thay vì chờ tin qua những đường dây liên lạc xa xôi và chậm trễ."},{"t":"Bếp lửa những đêm rét. Góc hang có một bếp lửa nhỏ. Tháng Hai, tháng Ba ở vùng núi đá biên giới Cao Bằng vẫn còn những đợt rét buốt. Đêm xuống, hơi lạnh từ vách đá và từ dòng suối đầu nguồn thấm vào người. Bếp lửa là nguồn sưởi ấm chính của những người ở trong hang, đồng thời là thứ ánh sáng hiếm hoi giữa lòng núi tối. Bếp lửa cũng là chỗ nấu những bữa ăn đạm bạc mà bài thơ “Tức cảnh Pác Bó” đã ghi lại: cháo bẹ, tức cháo ngô, với rau măng hái trong rừng. Ý nghĩa của bài thơ được kể riêng trong chuyên đề Lời Bác. Theo hồ sơ di tích, trong hang còn chỗ Người ngồi làm việc với cán bộ cách mạng và dịch những tài liệu quan trọng. Như vậy, căn hang không chỉ để ngủ. Bên ánh lửa, những buổi làm việc với anh em cán bộ vẫn diễn ra, và những trang tài liệu vẫn được viết tiếp. Một nếp sinh hoạt đều đặn, ngăn nắp được giữ gìn, dù chỗ ở chỉ là một hang đá ẩm lạnh nơi đầu nguồn."},{"t":"Chiếc hòm gỗ, tủ hồ sơ của phong trào. Trong hang có một chiếc hòm gỗ dùng để cất tài liệu, sách báo. Với người làm cách mạng bí mật, giấy tờ vừa quý giá vừa nguy hiểm. Quý vì đó là sách lý luận, là bản dịch đang làm dở, là tin tức từ các địa phương gửi lên. Nguy hiểm vì chỉ một tờ giấy rơi vào tay địch cũng có thể làm lộ cả một đường dây liên lạc. Hang đá lại ẩm, giấy dễ mục, mực dễ nhòe, nên chiếc hòm vừa giữ bí mật vừa giữ cho giấy khô ráo. Những trang sách và bản thảo làm dở ở phiến đá bên suối cần một chỗ cất giữ kín đáo khi Người trở về hang. Công việc bên phiến đá ấy được kể riêng trong chuyên đề “Bàn đá bên suối Lê-nin”. Chiếc hòm trong không gian 3D của gian trưng bày là đồ vật minh họa, gợi lại vật dụng đơn sơ mà quan trọng bậc nhất ấy. Nó nhắc rằng cuộc đấu tranh giành độc lập bắt đầu không chỉ bằng súng đạn, mà trước hết bằng chữ nghĩa, bằng sự chuẩn bị kiên nhẫn về tư tưởng và tổ chức."},{"t":"Bạn có biết? Trong hang Cốc Bó còn dấu tích dòng chữ “Nhất cửu tứ nhất niên nhị nguyệt bát nhật”, đọc theo âm Hán Việt nghĩa là ngày 8 tháng 2 năm 1941, đúng ngày Người chuyển vào ở hang."},{"t":"Những người tìm đến hang. Căn hang hẹp nhưng không hề đóng kín với phong trào. Trong những tuần ở Cốc Bó, Người vừa dịch sách, soạn tài liệu, vừa gặp gỡ cán bộ, tìm hiểu tình hình trong nước và chuẩn bị cho Hội nghị Trung ương lần thứ tám. Cán bộ từ các nơi theo đường dây bí mật tìm về đầu nguồn, báo cáo tình hình, nhận chỉ thị rồi lại lặng lẽ trở về cơ sở. Người mở lớp huấn luyện cán bộ ngay tại vùng Pác Bó, học viên là thanh niên các dân tộc trong vùng. Bảo vệ và tiếp tế cho hang là việc của anh em cán bộ và của đồng bào quanh vùng, những người giữ kín tuyệt đối sự có mặt của “ông Ké”. Mỗi bước chân lên hang đều phải cẩn trọng, mỗi người đến đều phải được tin cậy. Nhờ vậy, căn hang nhỏ trở thành một trung tâm chỉ đạo thu nhỏ. Ở đó, kinh nghiệm ba mươi năm hoạt động ở nước ngoài gặp thực tiễn nóng hổi của phong trào trong nước, để từ đó hình thành đường lối cho chặng đường mới của cách mạng."},{"t":"Rời hang đá. Theo hồ sơ di tích, Người ở hang Cốc Bó đến khoảng giữa tháng 3/1941. Nguyên tắc sống còn của hoạt động bí mật là không ở một chỗ quá lâu, nhất là khi địch bắt đầu dò la, lùng sục vùng biên. Cuối tháng 3/1941, Người dùng hang Lũng Lạn làm nơi ở, một hang nhỏ hơn, rộng khoảng năm mươi mét vuông. Sau đó, nơi ở và làm việc chính của Người là lán Khuổi Nặm nép bên bìa rừng, cũng là nơi Người ở lâu nhất trong vùng Pác Bó, được kể trong chuyên đề “Lán Khuổi Nặm”. Dù chỉ gắn với Người trong những tuần đầu tiên, hang Cốc Bó đã trở thành biểu tượng của cả thời kỳ Pác Bó. Bởi đó là nơi ở đầu tiên của Người trong căn cứ địa, nơi những ngày gian khổ nhất được ghi lại trong câu thơ “Sáng ra bờ suối, tối vào hang”. Hai mươi năm sau, tháng 2/1961, đã là Chủ tịch nước, Người trở lại thăm Pác Bó, thăm đồng bào đã từng che chở mình trong những năm tháng ấy."},{"t":"Dấu tích hôm nay. Ngày nay, hang Cốc Bó là điểm trung tâm của Khu di tích lịch sử Pác Bó, được Thủ tướng Chính phủ xếp hạng di tích quốc gia đặc biệt theo Quyết định số 548/QĐ-TTg ngày 10/5/2012. Theo Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh, đường lên hang có 79 bậc đá dài ngắn khác nhau, tượng trưng cho 79 mùa xuân của Người. Khách tham quan vẫn phải cúi mình lách qua cửa hang hẹp như năm xưa, để hình dung chỗ nằm kê trên đá và bếp lửa sưởi những đêm rét. Trong gian trưng bày của Bảo tàng Hành trình 3D, góc hang Cốc Bó có chiếc hòm gỗ và chiếc bát gỗ bên bếp. Đó đều là đồ vật minh họa, giúp người xem hình dung cuộc sống của Người mùa xuân năm 1941; bấm vào từng đồ vật, bạn sẽ đọc được câu chuyện riêng của nó. Còn căn hang thật ở Pác Bó vẫn lặng lẽ dưới chân núi, bên dòng suối trong, như một chứng nhân của những ngày gian khổ mà rạng rỡ, khi con đường dẫn tới mùa thu độc lập bắt đầu từ một hang đá."},{"t":"Bạn có biết? Hang Lũng Lạn, nơi Người chuyển đến sau hang Cốc Bó vào cuối tháng 3/1941, chỉ rộng khoảng năm mươi mét vuông, trong khi lòng hang Cốc Bó rộng chừng tám mươi mét vuông."}],"so_chu":1963},{"i":9,"tieu_de_bang":"Bàn đá bên suối Lê-nin","tieu_de":"“Bàn đá chông chênh”: văn phòng giữa trời bên suối Lê-nin","sapo":"Không bàn ghế, không đèn, không mái che. Mỗi ngày, người đàn ông năm mươi tuổi mà bà con gọi là Già Thu ra ngồi bên một phiến đá cạnh suối, đặt giấy lên mặt đá gồ ghề và bắt đầu viết. Từ “văn phòng” giữa trời ấy, những trang sách lý luận được chuyển sang tiếng Việt, những tài liệu huấn luyện đầu tiên của vùng căn cứ ra đời.","bia":{"src":"textures/bai/G12_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Một phiến đá, một dòng suối","text":"Phiến đá nằm sát mép suối Lê-nin, cách cửa hang Cốc Bó không xa. Đó là một khối đá tự nhiên, mặt trên tương đối phẳng nhưng vẫn gồ ghề, mấp mô. Đặt giấy bút lên thì chênh vênh, ngồi lâu thì mỏi, đúng như chữ “chông chênh” mà Người sau này đưa vào thơ. Trước mặt là dòng suối nước trong xanh chảy trên lòng cuội, sau lưng là vách núi đá vôi mà Người đặt tên là núi Các Mác.\n\nChẳng ai dựng nên chiếc bàn ấy. Nó có sẵn ở đó từ bao đời, như trăm nghìn tảng đá khác dọc con suối đầu nguồn. Chỉ đến mùa xuân năm 1941, khi một người khách lạ chọn nó làm chỗ ngồi viết mỗi ngày, phiến đá mới có tên gọi riêng. Người dân quanh vùng và khách thập phương về sau quen gọi nó là “bàn đá chông chênh”. Một vật vô tri của núi rừng đã trở thành di tích, chỉ vì nó từng nâng đỡ những trang giấy làm nên lịch sử. Câu chuyện của phiến đá vì thế cũng là câu chuyện về cách làm việc của Người trong những ngày đầu trở về.","doc":1},{"loai":"doan","tieu_de":"Vì sao phải ra bờ suối?","text":"Câu thơ “Sáng ra bờ suối, tối vào hang” ghi lại nhịp sống đều đặn của Người ở Pác Bó. Lý do đầu tiên của nhịp sống ấy rất giản dị: trong hang tối, ánh sáng ban ngày chỉ hắt vào từ cửa hang hẹp. Muốn đọc sách, dịch sách, viết tài liệu trong nhiều giờ liền, phải ra chỗ sáng. Bờ suối trước hang là nơi gần nhất có đủ ánh sáng, lại thoáng đãng, khô ráo hơn lòng hang ẩm lạnh.\n\nNgồi bên suối, Người vẫn ở trong vùng được bảo vệ, cách hang chỉ vài bước chân. Đồng bào và anh em cán bộ canh gác các lối vào thung lũng. Như vậy, phiến đá vừa là chỗ làm việc, vừa nằm trong vòng an toàn của căn cứ nhỏ ở đầu nguồn. Ngày làm việc ngoài trời, tối về hang nghỉ và tiếp tục công việc bên bếp lửa. Nhịp ấy lặp đi lặp lại suốt những tuần Người ở hang Cốc Bó, bền bỉ như tiếng suối chảy không ngừng ngay bên cạnh.","doc":2},{"loai":"anh","src":"textures/bang_w/G12_9_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bàn đá bên suối Lê-nin”, nhìn từ xa."},{"loai":"doan","tieu_de":"Cuốn sách được dịch trên mặt đá","text":"Công việc được nhắc tới trong câu thơ “Bàn đá chông chênh dịch sử Đảng” là việc dịch cuốn Lịch sử Đảng Cộng sản (b) Liên Xô sang tiếng Việt. Đây là cuốn giáo trình tóm tắt xuất bản ở Liên Xô năm 1938. Sách kể lại chặng đường của những người cộng sản Nga, từ các nhóm mác-xít đầu tiên cuối thế kỷ XIX, qua cuộc cách mạng năm 1905, Cách mạng Tháng Mười năm 1917, đến công cuộc xây dựng chủ nghĩa xã hội ở Liên Xô.\n\nVới những người cách mạng Việt Nam năm 1941, cuốn sách chứa đựng nhiều kinh nghiệm quý. Đó là kinh nghiệm xây dựng một đảng cách mạng trong điều kiện hoạt động bí mật, kinh nghiệm kết hợp các hình thức đấu tranh, kinh nghiệm chuẩn bị lực lượng và chớp thời cơ giành chính quyền. Người dịch sách để làm tài liệu huấn luyện cán bộ, giúp những người cách mạng trẻ ở vùng căn cứ học tập cách xây dựng Đảng và lãnh đạo cách mạng. Trên mặt đá gồ ghề, từng trang sách lý luận dày đặc được chuyển thành tiếng Việt để cán bộ có thể đọc, học và làm theo.","doc":3},{"loai":"trich","text":"Đảng muốn vững thì phải có chủ nghĩa làm cốt, trong đảng ai cũng phải hiểu, ai cũng phải theo chủ nghĩa ấy. Đảng mà không có chủ nghĩa cũng như người không có trí khôn, tàu không có bàn chỉ nam.","nguoi":"Nguyễn Ái Quốc","nguon_ten":"Đường Kách mệnh (1927) – Hồ Chí Minh Toàn tập, tập 2, NXB Chính trị quốc gia, 2011","doc":4},{"loai":"doan","tieu_de":"Lý luận cho những người đi đầu","text":"Việc dịch sách lý luận giữa rừng không phải một ý thích bất chợt. Từ năm 1925 – 1927, ở Quảng Châu, Nguyễn Ái Quốc đã trực tiếp mở các lớp huấn luyện cho thanh niên Việt Nam. Những bài giảng ở đó được tập hợp thành cuốn Đường Kách mệnh, trong đó Người khẳng định đảng cách mạng phải có chủ nghĩa làm cốt. Mười bốn năm sau, trở về Pác Bó, Người lại bắt đầu từ chính việc ấy: đào tạo con người trước khi phát động phong trào.\n\nNhu cầu ấy càng cấp thiết vào năm 1941. Sau những đợt khủng bố những năm 1939 – 1940, nhiều cán bộ cốt cán bị bắt, bị giết, nhiều cơ sở tan vỡ. Phong trào cần một lớp cán bộ mới, phần đông là thanh niên các dân tộc ở vùng căn cứ, nhiệt tình nhưng chưa được học tập bài bản. Những trang dịch trên bàn đá chính là giáo trình cho lớp người ấy. Họ sẽ là những người đi đầu trong việc xây dựng các hội Cứu quốc, tổ chức du kích và chuẩn bị cho ngày khởi nghĩa.","doc":5},{"loai":"ban_co_biet","text":"Chữ “(b)” trong tên cuốn Lịch sử Đảng Cộng sản (b) Liên Xô là viết tắt của “bôn-sê-vích”, tên gọi của phái đa số trong Đảng Công nhân Dân chủ Xã hội Nga do Lê-nin đứng đầu. Nguyên bản là giáo trình tóm tắt xuất bản ở Liên Xô năm 1938.","nguon_ten":"Lịch sử Đảng Cộng sản (bôn-sê-vích) Liên Xô – Giáo trình tóm tắt, Mát-xcơ-va, 1938","doc":6},{"loai":"doan","tieu_de":"Không chỉ một cuốn sách","text":"Bản dịch “sử Đảng” chỉ là một phần trong khối lượng công việc đồ sộ của Người ở vùng căn cứ Cao Bằng. Người soạn tài liệu, viết bài và chuẩn bị nội dung cho các lớp huấn luyện cán bộ mở ngay tại Pác Bó. Người viết nhiều bài ca vận động bằng thơ lục bát cho đồng bào dễ thuộc, dễ nhớ, trong đó có bài diễn ca “Lịch sử nước ta” (xem chuyên đề “Lịch sử nước ta” và dự báo năm 1945). Người còn biên soạn tài liệu quân sự cho các đội du kích.\n\nNgày 1/8/1941, tờ báo Việt Nam độc lập do Người sáng lập ra số đầu tiên, làm cơ quan tuyên truyền của Việt Minh tỉnh Cao Bằng. Báo viết ngắn, dễ hiểu, nhiều bài bằng văn vần. Không phải mọi trang viết ấy đều ra đời trên phiến đá bên suối, bởi sau hang Cốc Bó Người còn ở và làm việc ở nhiều nơi khác trong vùng. Nhưng phiến đá là nơi mở đầu, là hình ảnh tượng trưng cho cả một thời kỳ Người dùng ngòi bút để chuẩn bị cho cách mạng.","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_pac_bo.jpg","chu_thich":"Suối Lê-nin dưới chân núi Các Mác, Pác Bó – dòng suối bên phiến đá nơi Nguyễn Ái Quốc ngồi làm việc năm 1941. Ảnh chụp năm 2016.","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Lớp học giữa rừng","text":"Những lớp huấn luyện ở Pác Bó rất nhỏ. Học viên là thanh niên các dân tộc trong vùng và cán bộ từ các nơi về. Không có trường sở, lớp học diễn ra ở những chỗ kín đáo giữa núi rừng, người học vừa học vừa phải giữ bí mật tuyệt đối. Bài giảng được soạn ngắn gọn, dễ hiểu, gắn với thực tế của địa phương và với nhiệm vụ đánh Pháp, đuổi Nhật, giành độc lập cho dân tộc.\n\nNgười đặc biệt chú ý đến cách nói, cách viết sao cho đồng bào ít chữ cũng hiểu được. Những khái niệm lý luận trừu tượng được chuyển thành lời lẽ mộc mạc, ví dụ gần gũi với đời sống hằng ngày của đồng bào. Học xong, cán bộ trở về địa phương xây dựng các hội Cứu quốc. Việt Minh nhờ đó phát triển khắp Cao Bằng, rồi lan sang các tỉnh lân cận. Từ phiến đá bên suối, qua những lớp học nhỏ giữa rừng, tư tưởng được chuyển thành tổ chức, và tổ chức dần trở thành lực lượng.","doc":8},{"loai":"ban_co_biet","text":"Theo hồ sơ di tích của Cục Di sản văn hóa, suối Lê-nin không chỉ là nơi có bàn đá làm việc mà còn là nơi Người từng ngồi câu cá trong những ngày ở Pác Bó.","nguon_ten":"Cục Di sản văn hóa (Bộ Văn hóa, Thể thao và Du lịch) – “Di tích lịch sử Pác Bó”, https://dsvh.gov.vn/di-tich-lich-su-pac-bo-2950","doc":9},{"loai":"doan","tieu_de":"Chữ “chông chênh”","text":"Trong bài thơ “Tức cảnh Pác Bó”, câu thứ ba ghi lại chính công việc bên phiến đá: “Bàn đá chông chênh dịch sử Đảng”. Chữ “chông chênh” tả đúng dáng phiến đá không bằng phẳng, đặt giấy lên thì chênh vênh. Nó cũng gợi cả hoàn cảnh của người ngồi viết: giữa rừng sâu, thiếu thốn đủ bề, bên ngoài là sự lùng sục của kẻ thù. Toàn bài thơ và chữ “sang” ở câu kết được bàn riêng trong chuyên đề Lời Bác.\n\nĐiều đáng chú ý là cái chông chênh chỉ thuộc về phiến đá. Công việc đặt trên đó thì vững vàng, có mục đích rõ ràng và được theo đuổi đến cùng. Người không đợi có một văn phòng đàng hoàng mới làm việc, không đợi đủ sách vở mới dịch, không đợi phong trào lớn mạnh mới mở lớp. Tinh thần ấy khiến phiến đá bình thường trở thành biểu tượng: người cách mạng có thể làm việc ở bất cứ đâu, trong bất cứ hoàn cảnh nào, miễn là công việc có ích cho dân tộc.","doc":10},{"loai":"anh","src":"textures/bang_w/G12_9_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bàn đá bên suối Lê-nin”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Những văn phòng không có mái","text":"Phiến đá bên suối Lê-nin mở đầu cho một chuỗi những nơi làm việc giản dị trong cuộc đời Người. Sau hang Cốc Bó là lán Khuổi Nặm dựng bằng tre nứa nơi bìa rừng. Mùa hè năm 1945, ở Tân Trào, Người ở và làm việc trong lán Nà Lừa. Những năm kháng chiến chống thực dân Pháp, nơi làm việc của Người là những căn lán giữa núi rừng chiến khu Việt Bắc. Ngay cả khi đã về Thủ đô, từ tháng 5/1958, Người vẫn chọn ở và làm việc trong ngôi nhà sàn nhỏ bên ao cá trong khu Phủ Chủ tịch.\n\nĐặt cạnh nhau, những nơi ấy cho thấy một nếp sống nhất quán. Với Người, chỗ làm việc chỉ cần đủ ánh sáng để viết, đủ yên tĩnh để nghĩ, và gần gũi với thiên nhiên, với đồng bào. Phiến đá chông chênh bên suối Lê-nin là hình ảnh đầu tiên và mộc mạc nhất của nếp sống ấy trên đất Tổ quốc.","doc":11},{"loai":"anh","src":"textures/bang_w/G12_9_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bàn đá bên suối Lê-nin”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, phiến đá vẫn nằm bên bờ suối Lê-nin trong Khu di tích lịch sử Pác Bó, được giữ gìn như một hiện vật gốc giữa thiên nhiên. Men theo con đường ven suối từ khu hang Cốc Bó, khách tham quan có thể dừng lại bên “bàn đá chông chênh”, nhìn dòng nước trong chảy qua lòng cuội và ngọn núi Các Mác sừng sững phía sau. Đứng ở đó, người ta dễ hình dung dáng người gầy ngồi cúi mình trên trang giấy năm nào, bên tai là tiếng suối không ngừng.\n\nTrong gian trưng bày của Bảo tàng Hành trình 3D, cạnh bảng này có một cuốn sổ và một chồng sách. Đó là những đồ vật minh họa, gợi lại những trang bản dịch và tài liệu huấn luyện được viết giữa trời; bấm vào từng đồ vật để đọc câu chuyện của nó. Phiến đá thật ở Pác Bó vẫn mộc mạc như năm xưa, nhưng với nhiều thế hệ người Việt Nam, đó là một trong những chiếc bàn làm việc đáng nhớ nhất của lịch sử dân tộc.","doc":12},{"loai":"ban_co_biet","text":"Trong những năm ở vùng căn cứ Cao Bằng, Người còn biên soạn tài liệu quân sự cho các đội du kích, trong đó có cuốn “Cách đánh du kích”.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia; Hồ Chí Minh Toàn tập, tập 3, NXB Chính trị quốc gia, 2011","doc":13}],"nguon":["Hồ Chí Minh Toàn tập, tập 3, NXB Chính trị quốc gia, 2011 (Tức cảnh Pác Bó; các tài liệu viết ở Cao Bằng 1941 – 1945)","Hồ Chí Minh Toàn tập, tập 2, NXB Chính trị quốc gia, 2011 (Đường Kách mệnh)","Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","Cục Di sản văn hóa (Bộ Văn hóa, Thể thao và Du lịch) – “Di tích lịch sử Pác Bó”, https://dsvh.gov.vn/di-tich-lich-su-pac-bo-2950","Khu di tích lịch sử Pác Bó (Cao Bằng)"],"doc":[{"t":"“Bàn đá chông chênh”: văn phòng giữa trời bên suối Lê-nin. Không bàn ghế, không đèn, không mái che. Mỗi ngày, người đàn ông năm mươi tuổi mà bà con gọi là Già Thu ra ngồi bên một phiến đá cạnh suối, đặt giấy lên mặt đá gồ ghề và bắt đầu viết. Từ “văn phòng” giữa trời ấy, những trang sách lý luận được chuyển sang tiếng Việt, những tài liệu huấn luyện đầu tiên của vùng căn cứ ra đời."},{"t":"Một phiến đá, một dòng suối. Phiến đá nằm sát mép suối Lê-nin, cách cửa hang Cốc Bó không xa. Đó là một khối đá tự nhiên, mặt trên tương đối phẳng nhưng vẫn gồ ghề, mấp mô. Đặt giấy bút lên thì chênh vênh, ngồi lâu thì mỏi, đúng như chữ “chông chênh” mà Người sau này đưa vào thơ. Trước mặt là dòng suối nước trong xanh chảy trên lòng cuội, sau lưng là vách núi đá vôi mà Người đặt tên là núi Các Mác. Chẳng ai dựng nên chiếc bàn ấy. Nó có sẵn ở đó từ bao đời, như trăm nghìn tảng đá khác dọc con suối đầu nguồn. Chỉ đến mùa xuân năm 1941, khi một người khách lạ chọn nó làm chỗ ngồi viết mỗi ngày, phiến đá mới có tên gọi riêng. Người dân quanh vùng và khách thập phương về sau quen gọi nó là “bàn đá chông chênh”. Một vật vô tri của núi rừng đã trở thành di tích, chỉ vì nó từng nâng đỡ những trang giấy làm nên lịch sử. Câu chuyện của phiến đá vì thế cũng là câu chuyện về cách làm việc của Người trong những ngày đầu trở về."},{"t":"Vì sao phải ra bờ suối?. Câu thơ “Sáng ra bờ suối, tối vào hang” ghi lại nhịp sống đều đặn của Người ở Pác Bó. Lý do đầu tiên của nhịp sống ấy rất giản dị: trong hang tối, ánh sáng ban ngày chỉ hắt vào từ cửa hang hẹp. Muốn đọc sách, dịch sách, viết tài liệu trong nhiều giờ liền, phải ra chỗ sáng. Bờ suối trước hang là nơi gần nhất có đủ ánh sáng, lại thoáng đãng, khô ráo hơn lòng hang ẩm lạnh. Ngồi bên suối, Người vẫn ở trong vùng được bảo vệ, cách hang chỉ vài bước chân. Đồng bào và anh em cán bộ canh gác các lối vào thung lũng. Như vậy, phiến đá vừa là chỗ làm việc, vừa nằm trong vòng an toàn của căn cứ nhỏ ở đầu nguồn. Ngày làm việc ngoài trời, tối về hang nghỉ và tiếp tục công việc bên bếp lửa. Nhịp ấy lặp đi lặp lại suốt những tuần Người ở hang Cốc Bó, bền bỉ như tiếng suối chảy không ngừng ngay bên cạnh."},{"t":"Cuốn sách được dịch trên mặt đá. Công việc được nhắc tới trong câu thơ “Bàn đá chông chênh dịch sử Đảng” là việc dịch cuốn Lịch sử Đảng Cộng sản (b) Liên Xô sang tiếng Việt. Đây là cuốn giáo trình tóm tắt xuất bản ở Liên Xô năm 1938. Sách kể lại chặng đường của những người cộng sản Nga, từ các nhóm mác-xít đầu tiên cuối thế kỷ XIX, qua cuộc cách mạng năm 1905, Cách mạng Tháng Mười năm 1917, đến công cuộc xây dựng chủ nghĩa xã hội ở Liên Xô. Với những người cách mạng Việt Nam năm 1941, cuốn sách chứa đựng nhiều kinh nghiệm quý. Đó là kinh nghiệm xây dựng một đảng cách mạng trong điều kiện hoạt động bí mật, kinh nghiệm kết hợp các hình thức đấu tranh, kinh nghiệm chuẩn bị lực lượng và chớp thời cơ giành chính quyền. Người dịch sách để làm tài liệu huấn luyện cán bộ, giúp những người cách mạng trẻ ở vùng căn cứ học tập cách xây dựng Đảng và lãnh đạo cách mạng. Trên mặt đá gồ ghề, từng trang sách lý luận dày đặc được chuyển thành tiếng Việt để cán bộ có thể đọc, học và làm theo."},{"t":"Đảng muốn vững thì phải có chủ nghĩa làm cốt, trong đảng ai cũng phải hiểu, ai cũng phải theo chủ nghĩa ấy. Đảng mà không có chủ nghĩa cũng như người không có trí khôn, tàu không có bàn chỉ nam. — Nguyễn Ái Quốc"},{"t":"Lý luận cho những người đi đầu. Việc dịch sách lý luận giữa rừng không phải một ý thích bất chợt. Từ năm 1925 – 1927, ở Quảng Châu, Nguyễn Ái Quốc đã trực tiếp mở các lớp huấn luyện cho thanh niên Việt Nam. Những bài giảng ở đó được tập hợp thành cuốn Đường Kách mệnh, trong đó Người khẳng định đảng cách mạng phải có chủ nghĩa làm cốt. Mười bốn năm sau, trở về Pác Bó, Người lại bắt đầu từ chính việc ấy: đào tạo con người trước khi phát động phong trào. Nhu cầu ấy càng cấp thiết vào năm 1941. Sau những đợt khủng bố những năm 1939 – 1940, nhiều cán bộ cốt cán bị bắt, bị giết, nhiều cơ sở tan vỡ. Phong trào cần một lớp cán bộ mới, phần đông là thanh niên các dân tộc ở vùng căn cứ, nhiệt tình nhưng chưa được học tập bài bản. Những trang dịch trên bàn đá chính là giáo trình cho lớp người ấy. Họ sẽ là những người đi đầu trong việc xây dựng các hội Cứu quốc, tổ chức du kích và chuẩn bị cho ngày khởi nghĩa."},{"t":"Bạn có biết? Chữ “(b)” trong tên cuốn Lịch sử Đảng Cộng sản (b) Liên Xô là viết tắt của “bôn-sê-vích”, tên gọi của phái đa số trong Đảng Công nhân Dân chủ Xã hội Nga do Lê-nin đứng đầu. Nguyên bản là giáo trình tóm tắt xuất bản ở Liên Xô năm 1938."},{"t":"Không chỉ một cuốn sách. Bản dịch “sử Đảng” chỉ là một phần trong khối lượng công việc đồ sộ của Người ở vùng căn cứ Cao Bằng. Người soạn tài liệu, viết bài và chuẩn bị nội dung cho các lớp huấn luyện cán bộ mở ngay tại Pác Bó. Người viết nhiều bài ca vận động bằng thơ lục bát cho đồng bào dễ thuộc, dễ nhớ, trong đó có bài diễn ca “Lịch sử nước ta” (xem chuyên đề “Lịch sử nước ta” và dự báo năm 1945). Người còn biên soạn tài liệu quân sự cho các đội du kích. Ngày 1/8/1941, tờ báo Việt Nam độc lập do Người sáng lập ra số đầu tiên, làm cơ quan tuyên truyền của Việt Minh tỉnh Cao Bằng. Báo viết ngắn, dễ hiểu, nhiều bài bằng văn vần. Không phải mọi trang viết ấy đều ra đời trên phiến đá bên suối, bởi sau hang Cốc Bó Người còn ở và làm việc ở nhiều nơi khác trong vùng. Nhưng phiến đá là nơi mở đầu, là hình ảnh tượng trưng cho cả một thời kỳ Người dùng ngòi bút để chuẩn bị cho cách mạng."},{"t":"Lớp học giữa rừng. Những lớp huấn luyện ở Pác Bó rất nhỏ. Học viên là thanh niên các dân tộc trong vùng và cán bộ từ các nơi về. Không có trường sở, lớp học diễn ra ở những chỗ kín đáo giữa núi rừng, người học vừa học vừa phải giữ bí mật tuyệt đối. Bài giảng được soạn ngắn gọn, dễ hiểu, gắn với thực tế của địa phương và với nhiệm vụ đánh Pháp, đuổi Nhật, giành độc lập cho dân tộc. Người đặc biệt chú ý đến cách nói, cách viết sao cho đồng bào ít chữ cũng hiểu được. Những khái niệm lý luận trừu tượng được chuyển thành lời lẽ mộc mạc, ví dụ gần gũi với đời sống hằng ngày của đồng bào. Học xong, cán bộ trở về địa phương xây dựng các hội Cứu quốc. Việt Minh nhờ đó phát triển khắp Cao Bằng, rồi lan sang các tỉnh lân cận. Từ phiến đá bên suối, qua những lớp học nhỏ giữa rừng, tư tưởng được chuyển thành tổ chức, và tổ chức dần trở thành lực lượng."},{"t":"Bạn có biết? Theo hồ sơ di tích của Cục Di sản văn hóa, suối Lê-nin không chỉ là nơi có bàn đá làm việc mà còn là nơi Người từng ngồi câu cá trong những ngày ở Pác Bó."},{"t":"Chữ “chông chênh”. Trong bài thơ “Tức cảnh Pác Bó”, câu thứ ba ghi lại chính công việc bên phiến đá: “Bàn đá chông chênh dịch sử Đảng”. Chữ “chông chênh” tả đúng dáng phiến đá không bằng phẳng, đặt giấy lên thì chênh vênh. Nó cũng gợi cả hoàn cảnh của người ngồi viết: giữa rừng sâu, thiếu thốn đủ bề, bên ngoài là sự lùng sục của kẻ thù. Toàn bài thơ và chữ “sang” ở câu kết được bàn riêng trong chuyên đề Lời Bác. Điều đáng chú ý là cái chông chênh chỉ thuộc về phiến đá. Công việc đặt trên đó thì vững vàng, có mục đích rõ ràng và được theo đuổi đến cùng. Người không đợi có một văn phòng đàng hoàng mới làm việc, không đợi đủ sách vở mới dịch, không đợi phong trào lớn mạnh mới mở lớp. Tinh thần ấy khiến phiến đá bình thường trở thành biểu tượng: người cách mạng có thể làm việc ở bất cứ đâu, trong bất cứ hoàn cảnh nào, miễn là công việc có ích cho dân tộc."},{"t":"Những văn phòng không có mái. Phiến đá bên suối Lê-nin mở đầu cho một chuỗi những nơi làm việc giản dị trong cuộc đời Người. Sau hang Cốc Bó là lán Khuổi Nặm dựng bằng tre nứa nơi bìa rừng. Mùa hè năm 1945, ở Tân Trào, Người ở và làm việc trong lán Nà Lừa. Những năm kháng chiến chống thực dân Pháp, nơi làm việc của Người là những căn lán giữa núi rừng chiến khu Việt Bắc. Ngay cả khi đã về Thủ đô, từ tháng 5/1958, Người vẫn chọn ở và làm việc trong ngôi nhà sàn nhỏ bên ao cá trong khu Phủ Chủ tịch. Đặt cạnh nhau, những nơi ấy cho thấy một nếp sống nhất quán. Với Người, chỗ làm việc chỉ cần đủ ánh sáng để viết, đủ yên tĩnh để nghĩ, và gần gũi với thiên nhiên, với đồng bào. Phiến đá chông chênh bên suối Lê-nin là hình ảnh đầu tiên và mộc mạc nhất của nếp sống ấy trên đất Tổ quốc."},{"t":"Dấu tích hôm nay. Ngày nay, phiến đá vẫn nằm bên bờ suối Lê-nin trong Khu di tích lịch sử Pác Bó, được giữ gìn như một hiện vật gốc giữa thiên nhiên. Men theo con đường ven suối từ khu hang Cốc Bó, khách tham quan có thể dừng lại bên “bàn đá chông chênh”, nhìn dòng nước trong chảy qua lòng cuội và ngọn núi Các Mác sừng sững phía sau. Đứng ở đó, người ta dễ hình dung dáng người gầy ngồi cúi mình trên trang giấy năm nào, bên tai là tiếng suối không ngừng. Trong gian trưng bày của Bảo tàng Hành trình 3D, cạnh bảng này có một cuốn sổ và một chồng sách. Đó là những đồ vật minh họa, gợi lại những trang bản dịch và tài liệu huấn luyện được viết giữa trời; bấm vào từng đồ vật để đọc câu chuyện của nó. Phiến đá thật ở Pác Bó vẫn mộc mạc như năm xưa, nhưng với nhiều thế hệ người Việt Nam, đó là một trong những chiếc bàn làm việc đáng nhớ nhất của lịch sử dân tộc."},{"t":"Bạn có biết? Trong những năm ở vùng căn cứ Cao Bằng, Người còn biên soạn tài liệu quân sự cho các đội du kích, trong đó có cuốn “Cách đánh du kích”."}],"so_chu":1921},{"i":10,"tieu_de_bang":"Lán Khuổi Nặm","tieu_de":"Lán Khuổi Nặm, tháng 5/1941: căn nhà sàn mười hai mét vuông nơi Mặt trận Việt Minh ra đời","sapo":"Căn lán chỉ rộng chừng mười hai mét vuông, chia làm hai gian nhỏ, nép ngay bìa rừng. Từ bên ngoài nhìn vào không thấy, nhưng từ trong nhìn ra thì rõ mọi lối đi. Trong mười ngày tháng 5/1941, dưới mái lán ấy, Hội nghị Trung ương lần thứ tám do Nguyễn Ái Quốc chủ trì đã đưa ra những quyết định làm xoay chuyển vận mệnh dân tộc.","bia":{"src":"textures/bai/G12_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Căn lán nơi bìa rừng","text":"Lán Khuổi Nặm được dựng theo kiểu nhà sàn của đồng bào dân tộc, vật liệu là tre nứa, mái lợp lá. Theo hồ sơ di tích của Cục Di sản văn hóa, lán có hai gian nhỏ, tổng diện tích chỉ khoảng mười hai mét vuông. Sàn lán nâng cao khỏi mặt đất ẩm của rừng, gần đó là con suối nhỏ mang tên Khuổi Nặm.\n\nVị trí của căn lán được chọn rất kỹ. Lán nằm ngay bìa rừng, hoàn toàn kín đáo: người ở ngoài nhìn vào không thấy, còn người ở trong thì quan sát rõ mọi lối đi phía trước. Khi có động, từ lán có thể rút qua suối Khuổi Nặm sang phía biên giới Trung Quốc một cách an toàn. Một căn nhà nhỏ bé, mộc mạc như hàng nghìn căn lán nương của đồng bào vùng cao, nhưng mỗi chi tiết đều được tính toán cho một cuộc sống bí mật. Theo hồ sơ di tích, đây là nơi Người ở lâu nhất trong thời gian hoạt động ở vùng Pác Bó.","doc":1},{"loai":"doan","tieu_de":"Từ hang đá sang căn lán","text":"Những tuần đầu về nước, Người ở hang Cốc Bó, rồi cuối tháng 3/1941 chuyển sang hang Lũng Lạn (xem chuyên đề “Hang Cốc Bó”). Khi địch lùng sục gắt gao, Người rời hang đá sang ở và làm việc tại lán Khuổi Nặm. Căn lán sàn tránh được hơi ẩm lạnh của lòng hang, thuận tiện hơn cho việc đọc, viết và tiếp cán bộ.\n\nTừ căn lán này, Người tiếp tục dịch sách, soạn tài liệu, mở lớp huấn luyện cán bộ và gấp rút chuẩn bị cho một sự kiện hệ trọng: triệu tập Hội nghị Ban Chấp hành Trung ương Đảng. Căn lán hai gian ở bìa rừng Khuổi Nặm, kín đáo và có đường rút an toàn, đã trở thành nơi họp của hội nghị ấy. Triệu tập một hội nghị như vậy giữa vòng vây của địch đòi hỏi sự chuẩn bị kỹ lưỡng. Phải báo tin cho các đồng chí ở nhiều nơi, tổ chức đường dây đón đưa, bố trí người canh gác và chuẩn bị tài liệu cho các phiên họp.","doc":2},{"loai":"anh","src":"textures/bang_w/G12_10_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lán Khuổi Nặm”, nhìn từ xa."},{"loai":"doan","tieu_de":"Thời thế trước giờ hội nghị","text":"Mùa xuân năm 1941, Chiến tranh thế giới thứ hai đã bước sang năm thứ ba. Phát xít Đức chiếm phần lớn châu Âu, nước Pháp đầu hàng từ tháng 6/1940. Ở Đông Dương, từ tháng 9/1940, quân Nhật kéo vào, thực dân Pháp cúi đầu hợp tác với Nhật để cùng bóc lột nhân dân ta. Đời sống các tầng lớp nhân dân ngày càng cực khổ, lòng căm thù Pháp – Nhật dâng cao.\n\nTrước đó, Hội nghị Trung ương tháng 11/1939 và tháng 11/1940 đã bắt đầu chuyển hướng chỉ đạo chiến lược, tạm gác khẩu hiệu cách mạng ruộng đất, đưa nhiệm vụ chống đế quốc lên hàng đầu. Nhưng những cuộc khởi nghĩa Bắc Sơn, Nam Kỳ bị đàn áp, nhiều cán bộ lãnh đạo bị bắt, phong trào cần một đường lối hoàn chỉnh và thống nhất. Hội nghị ở Khuổi Nặm được triệu tập đúng vào lúc ấy, để hoàn chỉnh sự chuyển hướng, trả lời câu hỏi lớn nhất của thời cuộc: làm thế nào để giành lại độc lập cho dân tộc.","doc":3},{"loai":"ban_co_biet","text":"Hội nghị Trung ương lần thứ tám đã bầu Ban Chấp hành Trung ương mới và cử đồng chí Trường Chinh làm Tổng Bí thư của Đảng.","nguon_ten":"Văn kiện Đảng toàn tập, tập 7 (1940 – 1945), NXB Chính trị quốc gia – Nghị quyết Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng Cộng sản Đông Dương (5/1941)","doc":4},{"loai":"doan","tieu_de":"Mười ngày dưới mái lán","text":"Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng Cộng sản Đông Dương họp từ ngày 10 đến ngày 19/5/1941. Nguyễn Ái Quốc triệu tập và chủ trì hội nghị với tư cách đại diện Quốc tế Cộng sản. Dự hội nghị có các đồng chí Trường Chinh, Hoàng Văn Thụ, Hoàng Quốc Việt, Phùng Chí Kiên, cùng đại biểu một số xứ ủy và tổ chức Đảng hoạt động ở nước ngoài.\n\nĐể đến được Khuổi Nặm, các đại biểu từ trong nước phải theo những đường dây liên lạc bí mật, vượt qua vùng địch kiểm soát mới lên tới vùng biên giới. Căn lán mười hai mét vuông trở thành phòng họp suốt mười ngày, việc canh gác, bảo vệ hội nghị được giữ hết sức nghiêm ngặt. Trong không gian chật hẹp ấy, những người cộng sản Việt Nam phân tích tình hình thế giới, trong nước và đi đến những quyết định có ý nghĩa bước ngoặt đối với cách mạng Việt Nam.","doc":5},{"loai":"anh","src":"textures/bai/G12_v1.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện gian Pác Bó – Cao Bằng, nhìn từ trên cao.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Đặt giải phóng dân tộc lên trên hết","text":"Quyết định quan trọng nhất của Hội nghị là đặt nhiệm vụ giải phóng dân tộc lên hàng đầu. Hội nghị nhận định: lúc này, quyền lợi của cả dân tộc phải đặt lên trên hết. Nếu không giải phóng được dân tộc thì quyền lợi của bộ phận, giai cấp nào cũng không đòi lại được. Vì vậy, Hội nghị tiếp tục tạm gác khẩu hiệu cách mạng ruộng đất, chỉ nêu khẩu hiệu tịch thu ruộng đất của đế quốc và Việt gian chia cho dân cày nghèo, giảm tô, giảm tức.\n\nĐây là một sự lựa chọn đầy bản lĩnh. Nó cho phép tập hợp mọi tầng lớp người Việt Nam yêu nước, từ công nhân, nông dân đến trí thức, tiểu thương, cả những địa chủ còn lòng yêu nước, vào một khối đoàn kết chung. Kẻ thù được xác định rõ là đế quốc Pháp – Nhật và bọn tay sai. Tư tưởng đặt độc lập dân tộc lên trên hết, mà Nguyễn Ái Quốc theo đuổi từ những năm 1920, nay trở thành đường lối chính thức của cả Đảng.","doc":6},{"loai":"trich","text":"Trong lúc này quyền lợi của bộ phận, của giai cấp phải đặt dưới sự sinh tử, tồn vong của quốc gia, của dân tộc. Trong lúc này nếu không giải quyết được vấn đề dân tộc giải phóng, không đòi được độc lập, tự do cho toàn thể dân tộc, thì chẳng những toàn thể quốc gia dân tộc còn chịu mãi kiếp ngựa trâu, mà quyền lợi của bộ phận, giai cấp đến vạn năm cũng không đòi lại được.","nguoi":"Nghị quyết Hội nghị Trung ương lần thứ tám (5/1941)","nguon_ten":"Văn kiện Đảng toàn tập, tập 7 (1940 – 1945), NXB Chính trị quốc gia – Nghị quyết Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng Cộng sản Đông Dương (5/1941)","doc":7},{"loai":"doan","tieu_de":"Việt Minh ra đời","text":"Hội nghị chủ trương giải quyết vấn đề dân tộc trong khuôn khổ từng nước ở Đông Dương. Ở Việt Nam, Hội nghị quyết định thành lập Việt Nam Độc lập Đồng minh, gọi tắt là Việt Minh. Ở Lào và Cam-pu-chia, chủ trương lập những mặt trận riêng của từng nước. Việt Minh chính thức ra đời ngày 19/5/1941, ngày bế mạc hội nghị, cũng là ngày sinh lần thứ năm mươi mốt của Nguyễn Ái Quốc.\n\nViệt Minh tập hợp mọi người Việt Nam yêu nước, không phân biệt giai cấp, tôn giáo, đảng phái. Họ được tổ chức vào các đoàn thể mang tên Cứu quốc: Công nhân cứu quốc, Nông dân cứu quốc, Thanh niên cứu quốc, Phụ nữ cứu quốc và nhiều hội khác. Cái tên “cứu quốc” nói rõ mục đích chung vượt lên mọi khác biệt. Từ Cao Bằng, các hội Cứu quốc lan dần sang các tỉnh Việt Bắc, rồi về đồng bằng và thành thị. Chỉ bốn năm sau, Việt Minh trở thành lực lượng lãnh đạo toàn dân đứng lên giành chính quyền.","doc":8},{"loai":"ban_co_biet","text":"Nghị quyết Hội nghị Trung ương lần thứ tám đã nêu rõ: sau khi đánh đuổi Pháp – Nhật sẽ thành lập nước Việt Nam Dân chủ Cộng hòa. Bốn năm sau, ngày 2/9/1945, đó chính là tên của nhà nước mới được Chủ tịch Hồ Chí Minh tuyên bố khai sinh.","nguon_ten":"Văn kiện Đảng toàn tập, tập 7 (1940 – 1945), NXB Chính trị quốc gia – Nghị quyết Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng Cộng sản Đông Dương (5/1941)","doc":9},{"loai":"doan","tieu_de":"Chuẩn bị khởi nghĩa là nhiệm vụ trung tâm","text":"Hội nghị xác định chuẩn bị khởi nghĩa vũ trang là nhiệm vụ trung tâm của Đảng và nhân dân trong giai đoạn này. Hội nghị dự kiến con đường giành chính quyền: đi từ khởi nghĩa từng phần ở từng địa phương, tiến lên tổng khởi nghĩa khi thời cơ đến. Muốn vậy, phải xây dựng lực lượng chính trị của quần chúng, xây dựng lực lượng vũ trang và các căn cứ địa cách mạng.\n\nNhững chủ trương ấy biến căn lán nhỏ thành điểm xuất phát của cả một kế hoạch dài hơi. Căn cứ Cao Bằng và căn cứ Bắc Sơn – Võ Nhai được củng cố, các đội du kích được duy trì và phát triển. Cán bộ được đào tạo để chuẩn bị cho ngày khởi nghĩa. Bốn năm sau, khi phát xít Nhật đầu hàng Đồng minh tháng 8/1945, toàn dân tộc đã sẵn sàng. Cách mạng Tháng Tám diễn ra đúng theo hình thái mà Hội nghị ở Khuổi Nặm đã dự kiến: từ khởi nghĩa từng phần tiến lên tổng khởi nghĩa.","doc":10},{"loai":"anh","src":"textures/bang_w/G12_10_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lán Khuổi Nặm”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Lời kêu gọi từ vùng đầu nguồn","text":"Ít ngày sau hội nghị, ngày 6/6/1941, Nguyễn Ái Quốc viết thư “Kính cáo đồng bào”, kêu gọi toàn dân đoàn kết đánh Pháp, đuổi Nhật. Bức thư vạch rõ cảnh nhân dân ta bị cả thực dân Pháp và phát xít Nhật áp bức, bóc lột. Lời lẽ giản dị mà thống thiết, hướng tới mọi tầng lớp đồng bào, từ các bậc phụ huynh, các nhà trí thức, đến người lao động và binh lính.\n\nBức thư đưa tinh thần của Hội nghị Trung ương lần thứ tám đến với quần chúng bằng ngôn ngữ của trái tim. Nó biến một nghị quyết của Đảng thành lời hiệu triệu của cả dân tộc, mời gọi mỗi người Việt Nam góp phần mình vào sự nghiệp chung. Bức thư được ký tên Nguyễn Ái Quốc, cái tên mà nhiều người yêu nước đã biết đến từ bản Yêu sách của nhân dân An Nam gửi Hội nghị Véc-xai năm 1919. Sau nhiều năm, cái tên ấy lại vang lên trong một lời kêu gọi gửi thẳng tới đồng bào trong nước.","doc":11},{"loai":"trich","text":"Việc cứu quốc là việc chung. Ai là người Việt Nam đều phải kề vai gánh vác một phần trách nhiệm: người có tiền góp tiền, người có của góp của, người có sức góp sức, người có tài năng góp tài năng.","nguoi":"Nguyễn Ái Quốc","nguon_ten":"Thư “Kính cáo đồng bào”, 6/6/1941 – Hồ Chí Minh Toàn tập, tập 3, NXB Chính trị quốc gia, 2011","doc":12},{"loai":"doan","tieu_de":"Những người trong căn lán","text":"Số phận những người dự hội nghị năm ấy gắn liền với những năm tháng khốc liệt nhất của cách mạng. Đồng chí Phùng Chí Kiên hy sinh ngay trong năm 1941. Đồng chí Hoàng Văn Thụ bị địch bắt và hy sinh năm 1944, khi Cách mạng Tháng Tám chỉ còn cách hơn một năm. Đồng chí Trường Chinh, Tổng Bí thư được bầu tại Khuổi Nặm, cùng đồng chí Hoàng Quốc Việt tiếp tục lãnh đạo phong trào trong nước đến ngày Tổng khởi nghĩa.\n\nCòn Nguyễn Ái Quốc tiếp tục ở lại vùng căn cứ, xây dựng phong trào ở Cao Bằng. Ngày 1/8/1941, tờ báo Việt Nam độc lập do Người sáng lập ra số đầu tiên. Tháng 8/1942, Người lên đường sang Trung Quốc với tên Hồ Chí Minh, mở ra một chặng đường mới được kể trong chuyên đề Mốc thời gian. Căn lán nhỏ ở bìa rừng Khuổi Nặm, vì thế, là nơi hội tụ của những con người đã dâng hiến cả cuộc đời cho độc lập dân tộc.","doc":13},{"loai":"anh","src":"textures/bang_w/G12_10_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lán Khuổi Nặm”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, lán Khuổi Nặm là một điểm quan trọng trong Khu di tích quốc gia đặc biệt Pác Bó. Khách tham quan theo lối mòn vào bìa rừng sẽ gặp căn lán sàn hai gian nhỏ nép dưới tán cây, gần dòng suối Khuổi Nặm. Nhìn căn lán tận mắt, có thể hiểu vì sao nơi này được chọn: lán gần như khuất hẳn giữa rừng cây, trong khi từ lán lại nhìn rõ các lối đi phía trước.\n\nTrong gian trưng bày của Bảo tàng Hành trình 3D, góc lán Khuổi Nặm có một chiếc bàn nhỏ và một ngọn đèn dầu. Đó là những đồ vật minh họa, gợi lại khung cảnh giản dị của hội nghị năm 1941 và những đêm làm việc trong lán; bấm vào từng đồ vật để đọc câu chuyện của nó. Căn lán mười hai mét vuông nhắc người hôm nay rằng những quyết định lớn nhất của một dân tộc không cần đến những hội trường lộng lẫy, mà cần tầm nhìn, sự đồng lòng và niềm tin vào sức mạnh của nhân dân.","doc":14},{"loai":"ban_co_biet","text":"Theo hồ sơ di tích, trong quần thể Pác Bó, lán Khuổi Nặm là nơi Người ở lâu nhất. Thời gian ấy dài hơn cả ở hang Cốc Bó, hang Lũng Lạn hay nhà ông Lý Quốc Súng, nơi Người ở mười một ngày đầu tiên sau khi về nước.","nguon_ten":"Cục Di sản văn hóa (Bộ Văn hóa, Thể thao và Du lịch) – “Di tích lịch sử Pác Bó”, https://dsvh.gov.vn/di-tich-lich-su-pac-bo-2950","doc":15}],"nguon":["Văn kiện Đảng toàn tập, tập 7 (1940 – 1945), NXB Chính trị quốc gia – Nghị quyết Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng Cộng sản Đông Dương (5/1941)","Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, tập 3, NXB Chính trị quốc gia, 2011 (Kính cáo đồng bào, 6/6/1941)","Cục Di sản văn hóa (Bộ Văn hóa, Thể thao và Du lịch) – “Di tích lịch sử Pác Bó”, https://dsvh.gov.vn/di-tich-lich-su-pac-bo-2950","Bảo tàng Hồ Chí Minh","Khu di tích lịch sử Pác Bó (Cao Bằng)"],"doc":[{"t":"Lán Khuổi Nặm, tháng 5/1941: căn nhà sàn mười hai mét vuông nơi Mặt trận Việt Minh ra đời. Căn lán chỉ rộng chừng mười hai mét vuông, chia làm hai gian nhỏ, nép ngay bìa rừng. Từ bên ngoài nhìn vào không thấy, nhưng từ trong nhìn ra thì rõ mọi lối đi. Trong mười ngày tháng 5/1941, dưới mái lán ấy, Hội nghị Trung ương lần thứ tám do Nguyễn Ái Quốc chủ trì đã đưa ra những quyết định làm xoay chuyển vận mệnh dân tộc."},{"t":"Căn lán nơi bìa rừng. Lán Khuổi Nặm được dựng theo kiểu nhà sàn của đồng bào dân tộc, vật liệu là tre nứa, mái lợp lá. Theo hồ sơ di tích của Cục Di sản văn hóa, lán có hai gian nhỏ, tổng diện tích chỉ khoảng mười hai mét vuông. Sàn lán nâng cao khỏi mặt đất ẩm của rừng, gần đó là con suối nhỏ mang tên Khuổi Nặm. Vị trí của căn lán được chọn rất kỹ. Lán nằm ngay bìa rừng, hoàn toàn kín đáo: người ở ngoài nhìn vào không thấy, còn người ở trong thì quan sát rõ mọi lối đi phía trước. Khi có động, từ lán có thể rút qua suối Khuổi Nặm sang phía biên giới Trung Quốc một cách an toàn. Một căn nhà nhỏ bé, mộc mạc như hàng nghìn căn lán nương của đồng bào vùng cao, nhưng mỗi chi tiết đều được tính toán cho một cuộc sống bí mật. Theo hồ sơ di tích, đây là nơi Người ở lâu nhất trong thời gian hoạt động ở vùng Pác Bó."},{"t":"Từ hang đá sang căn lán. Những tuần đầu về nước, Người ở hang Cốc Bó, rồi cuối tháng 3/1941 chuyển sang hang Lũng Lạn (xem chuyên đề “Hang Cốc Bó”). Khi địch lùng sục gắt gao, Người rời hang đá sang ở và làm việc tại lán Khuổi Nặm. Căn lán sàn tránh được hơi ẩm lạnh của lòng hang, thuận tiện hơn cho việc đọc, viết và tiếp cán bộ. Từ căn lán này, Người tiếp tục dịch sách, soạn tài liệu, mở lớp huấn luyện cán bộ và gấp rút chuẩn bị cho một sự kiện hệ trọng: triệu tập Hội nghị Ban Chấp hành Trung ương Đảng. Căn lán hai gian ở bìa rừng Khuổi Nặm, kín đáo và có đường rút an toàn, đã trở thành nơi họp của hội nghị ấy. Triệu tập một hội nghị như vậy giữa vòng vây của địch đòi hỏi sự chuẩn bị kỹ lưỡng. Phải báo tin cho các đồng chí ở nhiều nơi, tổ chức đường dây đón đưa, bố trí người canh gác và chuẩn bị tài liệu cho các phiên họp."},{"t":"Thời thế trước giờ hội nghị. Mùa xuân năm 1941, Chiến tranh thế giới thứ hai đã bước sang năm thứ ba. Phát xít Đức chiếm phần lớn châu Âu, nước Pháp đầu hàng từ tháng 6/1940. Ở Đông Dương, từ tháng 9/1940, quân Nhật kéo vào, thực dân Pháp cúi đầu hợp tác với Nhật để cùng bóc lột nhân dân ta. Đời sống các tầng lớp nhân dân ngày càng cực khổ, lòng căm thù Pháp – Nhật dâng cao. Trước đó, Hội nghị Trung ương tháng 11/1939 và tháng 11/1940 đã bắt đầu chuyển hướng chỉ đạo chiến lược, tạm gác khẩu hiệu cách mạng ruộng đất, đưa nhiệm vụ chống đế quốc lên hàng đầu. Nhưng những cuộc khởi nghĩa Bắc Sơn, Nam Kỳ bị đàn áp, nhiều cán bộ lãnh đạo bị bắt, phong trào cần một đường lối hoàn chỉnh và thống nhất. Hội nghị ở Khuổi Nặm được triệu tập đúng vào lúc ấy, để hoàn chỉnh sự chuyển hướng, trả lời câu hỏi lớn nhất của thời cuộc: làm thế nào để giành lại độc lập cho dân tộc."},{"t":"Bạn có biết? Hội nghị Trung ương lần thứ tám đã bầu Ban Chấp hành Trung ương mới và cử đồng chí Trường Chinh làm Tổng Bí thư của Đảng."},{"t":"Mười ngày dưới mái lán. Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng Cộng sản Đông Dương họp từ ngày 10 đến ngày 19/5/1941. Nguyễn Ái Quốc triệu tập và chủ trì hội nghị với tư cách đại diện Quốc tế Cộng sản. Dự hội nghị có các đồng chí Trường Chinh, Hoàng Văn Thụ, Hoàng Quốc Việt, Phùng Chí Kiên, cùng đại biểu một số xứ ủy và tổ chức Đảng hoạt động ở nước ngoài. Để đến được Khuổi Nặm, các đại biểu từ trong nước phải theo những đường dây liên lạc bí mật, vượt qua vùng địch kiểm soát mới lên tới vùng biên giới. Căn lán mười hai mét vuông trở thành phòng họp suốt mười ngày, việc canh gác, bảo vệ hội nghị được giữ hết sức nghiêm ngặt. Trong không gian chật hẹp ấy, những người cộng sản Việt Nam phân tích tình hình thế giới, trong nước và đi đến những quyết định có ý nghĩa bước ngoặt đối với cách mạng Việt Nam."},{"t":"Đặt giải phóng dân tộc lên trên hết. Quyết định quan trọng nhất của Hội nghị là đặt nhiệm vụ giải phóng dân tộc lên hàng đầu. Hội nghị nhận định: lúc này, quyền lợi của cả dân tộc phải đặt lên trên hết. Nếu không giải phóng được dân tộc thì quyền lợi của bộ phận, giai cấp nào cũng không đòi lại được. Vì vậy, Hội nghị tiếp tục tạm gác khẩu hiệu cách mạng ruộng đất, chỉ nêu khẩu hiệu tịch thu ruộng đất của đế quốc và Việt gian chia cho dân cày nghèo, giảm tô, giảm tức. Đây là một sự lựa chọn đầy bản lĩnh. Nó cho phép tập hợp mọi tầng lớp người Việt Nam yêu nước, từ công nhân, nông dân đến trí thức, tiểu thương, cả những địa chủ còn lòng yêu nước, vào một khối đoàn kết chung. Kẻ thù được xác định rõ là đế quốc Pháp – Nhật và bọn tay sai. Tư tưởng đặt độc lập dân tộc lên trên hết, mà Nguyễn Ái Quốc theo đuổi từ những năm 1920, nay trở thành đường lối chính thức của cả Đảng."},{"t":"Trong lúc này quyền lợi của bộ phận, của giai cấp phải đặt dưới sự sinh tử, tồn vong của quốc gia, của dân tộc. Trong lúc này nếu không giải quyết được vấn đề dân tộc giải phóng, không đòi được độc lập, tự do cho toàn thể dân tộc, thì chẳng những toàn thể quốc gia dân tộc còn chịu mãi kiếp ngựa trâu, mà quyền lợi của bộ phận, giai cấp đến vạn năm cũng không đòi lại được. — Nghị quyết Hội nghị Trung ương lần thứ tám (5/1941)"},{"t":"Việt Minh ra đời. Hội nghị chủ trương giải quyết vấn đề dân tộc trong khuôn khổ từng nước ở Đông Dương. Ở Việt Nam, Hội nghị quyết định thành lập Việt Nam Độc lập Đồng minh, gọi tắt là Việt Minh. Ở Lào và Cam-pu-chia, chủ trương lập những mặt trận riêng của từng nước. Việt Minh chính thức ra đời ngày 19/5/1941, ngày bế mạc hội nghị, cũng là ngày sinh lần thứ năm mươi mốt của Nguyễn Ái Quốc. Việt Minh tập hợp mọi người Việt Nam yêu nước, không phân biệt giai cấp, tôn giáo, đảng phái. Họ được tổ chức vào các đoàn thể mang tên Cứu quốc: Công nhân cứu quốc, Nông dân cứu quốc, Thanh niên cứu quốc, Phụ nữ cứu quốc và nhiều hội khác. Cái tên “cứu quốc” nói rõ mục đích chung vượt lên mọi khác biệt. Từ Cao Bằng, các hội Cứu quốc lan dần sang các tỉnh Việt Bắc, rồi về đồng bằng và thành thị. Chỉ bốn năm sau, Việt Minh trở thành lực lượng lãnh đạo toàn dân đứng lên giành chính quyền."},{"t":"Bạn có biết? Nghị quyết Hội nghị Trung ương lần thứ tám đã nêu rõ: sau khi đánh đuổi Pháp – Nhật sẽ thành lập nước Việt Nam Dân chủ Cộng hòa. Bốn năm sau, ngày 2/9/1945, đó chính là tên của nhà nước mới được Chủ tịch Hồ Chí Minh tuyên bố khai sinh."},{"t":"Chuẩn bị khởi nghĩa là nhiệm vụ trung tâm. Hội nghị xác định chuẩn bị khởi nghĩa vũ trang là nhiệm vụ trung tâm của Đảng và nhân dân trong giai đoạn này. Hội nghị dự kiến con đường giành chính quyền: đi từ khởi nghĩa từng phần ở từng địa phương, tiến lên tổng khởi nghĩa khi thời cơ đến. Muốn vậy, phải xây dựng lực lượng chính trị của quần chúng, xây dựng lực lượng vũ trang và các căn cứ địa cách mạng. Những chủ trương ấy biến căn lán nhỏ thành điểm xuất phát của cả một kế hoạch dài hơi. Căn cứ Cao Bằng và căn cứ Bắc Sơn – Võ Nhai được củng cố, các đội du kích được duy trì và phát triển. Cán bộ được đào tạo để chuẩn bị cho ngày khởi nghĩa. Bốn năm sau, khi phát xít Nhật đầu hàng Đồng minh tháng 8/1945, toàn dân tộc đã sẵn sàng. Cách mạng Tháng Tám diễn ra đúng theo hình thái mà Hội nghị ở Khuổi Nặm đã dự kiến: từ khởi nghĩa từng phần tiến lên tổng khởi nghĩa."},{"t":"Lời kêu gọi từ vùng đầu nguồn. Ít ngày sau hội nghị, ngày 6/6/1941, Nguyễn Ái Quốc viết thư “Kính cáo đồng bào”, kêu gọi toàn dân đoàn kết đánh Pháp, đuổi Nhật. Bức thư vạch rõ cảnh nhân dân ta bị cả thực dân Pháp và phát xít Nhật áp bức, bóc lột. Lời lẽ giản dị mà thống thiết, hướng tới mọi tầng lớp đồng bào, từ các bậc phụ huynh, các nhà trí thức, đến người lao động và binh lính. Bức thư đưa tinh thần của Hội nghị Trung ương lần thứ tám đến với quần chúng bằng ngôn ngữ của trái tim. Nó biến một nghị quyết của Đảng thành lời hiệu triệu của cả dân tộc, mời gọi mỗi người Việt Nam góp phần mình vào sự nghiệp chung. Bức thư được ký tên Nguyễn Ái Quốc, cái tên mà nhiều người yêu nước đã biết đến từ bản Yêu sách của nhân dân An Nam gửi Hội nghị Véc-xai năm 1919. Sau nhiều năm, cái tên ấy lại vang lên trong một lời kêu gọi gửi thẳng tới đồng bào trong nước."},{"t":"Việc cứu quốc là việc chung. Ai là người Việt Nam đều phải kề vai gánh vác một phần trách nhiệm: người có tiền góp tiền, người có của góp của, người có sức góp sức, người có tài năng góp tài năng. — Nguyễn Ái Quốc"},{"t":"Những người trong căn lán. Số phận những người dự hội nghị năm ấy gắn liền với những năm tháng khốc liệt nhất của cách mạng. Đồng chí Phùng Chí Kiên hy sinh ngay trong năm 1941. Đồng chí Hoàng Văn Thụ bị địch bắt và hy sinh năm 1944, khi Cách mạng Tháng Tám chỉ còn cách hơn một năm. Đồng chí Trường Chinh, Tổng Bí thư được bầu tại Khuổi Nặm, cùng đồng chí Hoàng Quốc Việt tiếp tục lãnh đạo phong trào trong nước đến ngày Tổng khởi nghĩa. Còn Nguyễn Ái Quốc tiếp tục ở lại vùng căn cứ, xây dựng phong trào ở Cao Bằng. Ngày 1/8/1941, tờ báo Việt Nam độc lập do Người sáng lập ra số đầu tiên. Tháng 8/1942, Người lên đường sang Trung Quốc với tên Hồ Chí Minh, mở ra một chặng đường mới được kể trong chuyên đề Mốc thời gian. Căn lán nhỏ ở bìa rừng Khuổi Nặm, vì thế, là nơi hội tụ của những con người đã dâng hiến cả cuộc đời cho độc lập dân tộc."},{"t":"Dấu tích hôm nay. Ngày nay, lán Khuổi Nặm là một điểm quan trọng trong Khu di tích quốc gia đặc biệt Pác Bó. Khách tham quan theo lối mòn vào bìa rừng sẽ gặp căn lán sàn hai gian nhỏ nép dưới tán cây, gần dòng suối Khuổi Nặm. Nhìn căn lán tận mắt, có thể hiểu vì sao nơi này được chọn: lán gần như khuất hẳn giữa rừng cây, trong khi từ lán lại nhìn rõ các lối đi phía trước. Trong gian trưng bày của Bảo tàng Hành trình 3D, góc lán Khuổi Nặm có một chiếc bàn nhỏ và một ngọn đèn dầu. Đó là những đồ vật minh họa, gợi lại khung cảnh giản dị của hội nghị năm 1941 và những đêm làm việc trong lán; bấm vào từng đồ vật để đọc câu chuyện của nó. Căn lán mười hai mét vuông nhắc người hôm nay rằng những quyết định lớn nhất của một dân tộc không cần đến những hội trường lộng lẫy, mà cần tầm nhìn, sự đồng lòng và niềm tin vào sức mạnh của nhân dân."},{"t":"Bạn có biết? Theo hồ sơ di tích, trong quần thể Pác Bó, lán Khuổi Nặm là nơi Người ở lâu nhất. Thời gian ấy dài hơn cả ở hang Cốc Bó, hang Lũng Lạn hay nhà ông Lý Quốc Súng, nơi Người ở mười một ngày đầu tiên sau khi về nước."}],"so_chu":2128}],"do_vat":[{"id":"treasure_chest@-14.6,-49.0","x":-14.6,"y":0.55,"z":-49,"loai":"treasure_chest","ten":"Chiếc hòm gỗ","tieu_de":"Nơi cất giữ tài liệu trong hang đá","text":"Sáng ngày 28 tháng 1 năm 1941, sau đúng ba mươi năm bôn ba tìm đường cứu nước, Nguyễn Ái Quốc vượt qua cột mốc biên giới số 108 thuộc xã Trường Hà, huyện Hà Quảng, tỉnh Cao Bằng, đặt chân trở lại Tổ quốc. Người mang tên gọi mới — Già Thu — hòa vào cuộc sống của đồng bào Tày, Nùng nơi miền biên viễn, rồi ít ngày sau chuyển vào ở và làm việc trong hang Cốc Bó, một hang đá nhỏ dưới chân núi, kín đáo và dễ ẩn náu khi cần lui về phía biên giới.\n\nCái tên Pác Bó, trong tiếng Tày có nghĩa là “đầu nguồn”, gọi đúng vị trí của bản làng nằm ngay nơi một dòng suối bắt đầu chảy ra từ lòng núi đá vôi. Địa hình hiểm trở, nhiều hang động ăn sâu vào núi, lại nằm sát biên giới Việt – Trung khiến Pác Bó trở thành nơi lý tưởng để đặt căn cứ đầu tiên: vừa dễ ẩn náu trước các cuộc lùng sục của thực dân Pháp, vừa có thể lui về phía bên kia biên giới khi tình thế nguy cấp, trong khi đồng bào các dân tộc nơi đây từ trước đã một lòng tin theo cách mạng.\n\nTrong không gian chật hẹp của hang đá, đồ đạc mang theo chỉ gồm những vật dụng tối thiểu: một tấm ván kê làm giường, một bếp lửa nhỏ để sưởi ấm và nấu ăn, và một chiếc hòm gỗ dùng để cất giữ tài liệu, sách báo cách mạng. Hang đá vốn ẩm thấp, giấy tờ mực viết dễ bị hư hỏng, ẩm mốc theo thời gian; trong khi đó, tài liệu cách mạng lại là thứ phải được giữ gìn cẩn thận và tuyệt đối bí mật, tránh rơi vào tay đối phương nếu có lục soát bất ngờ. Chiếc hòm nhỏ, vì thế, trở thành vật dụng quan trọng bậc nhất trong đời sống hằng ngày của người lãnh đạo cách mạng giữa núi rừng.\n\nChính trong những tháng ngày ở hang Cốc Bó, Người vừa trực tiếp dịch tài liệu lý luận, soạn thảo các văn kiện huấn luyện cán bộ, vừa theo dõi sát diễn biến phong trào trong nước để chuẩn bị cho một hội nghị quan trọng. Tháng 5 năm 1941, Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng họp tại lán Khuổi Nặm gần đó, dưới sự chủ trì của Người, quyết định đặt nhiệm vụ giải phóng dân tộc lên hàng đầu và thành lập Mặt trận Việt Minh — một quyết định có ý nghĩa bước ngoặt được chuẩn bị phần lớn ngay từ những trang tài liệu cất trong chiếc hòm gỗ nhỏ ấy.\n\nNgày nay, hang Cốc Bó cùng khu vực xung quanh được bảo tồn gần như nguyên vẹn trong Khu di tích lịch sử Pác Bó, tỉnh Cao Bằng, là điểm đến quen thuộc của các đoàn khách tham quan, học tập truyền thống cách mạng. Chiếc hòm gỗ trưng bày trong không gian ba chiều tại đây là đồ vật minh họa, phục dựng theo mô tả về đời sống giản dị trong hang đá năm 1941, giúp người xem hình dung rõ hơn điều kiện làm việc gian khổ nhưng đầy quyết tâm của những ngày đầu chuẩn bị cho cao trào giải phóng dân tộc.","nguon":"Khu di tích lịch sử Pác Bó (Cao Bằng); Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","doc":[{"t":"Nơi cất giữ tài liệu trong hang đá. Sáng ngày 28 tháng 1 năm 1941, sau đúng ba mươi năm bôn ba tìm đường cứu nước, Nguyễn Ái Quốc vượt qua cột mốc biên giới số 108 thuộc xã Trường Hà, huyện Hà Quảng, tỉnh Cao Bằng, đặt chân trở lại Tổ quốc. Người mang tên gọi mới — Già Thu — hòa vào cuộc sống của đồng bào Tày, Nùng nơi miền biên viễn, rồi ít ngày sau chuyển vào ở và làm việc trong hang Cốc Bó, một hang đá nhỏ dưới chân núi, kín đáo và dễ ẩn náu khi cần lui về phía biên giới."},{"t":"Cái tên Pác Bó, trong tiếng Tày có nghĩa là “đầu nguồn”, gọi đúng vị trí của bản làng nằm ngay nơi một dòng suối bắt đầu chảy ra từ lòng núi đá vôi. Địa hình hiểm trở, nhiều hang động ăn sâu vào núi, lại nằm sát biên giới Việt – Trung khiến Pác Bó trở thành nơi lý tưởng để đặt căn cứ đầu tiên: vừa dễ ẩn náu trước các cuộc lùng sục của thực dân Pháp, vừa có thể lui về phía bên kia biên giới khi tình thế nguy cấp, trong khi đồng bào các dân tộc nơi đây từ trước đã một lòng tin theo cách mạng."},{"t":"Trong không gian chật hẹp của hang đá, đồ đạc mang theo chỉ gồm những vật dụng tối thiểu: một tấm ván kê làm giường, một bếp lửa nhỏ để sưởi ấm và nấu ăn, và một chiếc hòm gỗ dùng để cất giữ tài liệu, sách báo cách mạng. Hang đá vốn ẩm thấp, giấy tờ mực viết dễ bị hư hỏng, ẩm mốc theo thời gian; trong khi đó, tài liệu cách mạng lại là thứ phải được giữ gìn cẩn thận và tuyệt đối bí mật, tránh rơi vào tay đối phương nếu có lục soát bất ngờ. Chiếc hòm nhỏ, vì thế, trở thành vật dụng quan trọng bậc nhất trong đời sống hằng ngày của người lãnh đạo cách mạng giữa núi rừng."},{"t":"Chính trong những tháng ngày ở hang Cốc Bó, Người vừa trực tiếp dịch tài liệu lý luận, soạn thảo các văn kiện huấn luyện cán bộ, vừa theo dõi sát diễn biến phong trào trong nước để chuẩn bị cho một hội nghị quan trọng. Tháng 5 năm 1941, Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng họp tại lán Khuổi Nặm gần đó, dưới sự chủ trì của Người, quyết định đặt nhiệm vụ giải phóng dân tộc lên hàng đầu và thành lập Mặt trận Việt Minh — một quyết định có ý nghĩa bước ngoặt được chuẩn bị phần lớn ngay từ những trang tài liệu cất trong chiếc hòm gỗ nhỏ ấy."},{"t":"Ngày nay, hang Cốc Bó cùng khu vực xung quanh được bảo tồn gần như nguyên vẹn trong Khu di tích lịch sử Pác Bó, tỉnh Cao Bằng, là điểm đến quen thuộc của các đoàn khách tham quan, học tập truyền thống cách mạng. Chiếc hòm gỗ trưng bày trong không gian ba chiều tại đây là đồ vật minh họa, phục dựng theo mô tả về đời sống giản dị trong hang đá năm 1941, giúp người xem hình dung rõ hơn điều kiện làm việc gian khổ nhưng đầy quyết tâm của những ngày đầu chuẩn bị cho cao trào giải phóng dân tộc."},{"t":"Bạn có biết? Trong những ngày đầu về nước, Nguyễn Ái Quốc mang tên gọi Già Thu, hòa mình vào cuộc sống của đồng bào Tày, Nùng ở vùng biên giới Cao Bằng."}],"ban_co_biet":"Trong những ngày đầu về nước, Nguyễn Ái Quốc mang tên gọi Già Thu, hòa mình vào cuộc sống của đồng bào Tày, Nùng ở vùng biên giới Cao Bằng."},{"id":"wooden_bowl_01@-15.1,-46.8","x":-15.1,"y":0.55,"z":-46.8,"loai":"wooden_bowl_01","ten":"Bát gỗ","tieu_de":"“Cháo bẹ rau măng vẫn sẵn sàng”","text":"Giữa núi rừng Pác Bó, bữa ăn hằng ngày của Nguyễn Ái Quốc và các đồng chí cùng hoạt động rất đạm bạc, chủ yếu là cháo bẹ — tức cháo nấu từ ngô — cùng rau măng hái được trong rừng quanh hang Cốc Bó. Đây không phải là chi tiết suy đoán, mà chính Người đã ghi lại trong bài thơ Tức cảnh Pác Bó, sáng tác năm 1941: “Sáng ra bờ suối, tối vào hang / Cháo bẹ rau măng vẫn sẵn sàng / Bàn đá chông chênh dịch sử Đảng / Cuộc đời cách mạng thật là sang.”\n\nChiếc bát gỗ đặt cạnh bếp lửa nhỏ trong hang là vật dụng gắn liền với những bữa ăn giản dị ấy. Thời kỳ đầu về nước, điều kiện sinh hoạt nơi biên giới hết sức thiếu thốn: không có ruộng vườn ổn định, lương thực chủ yếu do đồng bào Tày, Nùng trong vùng giúp đỡ hoặc tự kiếm được từ núi rừng. Một bát cháo ngô, một nắm rau măng đã là bữa ăn tươm tất trong hoàn cảnh ấy, nhưng với Người, đó lại là điều hoàn toàn bình thường của cuộc đời người làm cách mạng.\n\nNgô — hay “bẹ” theo cách gọi của đồng bào miền núi phía Bắc — vốn là lương thực chính thay cho gạo ở nhiều bản làng vùng cao thời ấy, nơi ruộng nước hiếm hoi mà nương rẫy trồng ngô lại phù hợp với địa hình núi đá. Rau măng mọc tự nhiên trong rừng, không tốn công trồng cấy, trở thành nguồn thức ăn sẵn có quanh năm. Bữa cơm đạm bạc của Người, vì thế, cũng chính là bữa cơm quen thuộc của biết bao gia đình Tày, Nùng đã cưu mang, che chở cho cách mạng trong những ngày tháng gian khó ấy tại Pác Bó.\n\nĐiều đáng chú ý trong bốn câu thơ ngắn ngủi ấy không phải là sự than vãn về thiếu thốn, mà là tinh thần lạc quan hiếm có: câu kết “Cuộc đời cách mạng thật là sang” biến gian khổ vật chất thành một cách nhìn đầy tự hào về lý tưởng đã chọn. Bài thơ, vì thế, không chỉ là một ghi chép đời thường mà còn trở thành một trong những áng thơ tiêu biểu nhất phản ánh phong cách sống và tinh thần của Người trong những năm tháng gian khó nhất trước Cách mạng Tháng Tám.\n\nNếp sống giản dị ấy không phải là điều bất đắc dĩ chỉ có trong những ngày đầu gian khó ở Pác Bó, mà theo nhiều hồi ký của những người từng sống và làm việc gần Người, đó là một lối sống được giữ gìn xuyên suốt cả cuộc đời hoạt động cách mạng, bất kể hoàn cảnh khó khăn hay đủ đầy. Chiếc bát gỗ nhỏ bên bếp lửa, vì vậy, không chỉ minh họa cho một giai đoạn lịch sử cụ thể mà còn gợi mở về một phong cách sống đã trở thành huyền thoại.\n\nChiếc bát gỗ trưng bày trong gian là đồ vật minh họa, được lựa chọn theo kiểu vật dụng sinh hoạt phổ biến của đồng bào miền núi phía Bắc thời kỳ ấy, giúp gợi lại đúng không khí đạm bạc mà ấm áp của những bữa cơm bên bếp lửa trong hang Cốc Bó, chứ không phải hiện vật gốc còn được lưu giữ. Bài thơ Tức cảnh Pác Bó gắn với hiện vật này hiện được giới thiệu trong nhiều tài liệu, sách giáo khoa và tại Khu di tích lịch sử Pác Bó, Cao Bằng.","nguon":"Tức cảnh Pác Bó (1941); Khu di tích lịch sử Pác Bó (Cao Bằng)","doc":[{"t":"“Cháo bẹ rau măng vẫn sẵn sàng”. Giữa núi rừng Pác Bó, bữa ăn hằng ngày của Nguyễn Ái Quốc và các đồng chí cùng hoạt động rất đạm bạc, chủ yếu là cháo bẹ — tức cháo nấu từ ngô — cùng rau măng hái được trong rừng quanh hang Cốc Bó. Đây không phải là chi tiết suy đoán, mà chính Người đã ghi lại trong bài thơ Tức cảnh Pác Bó, sáng tác năm 1941: “Sáng ra bờ suối, tối vào hang / Cháo bẹ rau măng vẫn sẵn sàng / Bàn đá chông chênh dịch sử Đảng / Cuộc đời cách mạng thật là sang.”"},{"t":"Chiếc bát gỗ đặt cạnh bếp lửa nhỏ trong hang là vật dụng gắn liền với những bữa ăn giản dị ấy. Thời kỳ đầu về nước, điều kiện sinh hoạt nơi biên giới hết sức thiếu thốn: không có ruộng vườn ổn định, lương thực chủ yếu do đồng bào Tày, Nùng trong vùng giúp đỡ hoặc tự kiếm được từ núi rừng. Một bát cháo ngô, một nắm rau măng đã là bữa ăn tươm tất trong hoàn cảnh ấy, nhưng với Người, đó lại là điều hoàn toàn bình thường của cuộc đời người làm cách mạng."},{"t":"Ngô — hay “bẹ” theo cách gọi của đồng bào miền núi phía Bắc — vốn là lương thực chính thay cho gạo ở nhiều bản làng vùng cao thời ấy, nơi ruộng nước hiếm hoi mà nương rẫy trồng ngô lại phù hợp với địa hình núi đá. Rau măng mọc tự nhiên trong rừng, không tốn công trồng cấy, trở thành nguồn thức ăn sẵn có quanh năm. Bữa cơm đạm bạc của Người, vì thế, cũng chính là bữa cơm quen thuộc của biết bao gia đình Tày, Nùng đã cưu mang, che chở cho cách mạng trong những ngày tháng gian khó ấy tại Pác Bó."},{"t":"Điều đáng chú ý trong bốn câu thơ ngắn ngủi ấy không phải là sự than vãn về thiếu thốn, mà là tinh thần lạc quan hiếm có: câu kết “Cuộc đời cách mạng thật là sang” biến gian khổ vật chất thành một cách nhìn đầy tự hào về lý tưởng đã chọn. Bài thơ, vì thế, không chỉ là một ghi chép đời thường mà còn trở thành một trong những áng thơ tiêu biểu nhất phản ánh phong cách sống và tinh thần của Người trong những năm tháng gian khó nhất trước Cách mạng Tháng Tám."},{"t":"Nếp sống giản dị ấy không phải là điều bất đắc dĩ chỉ có trong những ngày đầu gian khó ở Pác Bó, mà theo nhiều hồi ký của những người từng sống và làm việc gần Người, đó là một lối sống được giữ gìn xuyên suốt cả cuộc đời hoạt động cách mạng, bất kể hoàn cảnh khó khăn hay đủ đầy. Chiếc bát gỗ nhỏ bên bếp lửa, vì vậy, không chỉ minh họa cho một giai đoạn lịch sử cụ thể mà còn gợi mở về một phong cách sống đã trở thành huyền thoại."},{"t":"Chiếc bát gỗ trưng bày trong gian là đồ vật minh họa, được lựa chọn theo kiểu vật dụng sinh hoạt phổ biến của đồng bào miền núi phía Bắc thời kỳ ấy, giúp gợi lại đúng không khí đạm bạc mà ấm áp của những bữa cơm bên bếp lửa trong hang Cốc Bó, chứ không phải hiện vật gốc còn được lưu giữ. Bài thơ Tức cảnh Pác Bó gắn với hiện vật này hiện được giới thiệu trong nhiều tài liệu, sách giáo khoa và tại Khu di tích lịch sử Pác Bó, Cao Bằng."},{"t":"Bạn có biết? Bài thơ Tức cảnh Pác Bó chỉ vỏn vẹn bốn câu nhưng đã trở thành một trong những tác phẩm được trích dẫn nhiều nhất khi nói về đời sống của Nguyễn Ái Quốc những ngày đầu về nước năm 1941."}],"ban_co_biet":"Bài thơ Tức cảnh Pác Bó chỉ vỏn vẹn bốn câu nhưng đã trở thành một trong những tác phẩm được trích dẫn nhiều nhất khi nói về đời sống của Nguyễn Ái Quốc những ngày đầu về nước năm 1941."},{"id":"binder_notebook@2.2,-11.9","x":2.24,"y":1.17,"z":-11.95,"loai":"binder_notebook","ten":"Cuốn sổ bản dịch","tieu_de":"Những trang dịch “sử Đảng” bên suối","text":"Trước cửa hang Cốc Bó có một dòng suối nước trong vắt chảy qua, được Nguyễn Ái Quốc đặt tên là suối Lê-nin, còn ngọn núi đá vôi sừng sững phía sau được Người gọi là núi Các Mác — những cái tên giản dị nhưng gửi gắm trọn vẹn lý tưởng dẫn đường cho sự nghiệp cách mạng mà Người theo đuổi suốt cả cuộc đời. Bên bờ suối ấy có một phiến đá nhỏ, mặt gồ ghề, mấp mô không bằng phẳng, được Người tận dụng làm bàn làm việc mỗi khi trời tạnh ráo.\n\nChính trên phiến đá chông chênh ấy, Người miệt mài dịch cuốn Lịch sử Đảng Cộng sản (bôn-sê-vích) Liên Xô sang tiếng Việt, nhằm có tài liệu lý luận căn bản để huấn luyện đội ngũ cán bộ cách mạng đang được xây dựng gấp rút ở vùng căn cứ Cao Bằng. Công việc dịch thuật đòi hỏi sự tập trung cao độ, trong khi điều kiện làm việc lại vô cùng thiếu thốn: không bàn ghế, không đèn sáng ổn định, chỉ có ánh sáng tự nhiên bên bờ suối và ý chí bền bỉ của người dịch.\n\nCâu thơ “Bàn đá chông chênh dịch sử Đảng” trong bài Tức cảnh Pác Bó chính là ghi chép trực tiếp về công việc này, cho thấy giữa hoàn cảnh gian khổ nhất, việc chuẩn bị lý luận cách mạng vẫn được tiến hành đều đặn, nghiêm túc. Bản dịch hoàn thành từ những buổi làm việc bên suối như vậy trở thành tài liệu học tập quan trọng cho lớp cán bộ đầu tiên của phong trào Việt Minh tại Cao Bằng trong những năm 1941, 1942.\n\nCâu thơ mở đầu cùng bài — “Sáng ra bờ suối, tối vào hang” — cho thấy rõ nhịp sinh hoạt đều đặn của Người trong giai đoạn này: ban ngày ra ngoài làm việc bên phiến đá cạnh dòng suối trong vắt, tối đến mới trở vào hang đá nghỉ ngơi. Nhịp sống ấy lặp lại gần như mỗi ngày trong suốt những tháng đầu năm 1941, biến một khoảnh bờ suối nhỏ giữa núi rừng biên giới thành nơi ra đời của nhiều trang tài liệu quan trọng, đặt nền móng lý luận cho cả một giai đoạn cách mạng sắp tới.\n\nCông việc dịch thuật lý luận này không phải là việc làm đơn lẻ mà nằm trong cả một kế hoạch xây dựng đội ngũ cán bộ có nền tảng tư tưởng vững chắc cho phong trào Việt Minh vừa nhen nhóm ở Cao Bằng. Cùng với các tài liệu diễn ca dễ nhớ dành cho quần chúng, bản dịch lý luận chuyên sâu trên bàn đá bên suối Lê-nin nhắm tới một đối tượng khác: lớp cán bộ cốt cán cần được trang bị hiểu biết bài bản hơn để dẫn dắt phong trào ở cơ sở (xem chuyên đề đồ vật “Sách và tài liệu huấn luyện”).\n\nCuốn sổ đặt trên bàn đá trong không gian ba chiều tại đây là đồ vật minh họa cho những trang bản dịch được viết giữa trời, trên mặt đá gồ ghề bên dòng suối Lê-nin, chứ không phải bản thảo gốc còn lưu giữ được. Ngày nay, phiến đá ấy — được gọi bằng đúng tên trong bài thơ là “bàn đá chông chênh” — cùng suối Lê-nin và núi Các Mác vẫn được bảo tồn gần như nguyên vẹn trong Khu di tích lịch sử Pác Bó, là một trong những điểm dừng chân được du khách tìm đến nhiều nhất.","nguon":"Tức cảnh Pác Bó (1941); Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","doc":[{"t":"Những trang dịch “sử Đảng” bên suối. Trước cửa hang Cốc Bó có một dòng suối nước trong vắt chảy qua, được Nguyễn Ái Quốc đặt tên là suối Lê-nin, còn ngọn núi đá vôi sừng sững phía sau được Người gọi là núi Các Mác — những cái tên giản dị nhưng gửi gắm trọn vẹn lý tưởng dẫn đường cho sự nghiệp cách mạng mà Người theo đuổi suốt cả cuộc đời. Bên bờ suối ấy có một phiến đá nhỏ, mặt gồ ghề, mấp mô không bằng phẳng, được Người tận dụng làm bàn làm việc mỗi khi trời tạnh ráo."},{"t":"Chính trên phiến đá chông chênh ấy, Người miệt mài dịch cuốn Lịch sử Đảng Cộng sản (bôn-sê-vích) Liên Xô sang tiếng Việt, nhằm có tài liệu lý luận căn bản để huấn luyện đội ngũ cán bộ cách mạng đang được xây dựng gấp rút ở vùng căn cứ Cao Bằng. Công việc dịch thuật đòi hỏi sự tập trung cao độ, trong khi điều kiện làm việc lại vô cùng thiếu thốn: không bàn ghế, không đèn sáng ổn định, chỉ có ánh sáng tự nhiên bên bờ suối và ý chí bền bỉ của người dịch."},{"t":"Câu thơ “Bàn đá chông chênh dịch sử Đảng” trong bài Tức cảnh Pác Bó chính là ghi chép trực tiếp về công việc này, cho thấy giữa hoàn cảnh gian khổ nhất, việc chuẩn bị lý luận cách mạng vẫn được tiến hành đều đặn, nghiêm túc. Bản dịch hoàn thành từ những buổi làm việc bên suối như vậy trở thành tài liệu học tập quan trọng cho lớp cán bộ đầu tiên của phong trào Việt Minh tại Cao Bằng trong những năm 1941, 1942."},{"t":"Câu thơ mở đầu cùng bài — “Sáng ra bờ suối, tối vào hang” — cho thấy rõ nhịp sinh hoạt đều đặn của Người trong giai đoạn này: ban ngày ra ngoài làm việc bên phiến đá cạnh dòng suối trong vắt, tối đến mới trở vào hang đá nghỉ ngơi. Nhịp sống ấy lặp lại gần như mỗi ngày trong suốt những tháng đầu năm 1941, biến một khoảnh bờ suối nhỏ giữa núi rừng biên giới thành nơi ra đời của nhiều trang tài liệu quan trọng, đặt nền móng lý luận cho cả một giai đoạn cách mạng sắp tới."},{"t":"Công việc dịch thuật lý luận này không phải là việc làm đơn lẻ mà nằm trong cả một kế hoạch xây dựng đội ngũ cán bộ có nền tảng tư tưởng vững chắc cho phong trào Việt Minh vừa nhen nhóm ở Cao Bằng. Cùng với các tài liệu diễn ca dễ nhớ dành cho quần chúng, bản dịch lý luận chuyên sâu trên bàn đá bên suối Lê-nin nhắm tới một đối tượng khác: lớp cán bộ cốt cán cần được trang bị hiểu biết bài bản hơn để dẫn dắt phong trào ở cơ sở (xem chuyên đề đồ vật “Sách và tài liệu huấn luyện”)."},{"t":"Cuốn sổ đặt trên bàn đá trong không gian ba chiều tại đây là đồ vật minh họa cho những trang bản dịch được viết giữa trời, trên mặt đá gồ ghề bên dòng suối Lê-nin, chứ không phải bản thảo gốc còn lưu giữ được. Ngày nay, phiến đá ấy — được gọi bằng đúng tên trong bài thơ là “bàn đá chông chênh” — cùng suối Lê-nin và núi Các Mác vẫn được bảo tồn gần như nguyên vẹn trong Khu di tích lịch sử Pác Bó, là một trong những điểm dừng chân được du khách tìm đến nhiều nhất."},{"t":"Bạn có biết? Người tự đặt tên dòng suối trước hang Cốc Bó là suối Lê-nin và ngọn núi phía sau là núi Các Mác, hai cái tên vẫn được giữ nguyên cho đến ngày nay tại Khu di tích Pác Bó."}],"ban_co_biet":"Người tự đặt tên dòng suối trước hang Cốc Bó là suối Lê-nin và ngọn núi phía sau là núi Các Mác, hai cái tên vẫn được giữ nguyên cho đến ngày nay tại Khu di tích Pác Bó."},{"id":"book_encyclopedia_set_01@2.8,-12.2","x":2.79,"y":1.17,"z":-12.15,"loai":"book_encyclopedia_set_01","ten":"Sách và tài liệu huấn luyện","tieu_de":"Những cuốn sách nhỏ cho đồng bào","text":"Bên cạnh việc dịch tài liệu lý luận trên phiến đá bên suối Lê-nin, tại vùng căn cứ Cao Bằng, Nguyễn Ái Quốc còn trực tiếp viết nhiều tài liệu ngắn gọn, dễ hiểu để huấn luyện cán bộ cơ sở và vận động quần chúng nhân dân theo cách mạng. Khác với những công trình lý luận dài, các tài liệu này thường được viết theo lối văn vần, dễ đọc, dễ nhớ, dễ truyền miệng — phù hợp với trình độ của đông đảo đồng bào ở vùng núi cao, nơi việc học chữ còn nhiều hạn chế.\n\nTiêu biểu trong số đó là bài diễn ca Lịch sử nước ta, mở đầu bằng câu được nhiều thế hệ người Việt thuộc lòng: “Dân ta phải biết sử ta”, do Việt Minh xuất bản năm 1942 để phổ biến rộng rãi trong quần chúng. Ở phần cuối bài diễn ca, Người còn ghi rõ dự báo về thời điểm giành độc lập: “1945 – Việt Nam độc lập”, một dự báo về sau được chứng thực đúng bằng thắng lợi của Cách mạng Tháng Tám năm 1945.\n\nSong song với các tài liệu tuyên truyền, lịch sử, Người còn soạn thảo những tài liệu mang tính quân sự thiết thực như Cách đánh du kích, hướng dẫn cụ thể cách tổ chức, chiến thuật cho các đội du kích nhỏ đang được xây dựng ở vùng căn cứ. Những cuốn sách, tài liệu tưởng như đơn sơ ấy chính là nền tảng tư tưởng và tổ chức quan trọng, chuẩn bị trực tiếp cho sự ra đời của Đội Việt Nam Tuyên truyền Giải phóng quân vào tháng 12 năm 1944 và cho cả cao trào Tổng khởi nghĩa sau này.\n\nNgày 22 tháng 12 năm 1944, thực hiện đúng những nguyên tắc tổ chức, chiến thuật đã được đúc kết trong các tài liệu huấn luyện trước đó, Đội Việt Nam Tuyên truyền Giải phóng quân chính thức được thành lập trong rừng, ban đầu chỉ với 34 chiến sĩ, do Võ Nguyên Giáp trực tiếp chỉ huy — đặt viên gạch đầu tiên cho Quân đội nhân dân Việt Nam sau này. Từ những trang sách nhỏ được viết ở Pác Bó đến một đội quân cách mạng đầu tiên ra đời chỉ ba năm sau, có thể thấy rõ tầm nhìn xa của công tác chuẩn bị được Người tiến hành ngay từ những ngày đầu về nước.\n\nĐiểm chung của những tài liệu này — từ diễn ca lịch sử, sách hướng dẫn du kích đến các bản tin tuyên truyền — là lối viết ngắn gọn, gần gũi với cách nói, cách nghĩ của người dân bình thường, khác hẳn văn phong hàn lâm thường thấy ở các tài liệu lý luận. Chính sự giản dị, dễ hiểu ấy đã giúp tư tưởng cách mạng lan tỏa nhanh chóng trong quần chúng ở một vùng núi cao, nơi trình độ dân trí còn nhiều hạn chế nhưng lòng yêu nước thì chưa bao giờ thiếu.\n\nChồng sách và tài liệu huấn luyện trưng bày trong không gian ba chiều tại đây là đồ vật minh họa, tượng trưng cho khối lượng lớn tài liệu tuyên truyền, huấn luyện được biên soạn ngay tại vùng núi Cao Bằng trong những năm 1941 – 1942, phần lớn viết tay hoặc in bằng phương tiện thô sơ, chứ không phải bản in gốc còn được lưu giữ nguyên vẹn. Nhiều bản diễn ca, tài liệu huấn luyện thời kỳ này hiện được giới thiệu dưới dạng tư liệu tại Bảo tàng Hồ Chí Minh và các bảo tàng lịch sử cách mạng trong nước.","nguon":"Hồ Chí Minh Toàn tập, tập 3, NXB Chính trị quốc gia, 2011; Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","doc":[{"t":"Những cuốn sách nhỏ cho đồng bào. Bên cạnh việc dịch tài liệu lý luận trên phiến đá bên suối Lê-nin, tại vùng căn cứ Cao Bằng, Nguyễn Ái Quốc còn trực tiếp viết nhiều tài liệu ngắn gọn, dễ hiểu để huấn luyện cán bộ cơ sở và vận động quần chúng nhân dân theo cách mạng. Khác với những công trình lý luận dài, các tài liệu này thường được viết theo lối văn vần, dễ đọc, dễ nhớ, dễ truyền miệng — phù hợp với trình độ của đông đảo đồng bào ở vùng núi cao, nơi việc học chữ còn nhiều hạn chế."},{"t":"Tiêu biểu trong số đó là bài diễn ca Lịch sử nước ta, mở đầu bằng câu được nhiều thế hệ người Việt thuộc lòng: “Dân ta phải biết sử ta”, do Việt Minh xuất bản năm 1942 để phổ biến rộng rãi trong quần chúng. Ở phần cuối bài diễn ca, Người còn ghi rõ dự báo về thời điểm giành độc lập: “1945 – Việt Nam độc lập”, một dự báo về sau được chứng thực đúng bằng thắng lợi của Cách mạng Tháng Tám năm 1945."},{"t":"Song song với các tài liệu tuyên truyền, lịch sử, Người còn soạn thảo những tài liệu mang tính quân sự thiết thực như Cách đánh du kích, hướng dẫn cụ thể cách tổ chức, chiến thuật cho các đội du kích nhỏ đang được xây dựng ở vùng căn cứ. Những cuốn sách, tài liệu tưởng như đơn sơ ấy chính là nền tảng tư tưởng và tổ chức quan trọng, chuẩn bị trực tiếp cho sự ra đời của Đội Việt Nam Tuyên truyền Giải phóng quân vào tháng 12 năm 1944 và cho cả cao trào Tổng khởi nghĩa sau này."},{"t":"Ngày 22 tháng 12 năm 1944, thực hiện đúng những nguyên tắc tổ chức, chiến thuật đã được đúc kết trong các tài liệu huấn luyện trước đó, Đội Việt Nam Tuyên truyền Giải phóng quân chính thức được thành lập trong rừng, ban đầu chỉ với 34 chiến sĩ, do Võ Nguyên Giáp trực tiếp chỉ huy — đặt viên gạch đầu tiên cho Quân đội nhân dân Việt Nam sau này. Từ những trang sách nhỏ được viết ở Pác Bó đến một đội quân cách mạng đầu tiên ra đời chỉ ba năm sau, có thể thấy rõ tầm nhìn xa của công tác chuẩn bị được Người tiến hành ngay từ những ngày đầu về nước."},{"t":"Điểm chung của những tài liệu này — từ diễn ca lịch sử, sách hướng dẫn du kích đến các bản tin tuyên truyền — là lối viết ngắn gọn, gần gũi với cách nói, cách nghĩ của người dân bình thường, khác hẳn văn phong hàn lâm thường thấy ở các tài liệu lý luận. Chính sự giản dị, dễ hiểu ấy đã giúp tư tưởng cách mạng lan tỏa nhanh chóng trong quần chúng ở một vùng núi cao, nơi trình độ dân trí còn nhiều hạn chế nhưng lòng yêu nước thì chưa bao giờ thiếu."},{"t":"Chồng sách và tài liệu huấn luyện trưng bày trong không gian ba chiều tại đây là đồ vật minh họa, tượng trưng cho khối lượng lớn tài liệu tuyên truyền, huấn luyện được biên soạn ngay tại vùng núi Cao Bằng trong những năm 1941 – 1942, phần lớn viết tay hoặc in bằng phương tiện thô sơ, chứ không phải bản in gốc còn được lưu giữ nguyên vẹn. Nhiều bản diễn ca, tài liệu huấn luyện thời kỳ này hiện được giới thiệu dưới dạng tư liệu tại Bảo tàng Hồ Chí Minh và các bảo tàng lịch sử cách mạng trong nước."},{"t":"Bạn có biết? Trong bài diễn ca Lịch sử nước ta (1942), Nguyễn Ái Quốc từng ghi rõ dự báo “1945 – Việt Nam độc lập” — một dự báo sau này được chứng thực đúng bằng thắng lợi Cách mạng Tháng Tám."}],"ban_co_biet":"Trong bài diễn ca Lịch sử nước ta (1942), Nguyễn Ái Quốc từng ghi rõ dự báo “1945 – Việt Nam độc lập” — một dự báo sau này được chứng thực đúng bằng thắng lợi Cách mạng Tháng Tám."},{"id":"table@23.1,-18.1","x":23.08,"y":1.64,"z":-18.1,"loai":"table","ten":"Bàn trong lán Khuổi Nặm","tieu_de":"Nơi Hội nghị Trung ương lần thứ tám làm việc","text":"Cách hang Cốc Bó không xa, giữa rừng già Pác Bó, có một lán nhỏ dựng bằng tre nứa, mái lợp lá cọ, được gọi theo tên địa danh là lán Khuổi Nặm. Từ ngày 10 đến ngày 19 tháng 5 năm 1941, tại chính căn lán đơn sơ ấy, Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng đã họp liên tục trong mười ngày, dưới sự chủ trì trực tiếp của Nguyễn Ái Quốc — khi đó vừa trở về nước hơn ba tháng.\n\nQuanh chiếc bàn giản dị được kê tạm trong lán, các đại biểu Trung ương đã bàn bạc và đi đến những quyết định mang tính bước ngoặt: đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, tạm gác lại khẩu hiệu cách mạng ruộng đất để tập trung lực lượng toàn dân tộc chống Pháp, chống Nhật. Hội nghị cũng quyết định thành lập một mặt trận dân tộc thống nhất rộng rãi, lấy tên là Việt Nam Độc lập Đồng minh — gọi tắt là Việt Minh — chính thức ra đời ngày 19 tháng 5 năm 1941, đúng ngày bế mạc hội nghị.\n\nCùng với quyết định thành lập Việt Minh, Hội nghị Trung ương lần thứ tám còn bầu đồng chí Trường Chinh giữ chức Tổng Bí thư của Đảng. Đây được xem là một trong những quyết sách có tính bước ngoặt nhất của cách mạng Việt Nam giai đoạn này, đặt nền tảng tư tưởng và tổ chức trực tiếp cho thắng lợi của Cách mạng Tháng Tám chỉ hơn bốn năm sau đó. Từ những quyết định được đưa ra quanh chiếc bàn nhỏ trong lán tre giữa rừng, các hội Cứu quốc trong công nhân, nông dân, phụ nữ, thanh niên lần lượt được vận động thành lập khắp vùng căn cứ.\n\nTừ căn cứ địa Pác Bó với lán Khuổi Nặm là một trong những điểm mốc quan trọng nhất, con đường cách mạng do Người vạch ra tiếp tục mở rộng dần về phía nam, qua Tân Trào rồi tiến về Hà Nội trong mùa thu năm 1945. Có thể nói, những quyết sách bàn bạc quanh chiếc bàn nhỏ giữa rừng tre nứa này chính là điểm khởi đầu về mặt tổ chức cho cả chuỗi sự kiện dẫn tới ngày Tuyên ngôn Độc lập 2 tháng 9 năm 1945 tại Hà Nội.\n\nĐiều đáng chú ý là toàn bộ những quyết định lớn lao ấy được đưa ra không phải trong một hội trường bề thế mà trong một căn lán tre nứa đơn sơ, dựng tạm giữa rừng để tránh sự phát hiện của các cuộc càn quét. Sự tương phản giữa quy mô khiêm tốn của nơi họp và tầm vóc lịch sử của những quyết sách được thông qua tại đây là một trong những điều khiến lán Khuổi Nặm trở thành địa danh được nhắc đến nhiều nhất khi kể về giai đoạn chuẩn bị lực lượng cho Cách mạng Tháng Tám.\n\nChiếc bàn nhỏ trưng bày trong lán dựng lại tại đây là đồ vật minh họa, phục dựng theo mô tả về khung cảnh giản dị của một hội nghị có ý nghĩa lịch sử trọng đại, chứ không phải hiện vật gốc còn được lưu giữ nguyên vẹn. Ngày nay, lán Khuổi Nặm cùng khu vực xung quanh được phục dựng và bảo tồn trong Khu di tích lịch sử Pác Bó, tỉnh Cao Bằng, là điểm tham quan gắn liền với sự kiện thành lập Mặt trận Việt Minh.","nguon":"Văn kiện Đảng toàn tập, tập 7 (1940 – 1945), NXB Chính trị quốc gia – Nghị quyết Hội nghị Trung ương lần thứ tám","doc":[{"t":"Nơi Hội nghị Trung ương lần thứ tám làm việc. Cách hang Cốc Bó không xa, giữa rừng già Pác Bó, có một lán nhỏ dựng bằng tre nứa, mái lợp lá cọ, được gọi theo tên địa danh là lán Khuổi Nặm. Từ ngày 10 đến ngày 19 tháng 5 năm 1941, tại chính căn lán đơn sơ ấy, Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng đã họp liên tục trong mười ngày, dưới sự chủ trì trực tiếp của Nguyễn Ái Quốc — khi đó vừa trở về nước hơn ba tháng."},{"t":"Quanh chiếc bàn giản dị được kê tạm trong lán, các đại biểu Trung ương đã bàn bạc và đi đến những quyết định mang tính bước ngoặt: đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, tạm gác lại khẩu hiệu cách mạng ruộng đất để tập trung lực lượng toàn dân tộc chống Pháp, chống Nhật. Hội nghị cũng quyết định thành lập một mặt trận dân tộc thống nhất rộng rãi, lấy tên là Việt Nam Độc lập Đồng minh — gọi tắt là Việt Minh — chính thức ra đời ngày 19 tháng 5 năm 1941, đúng ngày bế mạc hội nghị."},{"t":"Cùng với quyết định thành lập Việt Minh, Hội nghị Trung ương lần thứ tám còn bầu đồng chí Trường Chinh giữ chức Tổng Bí thư của Đảng. Đây được xem là một trong những quyết sách có tính bước ngoặt nhất của cách mạng Việt Nam giai đoạn này, đặt nền tảng tư tưởng và tổ chức trực tiếp cho thắng lợi của Cách mạng Tháng Tám chỉ hơn bốn năm sau đó. Từ những quyết định được đưa ra quanh chiếc bàn nhỏ trong lán tre giữa rừng, các hội Cứu quốc trong công nhân, nông dân, phụ nữ, thanh niên lần lượt được vận động thành lập khắp vùng căn cứ."},{"t":"Từ căn cứ địa Pác Bó với lán Khuổi Nặm là một trong những điểm mốc quan trọng nhất, con đường cách mạng do Người vạch ra tiếp tục mở rộng dần về phía nam, qua Tân Trào rồi tiến về Hà Nội trong mùa thu năm 1945. Có thể nói, những quyết sách bàn bạc quanh chiếc bàn nhỏ giữa rừng tre nứa này chính là điểm khởi đầu về mặt tổ chức cho cả chuỗi sự kiện dẫn tới ngày Tuyên ngôn Độc lập 2 tháng 9 năm 1945 tại Hà Nội."},{"t":"Điều đáng chú ý là toàn bộ những quyết định lớn lao ấy được đưa ra không phải trong một hội trường bề thế mà trong một căn lán tre nứa đơn sơ, dựng tạm giữa rừng để tránh sự phát hiện của các cuộc càn quét. Sự tương phản giữa quy mô khiêm tốn của nơi họp và tầm vóc lịch sử của những quyết sách được thông qua tại đây là một trong những điều khiến lán Khuổi Nặm trở thành địa danh được nhắc đến nhiều nhất khi kể về giai đoạn chuẩn bị lực lượng cho Cách mạng Tháng Tám."},{"t":"Chiếc bàn nhỏ trưng bày trong lán dựng lại tại đây là đồ vật minh họa, phục dựng theo mô tả về khung cảnh giản dị của một hội nghị có ý nghĩa lịch sử trọng đại, chứ không phải hiện vật gốc còn được lưu giữ nguyên vẹn. Ngày nay, lán Khuổi Nặm cùng khu vực xung quanh được phục dựng và bảo tồn trong Khu di tích lịch sử Pác Bó, tỉnh Cao Bằng, là điểm tham quan gắn liền với sự kiện thành lập Mặt trận Việt Minh."},{"t":"Bạn có biết? Cũng tại Hội nghị Trung ương lần thứ tám (5/1941), đồng chí Trường Chinh được bầu giữ chức Tổng Bí thư của Đảng, bên cạnh quyết định thành lập Mặt trận Việt Minh."}],"ban_co_biet":"Cũng tại Hội nghị Trung ương lần thứ tám (5/1941), đồng chí Trường Chinh được bầu giữ chức Tổng Bí thư của Đảng, bên cạnh quyết định thành lập Mặt trận Việt Minh."},{"id":"vintage_oil_lamp@23.1,-18.1","x":23.08,"y":2.24,"z":-18.1,"loai":"vintage_oil_lamp","ten":"Ngọn đèn trong lán","tieu_de":"Tờ báo Việt Nam độc lập ra đời giữa rừng","text":"Sau khi Hội nghị Trung ương lần thứ tám kết thúc ngày 19 tháng 5 năm 1941 với quyết định thành lập Mặt trận Việt Minh, công việc tuyên truyền, vận động quần chúng trở thành nhiệm vụ cấp thiết ở khắp vùng căn cứ Cao Bằng. Chỉ hơn hai tháng sau, ngày 1 tháng 8 năm 1941, tờ báo Việt Nam độc lập do chính Nguyễn Ái Quốc sáng lập đã ra số đầu tiên, trở thành cơ quan tuyên truyền chính thức của Việt Minh tỉnh Cao Bằng.\n\nKhác với những tờ báo chính trị thông thường, Việt Nam độc lập được viết theo lối ngắn gọn, dễ hiểu, nhiều bài trình bày bằng văn vần để đồng bào — kể cả những người ít biết chữ — cũng có thể nghe, nhớ và truyền miệng lại cho nhau. Nội dung báo tập trung vào những vấn đề thiết thực với đời sống người dân vùng cao, đồng thời khéo léo lồng ghép tinh thần yêu nước, kêu gọi đoàn kết chống Pháp, chống Nhật trong khuôn khổ Mặt trận Việt Minh vừa thành lập.\n\nNhững số báo đầu tiên ấy được các cán bộ cơ sở bí mật mang đi phổ biến tới từng bản làng trong vùng căn cứ, trở thành một trong những kênh tuyên truyền hiệu quả nhất của Việt Minh những năm đầu, sát cánh cùng các tài liệu diễn ca dễ nhớ như Lịch sử nước ta cũng ra đời trong cùng giai đoạn này tại Pác Bó (xem chuyên đề đồ vật “Sách và tài liệu huấn luyện”). Nhờ cách viết ngắn gọn, gần gũi, tờ báo nhanh chóng góp phần mở rộng ảnh hưởng của Việt Minh ra ngoài phạm vi tỉnh Cao Bằng.\n\nPhần lớn những số báo, tài liệu tuyên truyền đầu tiên ấy được viết trong điều kiện hết sức thiếu thốn, ngay trong những chiếc lán đơn sơ dựng giữa rừng như lán Khuổi Nặm — nơi vừa diễn ra Hội nghị Trung ương lần thứ tám ít lâu trước đó. Không có đèn điện, không có bàn làm việc kiên cố, chỉ có một ngọn đèn dầu nhỏ thắp sáng mỗi khi trời tối, những trang bản thảo đầu tiên của tờ báo cách mạng vẫn ra đời đều đặn, phục vụ kịp thời cho công tác vận động quần chúng đang được đẩy mạnh khắp vùng căn cứ.\n\nChỉ trong vài năm ngắn ngủi sau khi ra đời, từ một tờ báo nhỏ lưu hành nội bộ trong vùng căn cứ, hệ thống tuyên truyền của Việt Minh đã góp phần quan trọng chuẩn bị tinh thần cho quần chúng nhân dân trước cao trào Tổng khởi nghĩa. Ngọn đèn dầu nhỏ bé trong lán tre, vì thế, cũng là một chứng nhân thầm lặng cho sự ra đời của cả một nền báo chí cách mạng còn rất non trẻ nhưng đầy sức sống giữa hoàn cảnh chiến tranh, bưng bít thông tin của chính quyền thực dân.\n\nNgọn đèn dầu trưng bày trong lán tại đây là đồ vật minh họa cho điều kiện làm việc gian khổ nhưng bền bỉ ấy của những người làm báo cách mạng đầu tiên giữa núi rừng Cao Bằng, chứ không phải hiện vật gốc còn lưu giữ được. Tờ báo Việt Nam độc lập, cùng nhiều tài liệu tuyên truyền khác ra đời trong giai đoạn 1941 – 1945, hiện được giới thiệu dưới dạng tư liệu, bản sao tại Bảo tàng Hồ Chí Minh và một số bảo tàng lịch sử cách mạng trong nước.","nguon":"Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","doc":[{"t":"Tờ báo Việt Nam độc lập ra đời giữa rừng. Sau khi Hội nghị Trung ương lần thứ tám kết thúc ngày 19 tháng 5 năm 1941 với quyết định thành lập Mặt trận Việt Minh, công việc tuyên truyền, vận động quần chúng trở thành nhiệm vụ cấp thiết ở khắp vùng căn cứ Cao Bằng. Chỉ hơn hai tháng sau, ngày 1 tháng 8 năm 1941, tờ báo Việt Nam độc lập do chính Nguyễn Ái Quốc sáng lập đã ra số đầu tiên, trở thành cơ quan tuyên truyền chính thức của Việt Minh tỉnh Cao Bằng."},{"t":"Khác với những tờ báo chính trị thông thường, Việt Nam độc lập được viết theo lối ngắn gọn, dễ hiểu, nhiều bài trình bày bằng văn vần để đồng bào — kể cả những người ít biết chữ — cũng có thể nghe, nhớ và truyền miệng lại cho nhau. Nội dung báo tập trung vào những vấn đề thiết thực với đời sống người dân vùng cao, đồng thời khéo léo lồng ghép tinh thần yêu nước, kêu gọi đoàn kết chống Pháp, chống Nhật trong khuôn khổ Mặt trận Việt Minh vừa thành lập."},{"t":"Những số báo đầu tiên ấy được các cán bộ cơ sở bí mật mang đi phổ biến tới từng bản làng trong vùng căn cứ, trở thành một trong những kênh tuyên truyền hiệu quả nhất của Việt Minh những năm đầu, sát cánh cùng các tài liệu diễn ca dễ nhớ như Lịch sử nước ta cũng ra đời trong cùng giai đoạn này tại Pác Bó (xem chuyên đề đồ vật “Sách và tài liệu huấn luyện”). Nhờ cách viết ngắn gọn, gần gũi, tờ báo nhanh chóng góp phần mở rộng ảnh hưởng của Việt Minh ra ngoài phạm vi tỉnh Cao Bằng."},{"t":"Phần lớn những số báo, tài liệu tuyên truyền đầu tiên ấy được viết trong điều kiện hết sức thiếu thốn, ngay trong những chiếc lán đơn sơ dựng giữa rừng như lán Khuổi Nặm — nơi vừa diễn ra Hội nghị Trung ương lần thứ tám ít lâu trước đó. Không có đèn điện, không có bàn làm việc kiên cố, chỉ có một ngọn đèn dầu nhỏ thắp sáng mỗi khi trời tối, những trang bản thảo đầu tiên của tờ báo cách mạng vẫn ra đời đều đặn, phục vụ kịp thời cho công tác vận động quần chúng đang được đẩy mạnh khắp vùng căn cứ."},{"t":"Chỉ trong vài năm ngắn ngủi sau khi ra đời, từ một tờ báo nhỏ lưu hành nội bộ trong vùng căn cứ, hệ thống tuyên truyền của Việt Minh đã góp phần quan trọng chuẩn bị tinh thần cho quần chúng nhân dân trước cao trào Tổng khởi nghĩa. Ngọn đèn dầu nhỏ bé trong lán tre, vì thế, cũng là một chứng nhân thầm lặng cho sự ra đời của cả một nền báo chí cách mạng còn rất non trẻ nhưng đầy sức sống giữa hoàn cảnh chiến tranh, bưng bít thông tin của chính quyền thực dân."},{"t":"Ngọn đèn dầu trưng bày trong lán tại đây là đồ vật minh họa cho điều kiện làm việc gian khổ nhưng bền bỉ ấy của những người làm báo cách mạng đầu tiên giữa núi rừng Cao Bằng, chứ không phải hiện vật gốc còn lưu giữ được. Tờ báo Việt Nam độc lập, cùng nhiều tài liệu tuyên truyền khác ra đời trong giai đoạn 1941 – 1945, hiện được giới thiệu dưới dạng tư liệu, bản sao tại Bảo tàng Hồ Chí Minh và một số bảo tàng lịch sử cách mạng trong nước."},{"t":"Bạn có biết? Tờ báo Việt Nam độc lập ra số đầu tiên ngày 1 tháng 8 năm 1941, chỉ hơn hai tháng sau khi Mặt trận Việt Minh được thành lập tại Hội nghị Trung ương lần thứ tám."}],"ban_co_biet":"Tờ báo Việt Nam độc lập ra số đầu tiên ngày 1 tháng 8 năm 1941, chỉ hơn hai tháng sau khi Mặt trận Việt Minh được thành lập tại Hội nghị Trung ương lần thứ tám."}]};
